  },
  Skill_117315_Desc_3 = {
    Text = "Gây  <Damage:[Damage:Arg1]> Sát Thương, nhận 3 tầng <ZuiyinKeywords:Tội Ấn>. Sau khi sử dụng lá này, đặt nó lên đầu Bộ Bài Rút. Lần thứ 3 sử dụng sẽ <DepleteIconKeywords:Tiêu Thụ> và khiến Thẻ Lệnh tiếp theo của Pollux nhận hiệu ứng «Cứu Thánh» và có hiệu lực 2 lần."
  },
  Skill_117315_Name = {Text = "Tim Thánh"},
  Skill_117315_tempBattleDesc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương, nhận 3 lớp<ZuiyinKeywords:Dấu ấn tội lỗi>. Sau khi chơi, Xáo trộn thẻ bài này vào đầu rút bài từ bộ bài. Khi chơi lần thứ 3<DepleteIconKeywords:tiêu thụ> và khiến thẻ lệnh tiếp theo của bản thân được hưởng hiệu ứng \"Cứu chuộc đau đớn\" ([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_2 = {
    Text = "([Arg2]/3) Gây  <Damage:[Damage:Arg1]> Sát Thương, nhận 3 tầng <ZuiyinKeywords:Tội Ấn>. Sau khi sử dụng lá này, đặt nó lên đầu Bộ Bài Rút. Lần thứ 3 sử dụng sẽ <DepleteIconKeywords:Tiêu Thụ> và khiến Thẻ Lệnh tiếp theo của Pollux nhận hiệu ứng «Cứu Thánh» và có hiệu lực 2 lần."
  },
  Skill_117315_tempBattleDesc_3 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương và gây [Arg3]% Chảy máu, nhận 3 lớp<ZuiyinKeywords:Dấu ấn tội lỗi>. Sau khi chơi, Xáo trộn thẻ bài này vào đầu rút bài từ bộ bài. Khi chơi lần thứ 3<DepleteIconKeywords:tiêu thụ> và khiến thẻ lệnh tiếp theo của bản thân được hưởng hiệu ứng \"Cứu chuộc đau đớn\" ([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_4 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương và áp [Arg3]% chảy máu, nhận 3 lớp<ZuiyinKeywords:Ấn Tội>. Sau khi đánh sẽ xáo lá bài này vào đầu bộ bài rút. Lần đánh thứ 3 sẽ <DepleteIconKeywords:tiêu hao> và khiến lá chỉ lệnh tiếp theo của bản thân được hưởng hiệu ứng \"Cứu Chuộc Khổ Đau\" và kích hoạt 2 lần([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_5 = {
    Text = "Gây <Damage:[Damage:Arg1]> sát thương và áp dụng [Arg3]% Chảy Máu, nhận 3 tầng <ZuiyinKeywords:Tội Ấn>. Sau khi đánh ra, xáo lá bài này vào đầu chồng rút bài, tiêu hao tính lực trong lượt này trở thành 0 và áp dụng <BleedingIconKeywords:Chảy Máu> bằng 100% sát thương. Khi đánh ra lần thứ 3, <DepleteIconKeywords:tiêu hao> và khiến lá bài chỉ lệnh tiếp theo của bản thân được hưởng hiệu ứng \"Cứu Chuộc Khổ Đau\" và kích hoạt 2 lần ([Arg2]/3)."
  },
  Skill_117316_AwakerSkillBackgroundStory = {
    Text = "Trái tim sáng chói này sẽ xua đuổi tà ác khỏi người anh."
  },
  Skill_117316_BattleDesc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> Lá Chắn. nhận <Energy:[Energy:Arg3]> Aliemus."
  },
  Skill_117316_Desc_0 = {
    Text = "Nhận được <Block:[Block:Arg1]> Lá Chắn. Pollux nhận được <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_117316_EffectNameList = {
    Text = "Lá Chắn, Aliemus"
  },
  Skill_117316_Name = {Text = "Thủ"},
  Skill_117316_PropertyNameList = {
    Text = "Phòng Thủ*GrowValue1,$GrowValue2"
  },
  Skill_117317_AwakerSkillBackgroundStory = {
    Text = "\"Polux, thánh tâm của ngươi đang thực hiện ánh sáng của người giữ đèn, ngươi phải trân trọng vinh quang này như tôn kính Ngài.\"\nVậy là hắn đội chiếc vương miện hư vô đó lên đầu, không dám lơ là. \n \"Polux, đừng sợ, ngươi hãy thử xem vị tự do là gì...\"\nHắn vì vinh quang mà có được tất cả, nhưng cũng vì vinh quang mà mất đi tất cả. Vì thế hắn nhận ra rằng chiếc vương miện này chỉ là gông cùm vô hình. \nHắn đã xé bỏ vương miện, trái tim trống rỗng ấy lần đầu tiên phát ra ánh sáng rực rỡ như ban ngày, chỉ là những tiếng thét giận dữ đau thương không thể nào truyền đến tai một người khác."
  },
  Skill_117317_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> Sát Thương cho tất cả kẻ địch, làm cho Thẻ Lệnh tiếp theo trong lượt này của Pollux nhận được hiệu ứng \"Cứu Thánh\". Đặt 1 thẻ <DerivativeCardKeywords_118: Tim Thánh> vào tay."
  },
  Skill_117317_EffectNameList = {
    Text = "Sát Thương, Aliemus"
  },
  Skill_117317_Name = {
    Text = "Ánh Sáng Vô Tội Trời Ban"
  },
  Skill_117317_OverLimitUtlSkillDesc = {
    Text = "Gây <Damage:[Damage:Arg1]>Sát Thương cho tất cả kẻ địch, khiến Thẻ Lệnh tiếp theo trong lượt của Pollux nhận được hiệu ứng \"Cứu Thánh\". Đặt 2 lá <DerivativeCardKeywords_118: Tim Thánh> vào tay. Trong lượt này, mỗi Thẻ Lệnh của Pollux được hưởng thêm 50% hiệu ứng \"Cứu Thánh\", Thẻ Lệnh tiếp theo của Pollux sẽ kích hoạt thêm 1 lần."
  },
  Skill_117317_PropertyNameList = {
    Text = "Tấn công*GrowValue1"
  },
  Skill_117318_AwakerSkillBackgroundStory = {
    Text = "Trước đây, đôi mắt của anh bị bóng tối che phủ. Vì thế nên ngày đêm với anh đều như một. \nGiờ đây, khi đã chứng kiến được sự thật của thế giới, anh quay lưng và bước đi trên con đường ngược lại. \nChỉ có thể anh mới ngộ ra, từng bước chân dù có lạc lõng của mình đều được dẫn lối bởi ánh sáng ."
  },
  Skill_117318_Desc_0 = {
    Text = "Pollux nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Khi đánh ra và sau giai đoạn bỏ bài nhận được 3 tầng <ZuiyinKeywords:Tội Ấn>, mỗi 1 lá bài trên tay nhận thêm 1 tầng <ZuiyinKeywords:Tội Ấn>.\"Thánh Tâm\" gây xuất huyết bằng 100% sát thương."
  },
  Skill_117318_Desc_15 = {
    Text = "Pollux nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Khi đánh ra và sau giai đoạn bỏ bài nhận được 3 tầng <ZuiyinKeywords:Tội Ấn>, mỗi 1 lá bài trên tay nhận thêm 1 tầng <ZuiyinKeywords:Tội Ấn>.\"Thánh Tâm\" gây xuất huyết bằng 100% sát thương, sau khi đánh ra và xáo vào bộ rút bài, lá\"Thánh Tâm\"đó trong lượt này có tiêu hao toán lực trở thành 0 và gây <BleedingIconKeywords:Xuất Huyết> bằng 100% sát thương."
  },
