  },
  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "Cô ấy kiêu ngạo. Cô ấy dùng sự kiêu ngạo để che giấu những khoảng trống trong lòng không thể sửa chữa. \n Cô ấy quên mất mình đã từng là ai, cô ấy quên mất mình nên là ai. \n Vô số tín đồ lặn lội tôn thờ dưới chân cô, và trong những tiếng tôn kính đó, cô đã quên mất điều quan trọng nhất - \n cô đã hoàn toàn phục tùng số phận nhạt nhẽo này."
  },
  Skill_119763_BattleDesc = {
    Text = "Nhận 2 điểm tính toán, rút 2 lá bài. Khi bắt đầu vòng tiếp theo sẽ nhận [Arg3] điểm <SacrificeKeyWord:hy sinh>. <RippleKeywords:dịch chuyển>: Xóa [Arg4] điểm <SacrificeKeyWord:hy sinh>."
  },
  Skill_119763_Desc = {
    Text = "Nhận 2 điểm số học, rút 2 lá bài. Vào đầu lượt tiếp theo, chịu [Arg1]% của máu tối đa bởi <SacrificeKeyWord:hiến tế>. <RippleKeywords:Hậu tác động>: Xóa [Float:Arg2]% máu tối đa bởi <SacrificeKeyWord:hiến tế>."
  },
  Skill_119763_EffectNameList = {
    Text = "Xóa tỷ lệ hy sinh"
  },
  Skill_119763_Name = {
    Text = "Thánh ca đại dương sâu thẳm"
  },
  Skill_119763_PropertyNameList = {
    Text = "$GrowValue1%"
  },
  Skill_119764_AwakerSkillBackgroundStory = {
    Text = "Nguồn gốc của bức tượng ngà voi trong tay Muphí có nhiều ý kiến khác nhau. \n Có người nói rằng bức tượng đó xuất phát từ một di tích dưới đáy biển mà Muphí chỉ dẫn để khám phá, cũng có người nói rằng bức tượng đó được sinh ra từ trái tim đang nhảy múa trong ngực cô. \n Nhưng không thể nghi ngờ, bức tượng này, biểu trưng cho mối liên hệ vô số giữa cô và thành phố Loài Ốc tĩnh lặng dưới đáy biển tối tăm, đã xuất hiện trong tầm mắt của những người dấn thân vào biển vào ngày Muphí trở thành \"mẹ thần thực sự\". \n Sau đó, các tín đồ cũng đã chứng kiến Muphí sử dụng bức tượng ngà này để phá vỡ sóng gió, cắt đứt biển máu. \n Quyền lực tuyệt đối, thường không chỉ dừng lại ở những biểu tượng hư ảo. Gối của nhân loại chỉ có thể quỳ dưới quyền uy của sức mạnh tuyệt đối."
  },
  Skill_119764_BattleDesc = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên, khi bắt đầu vòng tiếp theo sẽ nhận [Arg7] điểm <SacrificeKeyWord:hy sinh>. Gây áp dụng [Arg3] lớp <DwmofeiKeywords:lễ cấy ghép> cho tất cả kẻ thù, gây [Arg4] lần <Damage:[Damage:Arg5]> điểm sát thương cho kẻ thù có sinh lực cao nhất, nhận được [Arg6]% <TentacleInjurieIconKeywords:thiệt hại xúc tu> gia tăng."
  },
  Skill_119764_Desc = {
    Text = "Nhận <Block:[Block:Arg1]> điểm Khiên, trong lượt sau nhận <SacrificeKeyWord:hy sinh> với số % sinh lực tối đa [Arg2]. Áp dụng [Arg3] lớp <DwmofeiKeywords:giáng sinh nghi lễ> lên tất cả kẻ thù, gây ra [Arg4] lần <Damage:[Damage:Arg5]> điểm sát thương lên kẻ thù có sinh lực cao nhất, nhận [Arg6]% <TentacleInjurieIconKeywords:thiệt hại xúc tu> gia tăng."
  },
  Skill_119764_EffectNameList = {
    Text = "Khiên, lớp nghi thức tái sinh, sát thương, tăng cường thiệt hại xúc tu"
  },
  Skill_119764_Name = {
    Text = "Công chúa hư vô"
  },
  Skill_119764_OverLimitUtlSkillDesc = {
    Text = "Nhận <Block:[Block:Arg1]> điểm Khiên, trong lượt sau nhận [Arg7] điểm <SacrificeKeyWord:hy sinh>. Áp dụng [Arg8] lớp <DwmofeiKeywords:giáng sinh nghi lễ> lên tất cả kẻ thù, gây ra [Arg4] lần <Damage:[Damage:Arg5]> điểm sát thương lên kẻ thù có sinh lực cao nhất, nhận [Arg6]% <TentacleInjurieIconKeywords:thiệt hại xúc tu> gia tăng. Đặt 3 lá tiêu hao điểm tính toán là 2 của \"Vòng khiêu vũ\" vào tay và làm cho nó nhận <DepleteIconKeywords:tiêu hao> và <PrepareKeypvewords1:chuẩn bị1>."
  },
