  },
  Skill_119765_AwakerSkillBackgroundStory = {
    Text = "Cô ấy là người nhẹ dạ. Cô ấy dùng sự nhẹ dạ để chống lại thực tại tàn tạ. \n Hãy để chúng ta khiêu vũ, cô nói, nhảy một điệu múa dâng tặng cho thần thánh. \n Cảm ơn thần thánh đã ban cho chúng ta những nguyên nhân sai lầm, quá khứ lộn xộn, và tương lai khó nắm bắt. \n Dưới ánh đèn sân khấu, cô ấy là tâm điểm duy nhất của mọi thứ."
  },
  Skill_119765_BattleDesc = {
    Text = "Nhận <Posse:[Arg7]> điểm năng lượng chìa khóa bạc. Nhận hiệu ứng khác nhau tùy theo tư thế xúc tu: \"Thủy triều\": <TentacleInjurieIconKeywords:thiệt hại xúc tu> +[TentaclePower:Arg1], tạo ra 1 xúc tu. \"Biển lặng\": Nhận <Block:[Block:Arg2]> điểm Khiên, giữ lại 50% Khiên đến lượt sau. \"Sóng gẩm\": Gây ra [Arg3] lần <Damage:[Damage:Arg4]> điểm sát thương lên kẻ thù có sinh lực cao nhất, nhận [Arg5]% <TentacleInjurieIconKeywords:thiệt hại xúc tu> gia tăng."
  },
  Skill_119765_Desc = {
    Text = "Nhận [Arg6]% năng lượng chìa khóa bạc đã sạc. Nhận hiệu ứng khác nhau tùy theo tư thế xúc tu: \"Thủy triều\": <TentacleInjurieIconKeywords:thiệt hại xúc tu> +[TentaclePower:Arg8], tạo ra 1 xúc tu. \"Biển lặng\": Nhận <Block:[Block:Arg9]> điểm Khiên, giữ lại 50% Khiên đến lượt sau. \"Sóng gẩm\": Gây ra [Arg3] lần <Damage:[Damage:Arg4]> điểm sát thương lên kẻ thù có sinh lực cao nhất, nhận [Arg5]% <TentacleInjurieIconKeywords:thiệt hại xúc tu> gia tăng."
  },
