  Skill_119766_AwakerSkillBackgroundStory = {
    Text = "Cô ấy đã nhỏ giọt máu cuống rốn của thần xuống biển. Cô cầu nguyện với thần về con đường không bao giờ đến đích. \n Chỉ cần bọt mơ vẫn tiếp tục tồn tại, cô là thần mẫu duy nhất."
  },
  Skill_119766_Desc_0 = {
