  },
  Skill_122485_Desc_15 = {
    Text = "Mocha nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>:\"Cuộc Gặp Gỡ Kịch Tính\" số lần sát thương +2. Giới hạn kích hoạt mỗi lượt tăng lên 5. Mỗi lần kích hoạt \"Cuộc Gặp Gỡ Kịch Tính\" khiến sát thương cuối cùng tạm thời của \"Đả Kích\" Mocha +25%. Lập tức tạo 2 lá\"Nhân Gian Bộc Phá\" tạm thời với tiêu hao toán lực là 0."
