  },
  Skill_125372_Name_1 = {
    Text = "Sợi sen khó giết"
  },
  Skill_125373_AwakerSkillBackgroundStory = {
    Text = "Tại sao phải quyến rũ chúng? Chúng vốn đã không có sức phản kháng. \n Tại sao phải xúi giục chúng? Đến khi cao hơn, rộng hơn, vòng xoáy quyền lực sẽ bao trùm tất cả những gì có thể nhìn thấy. \n Bởi vì chỉ có những kẻ bình thường bị mắc kẹt trong tình cảm mới khó nuốt trôi. Bởi vì thân thể tầm thường chưa được ướp muối tham vọng thật nhạt nhẽo. \n Không mơ quê là phần thưởng của kẻ săn mồi dành cho con mồi còn sót lại. \n Trung tâm của hạnh phúc không có bất kỳ thứ gì, chỉ có sự hỗn loạn vô tận, sự xảo trá vô tận."
  },
  Skill_125373_Desc_0 = {
    Text = "Tuần nhận <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Lần đầu tiên mỗi loại thẻ lệnh của Tuần kích hoạt hiệu ứng <ResonanceKeywords:cộng hưởng> trong mỗi lượt, Giá trị Điểm tính toán cơ bản của nó sẽ trở thành 0."
  },
  Skill_125373_Desc_15 = {
    Text = "Tuần nhận <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Lần đầu tiên mỗi loại thẻ lệnh của Tuần kích hoạt hiệu ứng <ResonanceKeywords:cộng hưởng> trong mỗi lượt, Giá trị Điểm tính toán cơ bản của nó sẽ trở thành 0. Giới hạn chồng chất của <WitherKeywords0:Say mê> tăng lên 15 lớp, thẻ lệnh đầu tiên Tuần chơi mỗi lượt có hiệu lực thêm 1 lần."
