  },
  Skill_126486_AwakerSkillBackgroundStory = {
    Text = "Nàng nhân danh vận mệnh, tại đây tuyên cáo——\nMọi số mệnh sai lầm, sẽ chìm vào cát bụi thời gian. Vận mệnh thế giới, sẽ trở về quỹ đạo đã định.\nNhững sợi tơ rối loạn, tại đây bị cắt đứt. Kẻ bất hạnh bị ruồng bỏ, sẽ yên nghỉ nơi đây."
  },
  Skill_126486_Desc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm lá chắn, khuếch đại sát thương tạm thời +[Arg2]%, loại bỏ trạng thái <SlowIconKeywords:Trì trệ> của tất cả tay bài."
  },
  Skill_126486_EffectNameList = {
    Text = "Khiên,Hiệu Lực Sát Thương,Phán Quyết Định Mệnh Vô Tận"
  },
  Skill_126486_Name = {
    Text = "Mệnh Đồ, Y Thử Dụ Thị"
  },
  Skill_126486_OverLimitUtlSkillDesc = {
    Text = "Nhận <Block:[Block:Arg1]> điểm lá chắn, khuếch đại sát thương tạm thời +[Arg2]%, loại bỏ trạng thái <SlowIconKeywords:Trì trệ> của tất cả tay bài. Tạo ra tối đa 5 Bản gốc tạm thời của thẻ bài <SingularityKeywords1:Ngọn hải đăng kỳ điểm> trong tay và khoảng không gian siêu việt, đặt chúng ngẫu nhiên vào rút bài từ bộ bài và rác bài và làm cho Giá trị Điểm tính toán tiêu tốn của chúng trở thành 0."
  },
  Skill_126486_PropertyNameList = {
    Text = "Phòng ngự*GrowValue1,$GrowValue2%, Tấn công*GrowValue3"
  },
  Skill_126488_BattleDesc_0 = {
    Text = "Mất [Float:Arg3]% sinh mệnh tối đa([Arg4]), nhận 1 tầng <SilkKeywords:Dệt Mệnh>. Trong trận đấu này, sinh mệnh mất từ \"<DerivativeCardKeywords_138:Kéo Chỉ Dẫn Mệnh>\" và <CutKeywords:Phán Quyết Định Mệnh> do Arachne gây ra tăng [Arg2]%. Hư Vô: Arachne nhận ngẫu nhiên 15~30 điểm Cuồng Khí."
  },
  Skill_126488_Desc_0 = {
    Text = "Mất [Arg1]% sinh mệnh tối đa, nhận 1 tầng <SilkKeywords:Dệt Mệnh>. Trong trận đấu này, sinh mệnh mất từ \"<DerivativeCardKeywords_138:Kéo Chỉ Dẫn Mệnh>\" và <CutKeywords:Phán Quyết Định Mệnh> do Arachne gây ra tăng [Arg2]%. Hư Vô: Arachne nhận ngẫu nhiên 15~30 điểm Cuồng Khí."
  },
  Skill_126488_Name = {
    Text = "Khiên Tơ Dẫn Mệnh"
  },
  Skill_126490_AwakerSkillBackgroundStory = {
    Text = "Khoảnh khắc bức màn kéo lên, những con rối ngẩng đầu, nhìn thấy gương mặt dịu dàng phía sau guồng quay.\nSợi tơ căng thẳng, giữa tiếng ca và điệu múa của những con rối, nàng mỉm cười như một người mẹ.\nTrên sân khấu vận mệnh, nàng là khán giả duy nhất của chúng."
  },
  Skill_126490_BattleDesc_0 = {
    Text = "Arachne nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>:\"Sự diệt vong\" chuyển thành chọn 1 thẻ bài khoảng không gian siêu việt để lấy ra, trao cho \"lần chơi tiếp theo có hiệu lực thêm 1 lần\", khiến thẻ lệnh được chơi tiếp theo kích hoạt <SingularityKeywords3:Xuyên chiều>."
  },
  Skill_126490_BattleDesc_15 = {
    Text = "Arachne nhận <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: \"Sự diệt vong\" đổi thành chọn lấy 1 thẻ lệnh từ Khoảng không gian siêu việt, trao cho \"Có hiệu lực thêm 1 lần sau khi chơi lần tiếp theo\", khiến thẻ lệnh tiếp theo được chơi kích hoạt <SingularityKeywords3:Xuyên Không Chiều Không Gian>. Sau khi tung \"Sự diệt vong\" lập tức gây <FixedDamage:Sát Thương Thuần Túy> tương đương 50% \"Phán Quyết Mệnh Vận\" lên tất cả kẻ địch, Khuếch đại sát thương và lá chắn của lần Bùng nổ tiếp theo tăng 50%."
  },
  Skill_126490_Desc_0 = {
    Text = "Arachne nhận [Arg2]% Cuồng Khí cơ bản. <ExaltIconKeywords:Linh Tri Giác Tỉnh>:\"Hủy Diệt\" thay đổi thành chọn 1 lá chỉ lệnh từ Không Gian Siêu Chiều lấy ra, phú cho \"lần đánh ra tiếp theo kích hoạt thêm 1 lần\", khiến lá chỉ lệnh tiếp theo được đánh ra kích hoạt <SingularityKeywords3:Xuyên Chiều>."
  },
  Skill_126490_Desc_15 = {
    Text = "Arachne nhận [Arg2]% căn bản điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: \"Sự diệt vong\" đổi thành chọn lấy 1 thẻ lệnh từ Khoảng không gian siêu việt, trao cho \"Có hiệu lực thêm 1 lần sau khi chơi lần tiếp theo\", khiến thẻ lệnh tiếp theo được chơi kích hoạt <SingularityKeywords3:Xuyên Không Chiều Không Gian>. Sau khi tung \"Sự diệt vong\" lập tức gây <FixedDamage:Sát Thương Thuần Túy> tương đương 50% \"Phán Quyết Mệnh Vận\" lên tất cả kẻ địch, Khuếch đại sát thương và lá chắn của lần Bùng nổ tiếp theo tăng 50%."
  },
