  },
  Skill_130351_Desc = {
    Text = "Sau giai đoạn rút bài, nếu có trong tay, chơi 1 thẻ lệnh ngẫu nhiên và làm cho nó có hiệu lực 2 lần. \n Sau khi đánh ra, thẻ lệnh tiếp theo sẽ có hiệu lực thêm 2 lần. Sau khi đánh [Arg1] lần sẽ tiêu thụ ([Arg2]/[Arg1])."
  },
  Skill_130351_Name = {Text = "Rối dây"},
  Skill_130385_Desc = {
    Text = "Sau giai đoạn rút bài, nếu có trong tay, chọn 1 thẻ lệnh ngẫu nhiên từ 2 thẻ trong tay và chơi nó, làm cho nó có hiệu lực 2 lần. \n Sau khi đánh ra, tiêu thụ sức tính toán của thẻ lệnh tiếp theo sẽ giảm 2 điểm, thẻ lệnh đã đánh sẽ có hiệu lực thêm 2 lần. Sau khi đánh [Arg1] lần sẽ tiêu thụ ([Arg2]/[Arg1])."
  },
  Skill_130385_Name = {Text = "Rối dây"},
  Skill_130386_Desc = {
    Text = "Sau giai đoạn rút bài, nếu có trong tay, chọn 1 thẻ lệnh ngẫu nhiên từ 2 thẻ lệnh trong tay và buộc phải chơi nó, và làm cho nó có hiệu lực 2 lần. \n Sau khi chơi, thẻ lệnh tiếp theo được chơi sẽ có hiệu lực thêm 2 lần. Sau khi chơi [Arg1] lần, tiêu hao ([Arg2]/[Arg1])."
  },
  Skill_130386_Name = {Text = "Rối dây"},
  Skill_130471_Desc = {
