  Skill_130476_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [AttackTimes:Arg2] lần, nhận được [Arg3] <PowerIconKeywords:lực lượng>, loại bỏ khe nứt chiều."
