  Skill_130476_Name = {
    Text = "Bi ca vượt qua số mệnh"
  },
  Skill_130477_Desc = {
    Text = "Khi chuyển sang ý định này, xóa bỏ\"Khế Ước Trói Thề\" và <Chapter5_Monster_Fervor4:cuồng nhiệt>, xóa sạch các đồng đội khác. Sinh lực hiện tại và tối đa của bản thân tăng 250%, tổng lượng \"Tàn Tro Cũ\" nhân đôi, nhận 50 lớp \"Sương Khiên Ăn Mòn\", mở\"Khe Nứt Chiều Không Gian\"."
  },
  Skill_130477_Name = {
