  Skill_130479_Desc = {
    Text = "Chuyển sang ý định này, gây [Arg1] lớp<BleedingIconKeywords:Chảy máu>. Áp dụng [Arg2] lớp<WeaknessIconKeywords:Suy nhược>, <VulnerabilityIconKeywords:Trọng thương>. Nếu số lượng thẻ bài trong khe nứt chiều lớn hơn [Arg3], sẽ thêm [Arg4] lớp<FragileIconKeywords:mong manh>, <BlindingKeywords:Mù>, <Decay:mục nát>."
