  },
  Skill_130513_Desc_1 = {
    Text = "<PVPWeaponKeywords:Mệnh Luân>: Khi trang bị và đầu lượt, kích hoạt ngẫu nhiên một trong các hiệu quả sau: Nhận <Energy:[Energy:Arg1]> Cuồng Khí và <PVPSlowKeywords:Trì Hoãn> bản thân; Nhận <Energy:[Energy:Arg3]> Cuồng Khí; Nhận <Energy:[Energy:Arg4]> và [Arg5] lá <PVPDerivativeCardKeywords_17:「Linh Cảm」>."
  },
  Skill_130513_Name_1 = {
    Text = "Trí tuệ của cuộc đánh bạc lớn"
  },
  Skill_130928_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> sát thương cho toàn bộ kẻ địch. Nếu không hạ gục mục tiêu, nhận [Arg2] tầng <PVPWaterPowerKeyWords:Dòng Xoáy>."
  },
  Skill_130928_Name_1 = {
    Text = "Hố sâu! Vortex! Đại tấn công"
  },
  Skill_130929_AwakerSkillBackgroundStory = {
    Text = "Vung vẩy khẩu pháo khổng lồ một cách năng động, nhảy nhót bước vào chiến trường. \n Không quan tâm đến phiền phức, không quan tâm đến nguy hiểm, vì những điều này so với bạn bè, thật là không đáng kể. \n \"Bạn bè, phiền toái! Mosk, xuất hiện!\""
  },
  Skill_130929_BattleDesc_0 = {
    Text = "Mosk nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Rút 1 thẻ\"Gắn đầy\". Sau khi Mosk phát động truy đuổi, lần bùng nổ điên cuồng tiếp theo của Mosk sẽ được hưởng thêm [Arg2]% tăng thương tổn xúc tu, tối đa cộng dồn [Arg3] lần."
  },
  Skill_130929_BattleDesc_15 = {
    Text = "Mosk nhận <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Rút 1 thẻ \"Gắn đầy\". Sau khi Mosk tung đòn Truy đuổi, lần Bùng nổ tiếp theo của Mosk được hưởng thêm [Arg2]% Tăng thương tổn xúc tu, và khiến lần Bùng nổ tiếp theo gây <FixedDamage:Sát Thương Thuần Túy> bằng [Arg4]% sinh lực tối đa lên kẻ địch có sinh lực cao nhất, tối đa chồng [Arg3] lần."
  },
  Skill_130929_Desc_0 = {
    Text = "Moss nhận [Arg5]% Cuồng Khí cơ bản. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Rút 1 lá\"Nạp Đạn!\". Sau khi Moss tung truy kích, lần bùng phát Cuồng Khí tiếp theo của Moss nhận thêm [Arg2]% gia thành sát thương xúc tu, tối đa cộng dồn [Arg3] lần."
  },
  Skill_130929_Desc_15 = {
    Text = "Mosk nhận [Arg5]% căn bản điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Rút 1 thẻ \"Gắn đầy\". Sau khi Mosk tung đòn Truy đuổi, lần Bùng nổ tiếp theo của Mosk được hưởng thêm [Arg2]% Tăng thương tổn xúc tu, và khiến lần Bùng nổ tiếp theo gây <FixedDamage:Sát Thương Thuần Túy> bằng [Arg4]% sinh lực tối đa lên kẻ địch có sinh lực cao nhất, tối đa chồng [Arg3] lần."
  },
  Skill_130929_EffectNameList = {
    Text = "Điên cuồng, tăng thương tổn xúc tu"
  },
  Skill_130929_Name = {
    Text = "Vortex đã đến!"
  },
  Skill_130929_PropertyNameList = {
    Text = "$GrowValue1,$GrowValue2%"
  },
  Skill_130930_Desc_1 = {
    Text = "<PVPWeaponKeywords:vòng mệnh>:\"Bùng nổ\" sau khi giúp bản thân nhận được <Block:[Block:Arg1]> lá chắn và <DelayKeywords:Trì hoãn>: <Energy:[Energy:Arg2]> điên cuồng."
  },
  Skill_130930_Name_1 = {
    Text = "Vườn địa đàng xa xôi"
  },
  Skill_130931_AwakerSkillBackgroundStory = {
    Text = "Vortex mang đến sự tàn phá, hố sâu mang đến sự hủy diệt.\nCô gái khao khát tình bạn và ánh nắng cuối cùng vẫn quay trở lại sự cô đơn vĩnh cửu.\nKhóc và la hét, than khóc, sự biến dạng, sụp đổ, là vòng lặp mà cô ấy trải qua khi ở trong Mosk.\nĐây là tiếng gầm gừ của hố sâu dưới Mosk tiêu thụ mọi thứ.\nCũng là minh chứng cho việc Mosk đánh bại Ngài."
  },
  Skill_130931_BattleDesc_0 = {
    Text = "Xua tan trạng thái <BurningKeywords:đốt cháy> của tất cả thẻ bài trong tay. Gây ra <Damage:[Damage:Arg1]> điểm sát thương cho tất cả kẻ địch, gây ra sát thương gấp đôi cho kẻ địch có sinh lực cao nhất. Hy sinh tối đa 3 xúc tu vĩnh viễn bổ sung([Arg4] cái), mỗi cái làm sát thương chí mạng của lần bùng nổ này tăng +50%(tỉ lệ chí mạng hiện tại: [Arg5]%. Tăng thương tổn xúc tu: [Arg8]%)."
  },
  Skill_130931_BattleDesc_1 = {
    Text = "Xua tan trạng thái <BurningKeywords:đốt cháy> của tất cả thẻ bài trong tay. Gây <Damage:[Damage:Arg1]> điểm sát thương cho tất cả kẻ địch, gây gấp đôi sát thương cho kẻ địch có sinh lực cao nhất. Hy sinh tối đa 3 xúc tu vĩnh viễn bổ sung([Arg4] cái), mỗi cái làm tăng sát thương chí mạng của cơn bùng nổ này thêm 50%(tỉ lệ chí mạng hiện tại: [Arg5]%. Tăng thương tổn xúc tu: [Arg8]%). Nhận [Arg6] điểm sự thông thạo giới vực."
  },
  Skill_130931_BattleDesc_3 = {
    Text = "Xóa bỏ trạng thái <BurningKeywords:đốt cháy> của tất cả thẻ bài trong tay. Gây ra <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ thù, gây gấp ba lần thương cho kẻ thù có sinh lực cao nhất. Hy sinh tối đa 3 xúc tu vĩnh viễn bổ sung([Arg4] cái), mỗi cái làm tăng sát thương chí mạng của lần bùng nổ này thêm 50%(tỉ lệ chí mạng hiện tại: [Arg5]%. Tăng thương tổn xúc tu: [Arg8]%). Nhận [Arg6] điểm sự thông thạo giới vực, mỗi khi tiêu hao 20 điểm điên cuồng sẽ khiến các thể thức tỉnh khác nhận 1 điểm điên cuồng."
  },
  Skill_130931_Desc_0 = {
    Text = "Xua tan trạng thái <BurningKeywords2:đốt cháy> của tất cả thẻ bài trong tay. Gây sát thương cộng thêm [Arg7]% <TentacleInjurieIconKeywords:thương tổn xúc tu> cho tất cả kẻ địch, gây sát thương gấp đôi cho kẻ địch có sinh lực cao nhất. Hy sinh tối đa 3 xúc tu vĩnh viễn bổ sung, mỗi xúc tu làm tăng sát thương chí mạng của cơn điên cuồng này thêm 50%."
  },
  Skill_130931_Desc_1 = {
    Text = "Giải tán trạng thái <BurningKeywords2:đốt cháy> của tất cả thẻ bài trong tay. Gây sát thương với [Arg7]% <TentacleInjurieIconKeywords:thương tổn xúc tu> gia tăng cho tất cả kẻ địch, gây gấp đôi sát thương cho kẻ địch có sức sống cao nhất. Hy sinh tối đa 3 xúc tu vĩnh viễn bổ sung, mỗi xúc tu sẽ tăng sát thương chí mạng của cơn thịnh nộ này thêm 50%. Nhận [Arg6] điểm sự thông thạo giới vực."
  },
  Skill_130931_Desc_3 = {
    Text = "Xua tan trạng thái <BurningKeywords2:đốt cháy> của tất cả thẻ bài trong tay. Gây sát thương cộng thêm [Arg7]% <TentacleInjurieIconKeywords:thương tổn xúc tu> cho tất cả kẻ địch, gây gấp ba lần sát thương cho kẻ địch có sinh lực cao nhất. Hy sinh tối đa 3 xúc tu vĩnh viễn bổ sung, mỗi xúc tu tăng sát thương chí mạng của cơn thịnh nộ này thêm 50%. Nhận [Arg6] điểm sự thông thạo giới vực, mỗi khi tiêu hao 20 điểm điên cuồng sẽ khiến các thể thức tỉnh khác nhận được 1 điểm điên cuồng."
  },
  Skill_130931_EffectNameList = {
