  Skill_130931_Name = {
    Text = "Hố sâu! Vortex! Pháo!"
  },
  Skill_130931_OverLimitUtlSkillDesc = {
    Text = "Xua tan trạng thái <BurningKeywords:Thiêu Đốt> của tất cả lá bài trên tay. Gây <Damage:[Damage:Arg1]> điểm sát thương lên tất cả kẻ địch, gây sát thương gấp ba lên kẻ địch có sinh mệnh cao nhất. Hy sinh tối đa 3 xúc tu vĩnh cửu bổ sung([Arg4] sợi), mỗi sợi tăng sát thương bạo kích của lần bùng nổ Cuồng Khí này +100%(Tỷ lệ bạo kích hiện tại: [Arg5]%. Gia tăng sát thương xúc tu: [Arg8]%). Nhận [Arg6] điểm Giới Vực Tinh Thông. 5 lần \"Oa! Lưu! Đạn!\" tiếp theo kích hoạt 2 lần."
  },
  Skill_130931_PropertyNameList = {
