  Skill_130940_Name = {Text = "Đánh·2"},
  Skill_130941_Desc_1 = {
    Text = "<PVPWeaponKeywords:Vòng mệnh>: Sau lần đầu tiên chơi \"Kỹ Năng\" trong mỗi lượt, gây <Damage:[Damage:Arg1]> thương lên kẻ địch có <HPAndShieldMin:Sinh lực và lá chắn thấp nhất>."
