  Skill_130941_Name_1 = {
    Text = "Điên rồ bị giam cầm"
  },
  Skill_130942_AwakerSkillBackgroundStory = {
    Text = "Kể từ khi trong một thí nghiệm, Mosk đã học được cách tiết kiệm lực lượng, thì sự tàn phá mà nó gây ra bắt đầu tăng gấp bội. \n Vì vậy, khi xung quanh Mosk bắt đầu xuất hiện độ ẩm bất thường, hãy ngay lập tức giữ khoảng cách với kẻ thù. \n Theo lời Mosk nói——\"Đầu tiên tích lũy lực, sau đó phóng ra, sức mạnh lớn!\"."
  },
  Skill_130942_Desc = {
    Text = "Nhận <Energy:[Energy:Arg1]> điểm điên cuồng, tỉ lệ chí mạng bùng nổ của Mosk trong lần tiếp theo +[Arg2]%. <RippleKeywords:Sóng dư chấn>: Các thể thức tỉnh khác nhận được <Energy:[Energy:Arg3]> điểm điên cuồng."
