  },
  Skill_131192_Desc = {
    Text = "Giảm Giá trị Điểm tính toán của tất cả thẻ bài trên tay có <ErosionColorInkKeywords:Nhận thức hỗn loạn> -1, mỗi thẻ như vậy khiến Thể thức tỉnh có điên cuồng thấp nhất nhận <Energy:5> điểm điên cuồng, sau đó hoàn nguyên các thẻ bài có <ErosionColorInkKeywords:Nhận thức hỗn loạn> ở mọi nơi. Trong lượt này sau khi chơi thẻ bài sẽ không còn gắn <ErosionColorInkKeywords:Nhận thức hỗn loạn> cho các thẻ bài khác."
  },
  Skill_131192_Name = {
    Text = "Sự thật cấm kỵ"
  },
  Skill_131241_Desc = {
    Text = "Người chơi nhận được [Power:Arg1] điểm <PowerIconKeywords:lực lượng>, <Block:[Block:Arg2]> điểm lá chắn, [Heal:Arg3] điểm hồi phục, [TentaclePower:Arg4] điểm <TentacleInjurieIconKeywords:thương tổn xúc tu>, [Counterattack:Arg5] lớp <RetaliateIconKeywords:phản công>, gây <Damage:[Damage:Arg6]> điểm thương cho kẻ địch ở hàng đầu [Arg7] lần, [Poison:Arg8] lớp <IntoxicationIconKeywords:ngộ độc>, áp dụng [Exhaustion:Arg9] lớp <ExhaustionIconKeywords:hấp thụ>."
  },
  Skill_131241_Name = {
    Text = "Pháo cầu vồng β"
  },
  Skill_131365_Desc = {
    Text = "Gây sát thương theo phần trăm sinh mệnh lên kẻ địch, đồng thời phá hủy Không Gian Siêu Chiều của chúng."
  },
  Skill_131365_Name = {
    Text = "Sợi Mệnh An Vị"
  },
  Skill_131438_Desc = {
    Text = "Sau giai đoạn rút bài, nếu có trong tay, chọn 1 thẻ lệnh ngẫu nhiên từ 2 thẻ trong tay và chơi nó, làm cho nó có hiệu lực 2 lần. \n Sau khi đánh ra, chi phí sức tính toán của thẻ lệnh tiếp theo giảm xuống 0, thẻ lệnh đã đánh ra sẽ có hiệu lực thêm 2 lần. Sau khi đánh [Arg1] lần sẽ tiêu thụ ([Arg2]/[Arg1])."
  },
  Skill_131438_Name = {Text = "Rối dây"},
  Skill_131654_Desc = {
    Text = "Sau khi chơi, xóa bỏ giá trị điên cuồng của thể thức tỉnh chỉ định, sau đó khiến nó nhận được giá trị điên cuồng gấp 1 lần giá trị điên cuồng cơ bản."
  },
  Skill_131654_Name = {
    Text = "Điên cuồng được nhân đôi 1 lần"
  },
  Skill_131786_Desc = {
    Text = "Chơi xong, gây [Damage:Arg1] điểm thương cho mục tiêu ngẫu nhiên, gây [Damage:Arg2] điểm thương cho kẻ địch khác."
  },
  Skill_131786_Name = {
    Text = "Mục tiêu kiểm tra"
  },
  Skill_131856_AwakerSkillBackgroundStory = {
    Text = "Đôi Mắt, tai, lưỡi, da, não bộ, cảm giác lan khắp toàn thân.\nTình yêu và sự dịu dàng được chia sẻ sẽ mãi mãi bao quanh bạn, cho đến khi chết——"
  },
  Skill_131856_BattleDesc_0 = {
    Text = "Saya nhận được <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Sau khi sử dụng \"Lò nung đỏ thẫm\", gắn thêm <ErosionColorInkKeywords:Nhận thức hỗn loạn> vào các thẻ lệnh không có \"<DestructionKeywords:Hủy hoại>\" của các Thể thức tỉnh khác ở mọi nơi. 3 lần đầu mỗi vòng chơi thẻ lệnh mang <ErosionColorInkKeywords:Nhận thức hỗn loạn> sẽ khiến Saya và Thể thức tỉnh sở hữu thẻ lệnh đó nhận được <Energy:[Energy:Arg2]> điểm Điên loạn."
  },
  Skill_131856_BattleDesc_15 = {
    Text = "Saya nhận được <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Sau khi sử dụng「Lò nung đỏ thẫm」Saya nhận được <Energy:[Energy:Arg4]> điểm Điên loạn và 1 lớp「<KaiHuajishu:Vũ Chủng>」. Gắn thêm <ErosionColorInkKeywords:Nhận thức hỗn loạn> vào các thẻ lệnh của các Thể thức tỉnh khác ở mọi nơi không có「<DestructionKeywords:Hủy hoại>」. 3 lần đầu mỗi lượt chơi thẻ lệnh mang <ErosionColorInkKeywords:Nhận thức hỗn loạn> sẽ khiến Saya và Thể thức tỉnh sở hữu thẻ lệnh đó nhận được <Energy:[Energy:Arg2]> điểm Điên loạn."
  },
  Skill_131856_Desc_0 = {
    Text = "Saya nhận [Arg3]% căn bản điên cuồng. <ExaltIconKeywords:Khai mở linh trí>:Sau khi sử dụng \"Lò nung đỏ thẫm\" gắn thêm <ErosionColorInkKeywords:Nhận thức hỗn loạn> cho thẻ lệnh của các Thể thức tỉnh khác không có\"<DestructionKeywords:Hủy hoại>\". 3 lần đầu mỗi lượt chơi thẻ lệnh có <ErosionColorInkKeywords:Nhận thức hỗn loạn> khiến Saya và Thể thức tỉnh sở hữu thẻ lệnh đó nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_131856_Desc_15 = {
    Text = "Saya nhận [Arg3]% Cuồng khí cơ bản. <ExaltIconKeywords:Khai mở linh trí>:Sau khi sử dụng \"Lò nung đỏ thẫm\" Saya nhận <Energy:[Energy:Arg4]> điểm điên cuồng và 1 tầng <KaiHuajishu:Vũ Chủng>. Gắn thêm <ErosionColorInkKeywords:Nhận thức hỗn loạn> cho thẻ lệnh của các Thể thức tỉnh khác không có\"<DestructionKeywords:Hủy hoại>\". 3 lần đầu mỗi lượt chơi thẻ lệnh có <ErosionColorInkKeywords:Nhận thức hỗn loạn> khiến Saya và Thể thức tỉnh sở hữu thẻ lệnh đó nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_131856_EffectNameList = {
    Text = "Cuồng Khí,Cuồng Khí bổ sung"
