  Skill_131858_AwakerSkillBackgroundStory = {
    Text = "Kinh dị, tươi đẹp, tuyệt vọng, dưới sự xâm nhiễm của \"Tình Yêu\", sinh mệnh rực rỡ ấy cất tiếng ngợi ca Nở Hoa.\nĐây là bài ca tuyên bố màn mở đầu của thế giới mới, tấu lên hồi kết của thế giới cũ."
  },
  Skill_131858_BattleDesc = {
    Text = "【<DevouredIconKeywords:Nuốt chửng> :Ngẫu nhiên 2 bản sao \"Đánh cơ bản\" hoặc \"Phòng thủ cơ bản\" có tiêu hao toán lực trở thành 0 và có hiệu lực thêm 1 lần.】Nhận <Block:[Block:Arg1]> điểm khiên. Chọn một Giác Tỉnh Thể khác, thêm vào bộ rút bài và bộ bỏ bài mỗi nơi một bộ bản sao gốc thẻ chỉ lệnh của Giác Tỉnh Thể đó, đồng thời gắn thêm <NothingnessIconKeywords:Hư vô> và <DestructionKeywords:Tiêu hủy>. Tiêu hao tất cả <KaiHuajishu:Vũ chủng>, mỗi tầng tiêu hao khiến ngẫu nhiên 1 lá \"Kỹ năng\" trong đó có tiêu hao toán lực trở thành 0."
  },
  Skill_131858_Desc = {
    Text = "【<DevouredIconKeywords:Nuốt chửng> :Ngẫu nhiên 2 bản sao \"Đánh cơ bản\" hoặc \"Phòng thủ cơ bản\" có tiêu hao toán lực trở thành 0 và có hiệu lực thêm 1 lần.】Nhận <Block:[Block:Arg1]> điểm khiên. Chọn một Giác Tỉnh Thể khác, thêm vào bộ rút bài và bộ bỏ bài mỗi nơi một bộ bản sao gốc thẻ chỉ lệnh của Giác Tỉnh Thể đó, đồng thời gắn thêm <NothingnessIconKeywords:Hư vô> và <DestructionKeywords:Tiêu hủy>. Tiêu hao tất cả <KaiHuajishu:Vũ chủng>, mỗi tầng tiêu hao khiến ngẫu nhiên 1 lá \"Kỹ năng\" trong đó có tiêu hao toán lực trở thành 0."
  },
  Skill_131858_EffectNameList = {Text = "lá chắn"},
  Skill_131858_Name = {
