  },
  Skill_132425_AwakerSkillBackgroundStory = {
    Text = "Cô gái rời khỏi thủy cung đã phá sản với nỗi lưu luyến, như một phần thưởng cho công việc, cô được phép mang về nhà vài con sứa. \n Đây là những sinh linh nhỏ bé mà cô yêu thích nhất, linh hồn của biển cả, hoa nảy nở sinh sôi. \n Chỉ cần chăm sóc cẩn thận, chúng sẽ lấp đầy cả bể cá! — Cô từng mong đợi cảnh tượng như vậy."
  },
  Skill_132425_Desc_0 = {
    Text = "Aurita nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Đánh thức>：Nhận 1 xúc tu, đưa 2 thẻ \"Tách tế bào\" vào tay. Khi Aurita gây sát thương, khiến [Arg2] xúc tu tấn công 1 lần."
  },
  Skill_132425_Desc_15 = {
    Text = "Ô Ryta nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Nhận 1 xúc tu, đưa 2 thẻ \"Phân chia tuyến\" vào tay. Khi Ô Ryta gây thương, khiến [Arg2] xúc tu tấn công 1 lần. \"Đánh\" của Ô Ryta trở thành sát thương xuyên thấu và gây thêm 2 lần sát thương."
  },
