  Skill_132431_AwakerSkillBackgroundStory = {
    Text = "\"Nhìn này! Ô Ryta phun bong bóng như một con cá!\""
  },
  Skill_132431_BattleDesc_0 = {
    Text = "Nhận được <Block:[Block:Arg1]> điểm lá chắn. Nhận được <Energy:[Energy:Arg2]> điểm khí điên cuồng."
  },
  Skill_132431_BattleDesc_3 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên, rút 1 thẻ. Nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_132431_Desc_0 = {
    Text = "<Block:[Block:Arg1]> điểm lá chắn đã được kích hoạt. Ô Ryta tích lũy thêm <Energy:[Energy:Arg2]> điểm cuồng nộ."
  },
  Skill_132431_Desc_3 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên, rút 1 thẻ. Aurita nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_132431_EffectNameList_0 = {
    Text = "Lá chắn, điên cuồng"
  },
  Skill_132431_Name = {
    Text = "Test·Phòng Thủ"
  },
  Skill_132431_PropertyNameList_0 = {
    Text = "Khả năng phòng thủ*GrowValue1,$GrowValue2"
  },
  Skill_132432_AwakerSkillBackgroundStory = {
    Text = "Trẻ em sẽ từ từ nhìn thấu bản chất của những câu chuyện cổ tích, hiểu được những ẩn dụ đằng sau huyền thoại. Trong ngôn ngữ của con người, quá trình này được gọi là \"trưởng thành\". \nNhưng cũng có những đứa trẻ càng tin vào những câu chuyện trước khi đi ngủ, chúng kiên trì cho rằng trên trời thật sự có cầu vồng, thật sự có những nền văn minh chìm sâu dưới biển sâu. \nÔ Ryta thích những câu chuyện này, cô ấy muốn chia sẻ niềm vui này với nhiều người bạn hơn."
  },
  Skill_132432_Desc_0 = {
    Text = "<TentacleInjurieIconKeywords:Thiệt hại xúc tu> +[TentaclePower:Arg1]. Bỏ hết bài trên tay, rút số lượng bài tương đương. Trộn 1 lá bài \"Tuyến thể phân bào\" vào chồng bài bỏ."
  },
  Skill_132432_Desc_1 = {
    Text = "<TentacleInjurieIconKeywords:Thiệt hại xúc tu> +[TentaclePower:Arg1]. Bỏ hết bài trên tay, rút số lượng bài tương đương +1. Trộn 1 lá bài \"Tuyến thể phân bào\" vào chồng bài bỏ."
  },
  Skill_132432_EffectNameList = {
    Text = "Thương tổn xúc tu, \"chia tách tuyến\" cấp độ"
  },
  Skill_132432_Name = {
    Text = "Test·Kỹ năng 2"
  },
  Skill_132432_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1,$GrowValue2"
  },
  Skill_132433_AwakerSkillBackgroundStory = {
    Text = "Trên thế giới tồn tại một loại sứa đặc biệt, khi bị thương, mô bị rụng của nó có thể phát triển lại thành một cơ thể sứa hoàn chỉnh. \n \"Ô Ryta cũng sinh sứa! Vậy nên Ô Ryta cũng là sứa!\"\nỞ giai đoạn này của việc trẻ em nhận thức về thế giới, đừng làm mất hứng thú của cô ấy."
  },
  Skill_132433_Desc_0 = {
    Text = "Gây ra <Damage:[Damage:Arg1]> điểm sát thương. Trộn [Arg2] thẻ \"Tuyến Phân Liệt\" vào chồng bài bỏ.<RippleKeywords:Hậu quả>: Nhận <Energy:[Energy:Arg3]> điểm Aliemus."
  },
  Skill_132433_Desc_2 = {
    Text = "Gây ra <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:Thiệt hại xuyên thấu>. Sắp [Arg2] thẻ \"Tuyến phân chia\" vào chồng bài bỏ. <RippleKeywords:Thời tiết>: Nhận <Energy:[Energy:Arg3]> điểm aliemus."
  },
