  Skill_132498_Name = {Text = "Giao"},
  Skill_132884_Desc_1 = {
    Text = "<PVPWeaponKeywords:Mệnh Luân>: Khi trang bị nhận được [Arg1] <StrongEffectKeywords:cường hiệu>, sau khi đồng đội khác Cuồng Khí Bộc Phát sẽ khiến họ nhận được <PVPOneMeetingKeywords:Nhất Kỳ Nhất Hội>."
