  Skill_133322_Name_1 = {Text = "Đánh"},
  Skill_133323_BattleDesc_1 = {
    Text = "Gây <Damage:[Damage:Arg4]> sát thương lên kẻ địch hàng trước, mỗi [Arg2] sinh mệnh đã mất sát thương +[Arg3], bản thân hồi phục lượng sinh mệnh tương đương."
  },
  Skill_133323_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> sát thương lên địch hàng trước, mỗi [Arg2] sinh mệnh đã mất thì sát thương +[Arg3], bản thân hồi phục lượng sinh mệnh tương đương."
  },
  Skill_133323_Name_1 = {
    Text = "Cướp đoạt"
  },
  Skill_133324_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> sát thương lên toàn bộ địch và áp dụng <PVPCognitiveDissonanceKeyWords:Nhận Thức Hỗn Loạn>."
  },
  Skill_133324_Name_1 = {
    Text = "Bài hát của Sa Ya"
  },
  Skill_133325_BattleDesc_1 = {
    Text = "Chọn một đồng minh, cho họ nhận <Heal:[Heal:Arg4]> <PVPFeatheredSeedsKeyWords:Vũ Chủng> và lượng Sinh lực tương đương, mỗi khi tiêu thụ [Arg2] Điểm tính toán, <PVPFeatheredSeedsKeyWords:Vũ Chủng> và lượng Sinh lực tương đương tăng thêm [Arg3]."
  },
  Skill_133325_Desc_1 = {
    Text = "Chọn một đồng đội, khiến mục tiêu nhận được <Heal:[Heal:Arg1]> <PVPFeatheredSeedsKeyWords:Vũ Chủng> và lượng sinh mệnh tương đương, mỗi [Arg2] toán lực tiêu hao, <PVPFeatheredSeedsKeyWords:Vũ Chủng> và lượng sinh mệnh tương đương tăng thêm [Arg3]."
  },
  Skill_133325_Name_1 = {Text = "Phát Tán"},
  Skill_133346_Desc_1 = {
    Text = "Gây <PVPSeriousInjuryKeywords:Thiệt hại nặng>, <PVPPenetrateKeywords:Xuyên thấu>, <DelayKeywords:Trì hoãn>: Hồi phục sinh lực <Heal:[Heal:Arg1]> cho toàn bộ đồng minh, mỗi [Arg2] lá chắn bị <PVPSeriousInjuryKeywords:Thiệt hại nặng> phá vỡ hoặc <DelayKeywords:Trì hoãn> chữa trị, lượng Hồi phục sinh lực +[Arg3]."
  },
  Skill_133346_Name_1 = {
    Text = "Dâng tặng thế giới mới"
  },
  Skill_133346_UnknownName = {
    Text = "Dâng tặng thế giới mới"
  },
  Skill_133347_Desc_1 = {
    Text = "<PVPWeaponKeywords:Vòng mệnh>: Vòng mệnh này được giữ lại sau khi chết. Khi người trang bị chết và sau [Arg2] lượt tiếp theo trong trạng thái đã chết, các đồng minh khác nhận <Heal:[Heal:Arg1]> <PVPFeatheredSeedsKeyWords:Vũ Chủng> và sinh lực."
  },
  Skill_133347_Name_1 = {
    Text = "Nguyện thế giới hóa thành hương thơm"
  },
  Skill_133348_Desc_1 = {
    Text = "<PVPWeaponKeywords:Mệnh Luân>: Sau khi trang bị, không thể nhận biết mô tả\"Đả Kích\",\"Kỹ Năng\",\"Cuồng Khí Bộc Phát\" của người trang bị, nhưng mỗi lần sát thương, khiên, hồi phục được tăng ngẫu nhiên [Arg1]%~[Arg2]%."
  },
  Skill_133348_Name_1 = {
    Text = "Cổ tích trong bùn lầy"
  },
  Skill_133365_AwakerSkillBackgroundStory = {
    Text = "Nàng đã từng nghe vô số lần tiếng sợi tơ đứt gãy.\nMột cuộc trùng phùng chưa từng xảy ra. Một lời tỏ tình chưa từng thốt ra. Một đứa trẻ chưa từng chào đời.\nMột bản nhạc chưa từng ra mắt. Một cuộc chiến chưa từng chiến thắng. Một nền văn minh chưa từng sống sót.\nSợi tơ đan dệt. Sợi tơ đứt gãy. Sợi tơ hòa trở lại tấm lưới khổng lồ.\nVị thần của vận mệnh đã sớm biết, không gì thực sự diệt vong, không gì từng thực sự tồn tại."
  },
  Skill_133365_Desc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm lá chắn, các thể thức tỉnh khác nhận <Energy:[Energy:Arg2]> điểm điên cuồng, lần tiếp theo \"<DerivativeCardKeywords_138:Khung Cửi Vĩnh Hằng>\" sẽ tạo ra \"<DerivativeCardKeywords_138:Sợi Tơ Định Mệnh>\" thêm vào bộ rút bài và bộ bài bỏ."
  },
  Skill_133365_EffectNameList = {
    Text = "Lá chắn, điên cuồng"
  },
  Skill_133365_Name = {
    Text = "Lưới Trói Mệnh"
  },
  Skill_133365_PropertyNameList = {
    Text = "Khả năng phòng thủ*GrowValue1,$GrowValue2"
  },
  Skill_133366_AwakerSkillBackgroundStory = {
    Text = "Từ ngày đầu tiên nàng chào đời, nàng đã nhìn thấy những sợi tơ vận mệnh lan rộng.\nDọc theo quỹ đạo của sợi tơ, nàng bước qua cánh cửa, lĩnh nhận số phận vô tận của một tù nhân.\nSợi tơ xuyên qua guồng quay mang tên Moirai, xuyên qua thành trì và eo biển, xuyên qua lời thề và dối trá, xuyên qua mỗi linh hồn tưởng rằng mình đang đưa ra lựa chọn.\nTrong ảo cảnh tự do này, guồng quay xoay chuyển, vĩnh hằng không ngừng."
  },
  Skill_133366_Desc_0 = {
    Text = "Gây [FateCut:Arg1] điểm<CutKeywords:Số phận Cắt đứt> cho tất cả kẻ thù, tạo ra 1 lá bài \"<DerivativeCardKeywords_138:Sợi Tơ Định Mệnh>\"để vào tay<SilkKeywords1:>"
  },
  Skill_133366_EffectNameList = {
    Text = "Phán Quyết Vận Mệnh"
  },
