  Skill_142695_AwakerSkillBackgroundStory = {
    Text = "Hắn giữ lại những phần sống động và thú vị nhất của những người thân yêu nhất, hắn ban cho kẻ thù những cực hình thảm khốc và kéo dài nhất.\nMỗi đêm chén chú chén anh, hắn cười lớn rồi chìm vào biển cả tạo thành từ những xác thân trống rỗng."
  },
  Skill_142695_BattleDesc = {
    Text = "Xóa trạng thái <ExhaustionIconKeywords:sức mạnh giảm xuống> của bản thân. Tạm thời giảm [Exhaustion:Arg1] điểm <ExhaustionIconKeywords:Sức mạnh> của tất cả kẻ địch. Gây <RealDamage:sát thương cố định> tương đương [Arg2]% thương tổn xúc tu( [Arg3] ) cho kẻ địch có sinh lực thấp nhất, nếu Giết chúng thì vĩnh viễn tạo 1 lá \"Giam Mộng Quỷ\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> đặt vào tay, mỗi trận tối đa vĩnh viễn tạo 3 lá."
  },
  Skill_142695_Desc = {
    Text = "Xóa bỏ Trạng thái <ExhaustionIconKeywords:sức mạnh giảm xuống> của bản thân. Tạm thời giảm [Exhaustion:Arg8] điểm <ExhaustionIconKeywords:lực lượng> của tất cả kẻ thù. Gây <RealDamage:Sát thương cố định> tương đương [Arg2]% thương tổn xúc tu lên kẻ thù có Sinh lực thấp nhất, nếu Giết được kẻ đó sẽ tạo ra 1 thẻ \"Giam Mộng Quỷ\" vĩnh viễn <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:>đưa vào tay, mỗi trận chiến tạo tối đa 3 thẻ \"Giam Mộng Quỷ\" vĩnh viễn."
  },
  Skill_142695_EffectNameList = {
    Text = "Giảm sức mạnh tạm thời,Tăng thương tổn xúc tu,Cấp độ Giam Mộng Quỷ"
  },
