  Skill_142700_AwakerSkillBackgroundStory = {
    Text = "\"Bạn muốn gì?\"\nSức mạnh, trật tự, lấy lại những gì đã mất, lấy máu rửa thù…\nHắn chìm vào im lặng lâu dài và u ám, nhưng thực ra hắn đã có câu trả lời từ lâu, một câu trả lời không có lời giải.\nHắn muốn mặt trời mọc đằng đông lặn đằng tây, hắn muốn mọi thứ như thường."
  },
  Skill_142700_BattleDesc_0 = {
    Text = "Pontos nhận <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Cứ mỗi 3 thẻ \"Giam Mộng Quỷ\"<BattueKeywords:> trong bộ bài, \"Chuyến Săn Bất Tận\" nhận thêm 1 lớp Bầy Đàn. Mỗi lần chơi 1 thẻ bài của Pontos, hiệu ứng giảm sức mạnh tạm thời của lần dùng \"Chuyến Săn Bất Tận\" tiếp theo tăng [Arg3]%, mỗi lượt tối đa kích hoạt 3 lần."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Pontos nhận <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Cứ mỗi 2 thẻ \"Giam Mộng Quỷ\" trong bộ bài, \"Chuyến Săn Bất Tận\" nhận thêm 1 tầng <BattueKeywords:Bầy Đàn>. Mỗi lần chơi 1 thẻ bài của Pontos, hiệu ứng giảm sức mạnh tạm thời của \"Chuyến Săn Bất Tận\" lần tiếp theo tăng [Arg3]%, mỗi lượt kích hoạt tối đa 3 lần. Lần đầu \"Đánh\" và lần đầu \"phòng thủ\" mỗi lượt nhận thêm <Energy:[Energy:Arg4]> điểm Điên loạn"
  },
  Skill_142700_Desc_0 = {
    Text = "Pontos nhận [Arg2]% Cuồng khí cơ bản. <ExaltIconKeywords:Khai mở linh trí>: Cứ mỗi 3 thẻ \"Giam Mộng Quỷ\"<BattueKeywords:> trong bộ bài, \"Chuyến Săn Bất Tận\" nhận thêm 1 lớp Bầy Đàn. Mỗi lần chơi 1 thẻ bài của Pontos, hiệu ứng giảm sức mạnh tạm thời của lần dùng \"Chuyến Săn Bất Tận\" tiếp theo tăng [Arg3]%, mỗi lượt tối đa kích hoạt 3 lần."
  },
  Skill_142700_Desc_15 = {
    Text = "Pontos nhận [Arg2]% Cuồng khí cơ bản. <ExaltIconKeywords:Khai mở linh trí>: Cứ mỗi 2 thẻ \"Giam Mộng Quỷ\" trong bộ bài, \"Chuyến Săn Bất Tận\" nhận thêm 1 tầng <BattueKeywords:Bầy Đàn>. Mỗi lần chơi 1 thẻ bài của Pontos, hiệu ứng giảm sức mạnh tạm thời của \"Chuyến Săn Bất Tận\" lần tiếp theo tăng [Arg3]%, mỗi lượt kích hoạt tối đa 3 lần. Lần đầu \"Đánh\" và lần đầu \"phòng thủ\" mỗi lượt nhận thêm <Energy:[Energy:Arg4]> điểm Điên loạn"
