  Skill_142846_AwakerSkillBackgroundStory = {
    Text = "Tai người và Công nghệ Bạc Tâm hiện có đều tạm thời không thể thu thập bất kỳ thông tin hữu ích nào từ Tiếng Còi săn mồi của Pontos.\nNhưng tất cả các cá thể bị Epoyanth đồng hóa dường như đều rất nhanh chóng Thích Nghi với việc tuân theo chỉ lệnh của Tiếng Còi."
  },
  Skill_142846_Desc = {
    Text = "Nếu là lần đầu tiên sử dụng trong trận chiến này, tạo ra 3 loại \"Giam Mộng Quỷ\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> khác nhau đặt vào tay và nhận <Block:[Block:Arg1]> điểm lá chắn, cứ mỗi 4 lá Giam Mộng Quỷ vĩnh viễn thì nâng cấp 1 lá trong số đó thành \"Song Sinh Mộng Quỷ\". Nếu không thì rút 3 lá \"Giam Mộng Quỷ\"."
  },
  Skill_142846_EffectNameList = {
    Text = "lá chắn,Cấp độ Giam Mộng Quỷ"
  },
  Skill_142846_Name = {
    Text = "Tiếng Còi Điều Khiển Ác Mộng"
  },
  Skill_142846_PropertyNameList = {
    Text = "Khả năng phòng thủ*GrowValue1,$GrowValue2"
  },
  Skill_142847_AwakerSkillBackgroundStory = {
    Text = "Tần suất xuất hiện của Epoyanth không theo quy luật, toàn bộ diện mạo của nó cũng không thể quan sát được.\nĐiều duy nhất được biết đến là, khi những sinh vật vô diện đó thành đàn thành lũ xuất hiện trên bầu trời, một ngôi nhà tỏa ra ánh ngọc kỳ lạ từ bên trong cửa sổ sẽ sừng sững trên vách đá trong màn sương mù nào đó."
  },
  Skill_142847_BattleDesc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương chắc chắn bạo kích lên tất cả kẻ thù. Nhận <Energy:[Energy:Arg2]> điểm Điên loạn. Có hiệu lực thêm X lần."
  },
  Skill_142847_BattleDesc_2 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương chắc chắn bạo kích lên tất cả kẻ thù. Nhận <Energy:[Energy:Arg2]> điểm Điên loạn. Có hiệu lực thêm X+1 lần."
  },
