  Skill_142874_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> thương cho kẻ địch, mất Sinh lực bằng một nửa lượng thương gây ra hoặc cho đồng minh nhận <Block:[Block:Arg2]> lá chắn. Rút [Arg3] thẻ bài."
  },
  Skill_142874_Name_1 = {Text = "Ác mộng"},
  Skill_142875_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> thương cho địch ở hàng trước, nhận <Energy:[Energy:Arg2]> cuồng nộ."
  },
  Skill_142875_Name_1 = {Text = "Đánh"},
  Skill_142876_Desc_1 = {
    Text = "<TauntKeywords:Chế nhạo>, mỗi lần bị Tấn Công sẽ đặt [Arg1] lá <PVPDerivativeCardKeywords_30:\"Ác mộng\"> vào Tay."
  },
  Skill_142876_Name_1 = {
    Text = "Nghi Lễ Lãnh Chúa"
  },
  Skill_142877_Desc_1 = {
    Text = "Chọn bất kỳ mục tiêu nào khác, nếu là đồng minh, bản thân và đồng minh nhận <Block:[Block:Arg1]> lá chắn, trước khi bắt đầu lượt tiếp theo, gánh chịu một nửa thương nhận được thay cho họ; nếu là kẻ địch, trước khi bắt đầu lượt tiếp theo, chuyển giao một nửa thương nhận được."
  },
  Skill_142877_Name_1 = {
    Text = "Vô Nghỉ Liệt Yến"
  },
  Skill_142878_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> thương, nếu điên loạn của mục tiêu nhỏ hơn [Arg2], thì thương tăng gấp đôi, ngược lại gây <PVPEmptinessKeywords:Hư vô>."
  },
  Skill_142878_Name_1 = {
    Text = "Nghệ Thuật Săn Lùng"
  },
  Skill_142879_Desc_1 = {
    Text = "Đặt [Arg1] lá <PVPDerivativeCardKeywords_30:\"Ác mộng\"> vào rút bài từ bộ bài, Rút [Arg2] lá bài."
