  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Vòng mệnh>: Khi đồng đội tử vong, bản thân nhận được <Energy:[Energy:Arg1]> điên cuồng. Khi đồng đội hồi sinh, họ nhận được <Energy:[Energy:Arg2]> điên cuồng. Hiệu ứng nhận điên cuồng chỉ có hiệu lực khi điên cuồng của mục tiêu chưa đầy, tối đa có hiệu lực [Arg8] lần, sau khi hết số lần sẽ hủy hoại vòng mệnh đó."
  },
  Skill_144438_Name_1 = {
    Text = "Đồng Bộ Linh Hồn"
  },
  Skill_144486_AwakerSkillBackgroundStory = {
    Text = "Tiên nữ và phù thủy gặp nhau tại một khoảng đất hoang vắng ở góc làng.\nLúc đó cô đang tươi cười mời chào những đứa trẻ xa lạ ăn mặc sang trọng, còn phù thủy thì lặng lẽ nhắm vào chiếc vòng vàng leng keng trên cổ tay người mẹ.\nÁnh mắt hai người chạm nhau giữa không trung, lập tức hiểu rõ ý định của nhau.\nCuộc đấu trí thầm lặng này, cuối cùng phù thủy nhỉnh hơn một bậc, nhờ kinh nghiệm lão luyện mà giành chiến thắng sít sao.\nNhưng một sự nghiệp lừa lọc, bịp bợm mới mẻ và tươi đẹp, cũng từ đây mà bắt đầu."
  },
  Skill_144486_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Nuốt chửng>: Nhận 1 lớp <WormGrowth1:No Nê>. Mỗi lần gây sát thương áp lên mục tiêu [Corrosion:Arg10] điểm <Corrosion:Xói mòn>.] Xua tan Trạng thái <BurningKeywords2:thiêu đốt> của tất cả bài trên tay. Nhận <Block:[Block:Arg2]> điểm lá chắn. Gây <Damage:[Damage:Arg1]> điểm sát thương cho tất cả kẻ địch [Arg8] lần. Mỗi 1 lớp <WormGrowth1:No Nê> Bùng nổ sát thương cơ bản và Tăng Khiên [Arg6]%. Tiêu thụ tất cả <SacrificialMark1:Lễ Vật>, mỗi lớp làm số lần sát thương +1, và nhận <WormGrowth1:No Nê>. Số lớp <WormGrowth1:No Nê> hiện tại: [Arg9], số lớp tích lũy trong trận chiến này: [Arg11]"
  },
  Skill_144486_BattleDesc_3 = {
