  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "Tham lam là bản chất của con người.\nKhông ai có thể cưỡng lại sức cám dỗ của đường ngọt, ngay cả bản thân tiên nữ giáo mẫu cũng không ngoại lệ.\nCaraboo nhe miệng cười, lộ ra hàm răng nanh đen nhánh."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo nhận <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Sau khi sử dụng \"Lò nung đỏ thẫm\", làm lần \"Phép Màu Tiên Nữ\" tiếp theo giảm Điểm tính toán -3, mỗi lựa chọn <FaxianKeywords:phát hiện> bao gồm thêm 1 lá <DerivativeCardKeywords_152:\"phước lành\">, chọn 1 nhóm đặt vào rút bài từ bộ bài."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo nhận <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Sau khi sử dụng \"Lò nung đỏ thẫm\", làm lần \"Phép Màu Tiên Nữ\" tiếp theo giảm Điểm tính toán -3, mỗi lựa chọn <FaxianKeywords:phát hiện> bao gồm thêm 2 lá <DerivativeCardKeywords_152:\"phước lành\">, chọn 1 nhóm đặt vào rút bài từ bộ bài. Sau khi chơi \"phước lành\", Dung hợp Phôi thai +10, Sinh lực hiện tại càng thấp thì hiệu ứng càng cao, tối đa tăng 100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo nhận [Arg2]% căn bản điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Sau khi sử dụng \"Lò nung đỏ thẫm\", làm lần \"Phép Màu Tiên Nữ\" tiếp theo giảm Điểm tính toán -3, mỗi lựa chọn <FaxianKeywords:phát hiện> bao gồm thêm 1 lá <DerivativeCardKeywords_152:\"phước lành\">, chọn 1 nhóm đặt vào rút bài từ bộ bài."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo nhận [Arg2]% căn bản điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Sau khi sử dụng \"Lò nung đỏ thẫm\", làm lần \"Phép Màu Tiên Nữ\" tiếp theo giảm Điểm tính toán -3, mỗi lựa chọn <FaxianKeywords:phát hiện> bao gồm thêm 2 lá <DerivativeCardKeywords_152:\"phước lành\">, chọn 1 nhóm đặt vào rút bài từ bộ bài. Sau khi chơi <Blessing:Phép Màu>, Dung hợp Phôi thai +10, Sinh lực hiện tại càng thấp thì hiệu ứng càng cao, tối đa tăng 100%."
