  Skill_145562_Desc_1 = {
    Text = "Chọn một kẻ địch, hai bên cùng <PVPLock:Khóa Định> lẫn nhau và gây <Damage:[Damage:Arg1]> thương cho mục tiêu. Nếu mục tiêu chết khi đang <PVPLock:Khóa Định> thì lá bài này trở về tay. <PVPFusion:Dung Hợp>: Sát thương+ [Arg2] ."
  },
  Skill_145562_Name_1 = {
    Text = "Giao Ước Kiếm Sĩ"
  },
  Skill_145612_Desc = {
    Text = "Phép Màu là thẻ tăng cường có Giá trị Điểm tính toán 1, sở hữu <RetainIconKeywords:Giữ lại>, <PrepareKeypvewords:Chuẩn bị>, <DepleteIconKeywords:tiêu hao>. \nKhi chơi sẽ nhận một <Blessing:Món Quà> có <BlessingNegativeEffect:Cái Giá> và 1 lớp <SacrificialMark1:Lễ Vật>. \"Phép Màu\" có 3 loại: \n\"Phép Màu Tức Thời\": Không kích hoạt \"Lỡ Thời Cơ\". \n\"Phép Màu Xa Hoa\": Không kích hoạt \"Lời Giả Tạo\". \n\"Phép Màu Nhân Từ\": Không kích hoạt \"Ý Đồ Xấu\"."
  },
  Skill_145612_Name = {
    Text = "Ban phước"
  },
  Skill_145664_Desc = {
    Text = "Thêm theo công thức [Poison:Arg1] Ngộ độc, [Counterattack:Arg2] phản công, [Power:Arg3] Sức mạnh, [Exhaustion:Arg4] Hấp thụ, [TentaclePower:Arg5] thương tổn xúc tu, [FateCut:Arg6] Phán Quyết Mệnh Vận, [Corrosion:Arg7] Xói mòn."
  },
  Skill_145664_Name = {
    Text = "Thêm trạng thái theo công thức"
  },
  Skill_145673_AwakerSkillBackgroundStory = {
    Text = "\"Con có thấy không? Thịt da của chúng đã nứt toác dưới lưỡi kiếm của con như thế nào, tuôn trào những đóa hoa máu rực rỡ.\"\n\"Đừng ảo tưởng rằng nhắm mắt lại là không còn tồn tại nữa, đứa con thân yêu của ta.\"\n\"Con hiểu rõ điều đó, con biết tường tận.\"\n\"Kỹ năng mà con đã khổ luyện, từ lâu đã nhuốm màu của cái chết, chỉ biết kéo đến tai họa tiếp theo cho người khác.\""
  },
  Skill_145673_BattleDesc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương. nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
