  Skill_145673_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương. Phụ Thệ·Orci nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_145673_Desc_2 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương 2 lần. Phụ Thệ·Orci nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
