  Skill_145673_Name = {Text = "Đánh"},
  Skill_145673_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1,$GrowValue2"
  },
  Skill_145674_AwakerSkillBackgroundStory = {
    Text = "\"Con có nghe thấy không? Tiếng than khóc của chúng đã vang vọng khắp mọi ngóc ngách như thế nào, nhưng chẳng ai dang tay che chở cho chúng dù chỉ một phần.\"\n\"Đừng tưởng bịt tai lại là có thể làm ngơ, gã hiệp sĩ bất tài.\"\n\"Con đã từng trải qua, con đã từng lựa chọn.\"\n\"Khi làn sóng kẻ thù ập đến, con tháo giáp bỏ chạy, mặc chúng giày xéo mảnh đất mà con yêu thương nhất.\""
  },
  Skill_145674_BattleDesc = {
    Text = "Nhận được <Block:[Block:Arg1]> điểm lá chắn. Nhận được <Energy:[Energy:Arg2]> điểm khí điên cuồng."
  },
  Skill_145674_Desc = {
    Text = "Nhận <Block:[Block:Arg3]> điểm lá chắn. Phụ Thệ·Orci nhận <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_145674_EffectNameList = {
    Text = "Lá chắn, điên cuồng"
