  Skill_145674_PropertyNameList = {
    Text = "Khả năng phòng thủ*GrowValue1,$GrowValue2"
  },
  Skill_145675_AwakerSkillBackgroundStory = {
    Text = "Thực ra, Orci từ lâu đã quên mất hình dáng thật sự của tòa lâu đài đó.\nNhưng giờ đây, hắn có thể dựa vào ước nguyện trong lòng để xây dựng nên những bức tường thành mới.\nNếu dưới sự bảo vệ của hắn, người ta vẫn có thể nghe thấy tiếng cười vui của mọi người, những bông hoa quen thuộc cũng sẽ lại nở rộ khắp cánh đồng......\nThì trái tim đã biến dị từ lâu đó, vẫn còn ý nghĩa để tồn tại trên đời này."
  },
  Skill_145675_BattleDesc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm lá chắn, nhận [Power:Arg2] điểm <PowerIconKeywords:sức mạnh> , tiêu thụ tất cả <KuangNu:Ám Dũng>, mỗi lớp tiêu thụ làm tăng lá chắn và sức mạnh gây ra thêm 33%, nhận 1 lớp <ShuZui:Tự Tội>."
