  Skill_145676_AwakerSkillBackgroundStory = {
    Text = "Khi mỗi hiệp sĩ được phong tước và tuyên thệ, thanh kiếm bên mình cũng được phủ lên ánh hào quang.\nNhưng thanh bạc thương đầu tiên của hắn, được trao cho sứ mệnh thiêng liêng, từ lâu đã tan chảy trong tàn tro của lửa chiến.\nDù sao, đã là kẻ mang tội, thì hãy để lớp bùn đen tội lỗi này trở thành vũ khí mới. Hắn nghĩ, như vậy, dù có vấy thêm nhiều máu, cũng sẽ không còn làm nhục người xưa nữa."
  },
  Skill_145676_BattleDesc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương, hưởng [Arg2]% tăng sức mạnh, nhận 1 lớp <KuangNu:Ám Dũng>."
