  Skill_145676_Name = {
    Text = "Súng Nhuốm Tội"
  },
  Skill_145676_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1"
  },
  Skill_145677_AwakerSkillBackgroundStory = {
    Text = "Ngày xưa, cậu thiếu niên cũng đã từng thử tách lớp bùn đen邪ác đó ra khỏi bản thân, nhưng dù cậu làm gì — dùng tay xé, dùng vật sắc bén cắt, dùng vật cùn đập......cơn ác mộng vô hình đó vẫn luôn ám ảnh không tan, thậm chí ngày càng lấn tới.\nCuối cùng, cậu đành thừa nhận rằng cậu và Nó từ lâu đã hoàn toàn Hợp nhất thành một, không còn phân biệt được nữa.\nNó đã hóa thành bóng tối của cậu."
  },
  Skill_145677_BattleDesc_0 = {
    Text = "Phụ Thệ·Orci nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Lần đầu tiên mỗi lượt \"Mũi Thương Nhuốm Tội\" của Phụ Thệ·Orci gây sát thương sẽ áp <Corrosion:Xói mòn> tương đương. Lá chắn của \"Phòng Thủ\" tăng 50%, Rút 1 lá bài."
  },
  Skill_145677_BattleDesc_15 = {
    Text = "Phụ Thệ·Orci nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Lần đầu tiên mỗi lượt \"Mũi Thương Nhuốm Tội\" của Phụ Thệ·Orci gây sát thương sẽ áp <Corrosion:Xói mòn> tương đương. Sát thương cơ bản của \"Mũi Thương Nhuốm Tội\" tăng 100%, hưởng thêm 200% hệ số sức mạnh. Lá chắn của \"Phòng Thủ\" tăng 100%, Rút 1 lá bài."
  },
  Skill_145677_Desc_0 = {
    Text = "Phụ Thệ·Orci nhận được [Arg2]% căn bản điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Lần đầu tiên mỗi lượt \"Mũi Thương Nhuốm Tội\" của Phụ Thệ·Orci gây sát thương sẽ áp <Corrosion:Xói mòn> tương đương. Lá chắn của \"Phòng Thủ\" tăng 50%, Rút 1 lá bài."
