  Skill_145678_AwakerSkillBackgroundStory = {
    Text = "Trong đợt kiểm tra định kỳ của Misaque, các nhà nghiên cứu đã chuyên tâm nghiên cứu khối vật chất đen vô định hình đó.\nĐiều bất ngờ là, họ thực sự đã chiết xuất được một số thành phần vật chất từ đó, và lập tức tiến hành thí nghiệm lần thứ hai, nhưng kết quả thu được lại hoàn toàn khác biệt.\nDường như tương ứng với đặc tính vô định hình mà nó thể hiện, các thành phần cấu thành nó cũng thay đổi từng giây từng phút, tựa như ảo ảnh hư vô mơ hồ.\nVật vô hình, căn nguyên vốn là vô hình."
  },
  Skill_145678_Desc = {
    Text = "Tạm thời giảm [Exhaustion:Arg1] điểm <ExhaustionIconKeywords:sức mạnh> của tất cả kẻ thù, nhận [Power:Arg2] điểm <PowerIconKeywords:sức mạnh>. Kích hoạt thêm X lần. X tối đa là 5."
