  Skill_146011_AwakerSkillBackgroundStory = {
    Text = "Đường cung của Kiếm Xương mãi mãi thong thả và thanh thoát.\nNghiêm túc vung ra từng nhát kiếm, đó là sự tôn trọng lớn nhất của cô ấy dành cho đối thủ, dành cho chính cuộc chiến."
  },
  Skill_146011_BattleDesc_0 = {
