  Skill_146012_Desc = {
    Text = "Không thể đánh ra. Khi Trong Tay thẻ này, thương do tất cả kẻ địch gây ra tăng lên 25%, toàn bộ thẻ lệnh của Lotan: Ngư Thần đều biến đổi thành <DerivativeCardKeywords_154:\"Tử Chiến\">, khi bắt đầu lượt Rút 1 thẻ <DerivativeCardKeywords_154:\"Tử Chiến\">."
  },
  Skill_146012_Name = {
    Text = "Đại Kiếm: Kình Lạc"
  },
  Skill_146013_AwakerSkillBackgroundStory = {
    Text = "Chỉ rất ít, rất ít lần, Rotan mới thu lại kiếm của mình.\nĐôi mắt dị sắc đang lạnh lùng quan sát. Thu thế, mãi mãi chỉ là để ra kiếm tốt hơn."
  },
  Skill_146013_BattleDesc_0 = {
    Text = "Nhận được <Block:[Block:Arg1]> điểm lá chắn. Nhận được <Energy:[Energy:Arg2]> điểm khí điên cuồng."
  },
  Skill_146013_BattleDesc_2 = {
