  Skill_146013_EffectNameList = {
    Text = "Lá chắn, điên cuồng"
  },
  Skill_146013_Name = {
    Text = "Phòng thủ"
  },
  Skill_146013_PropertyNameList = {
    Text = "Khả năng phòng thủ*GrowValue1,$GrowValue2"
  },
  Skill_146014_AwakerSkillBackgroundStory = {
    Text = "Mảnh xương sọ nặng nề và cứng nhất của Leviathan được mài thành trường đao, cô ấy gọi nó là \"Vẫn\".\nTrọng kiếm vung ngang, đường cung của lưỡi kiếm như vây đuôi cá voi khổng lồ vẫy động, xương trắng nặng nề nghiền nát tất cả những gì trước mặt cô ấy.\nHãy uống Máu Tươi của ta, gặm nhấm Sinh lực của ta đi, Rotan nói.\nRồi, hãy để tất cả sinh linh, đều rơi xuống trong Quỹ đạo Không Thể Cản của ngươi."
  },
  Skill_146014_Desc = {
    Text = "Gây [Arg3] lần <Damage:[Damage:Arg1]> điểm thương lên toàn bộ kẻ địch, hưởng [Arg2]% bonus Sức mạnh, được coi là \"Đánh\". Mỗi khi chơi 1 thẻ \"Đánh\" trong lượt này, Giá trị Điểm tính toán của \"Trường Kiếm: Diệt\" được chơi tiếp theo -1."
  },
  Skill_146014_EffectNameList = {
    Text = "Sát thương"
  },
  Skill_146014_Name = {
    Text = "Trường Kiếm: Diệt"
  },
  Skill_146014_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1"
  },
  Skill_146015_AwakerSkillBackgroundStory = {
    Text = "Leviathan mãi mãi ghi nhớ dáng vẻ của cô ấy khi vung ra nhát kiếm đó.\nTrong lãnh địa của Ngài, bóng hình liều lĩnh kia đã đầy thương tích. Thân xác thuộc về con người yếu ớt đến vậy, hầu như chỉ một hơi thở cũng đủ khiến cô ấy không còn sức đứng dậy. Ngu ngốc, ngạo mạn, đáng thương — đó là toàn bộ phán quyết của Leviathan dành cho cô ấy.\nTrước khi bản án giáng xuống, bóng hình yếu ớt ấy lại một lần nữa đứng dậy. Tiếng cười của cô ấy khiến Ngài cảm nhận được một cảm xúc chưa từng có.\nNgài thấy cô ấy mang theo vũ khí vỡ vụn và thân xác tàn tạ, nhảy vọt cao lên phía Ngài. Ngài thấy Ý chí kiếm dường như có thể chém nát biển sao, hiện ra trước mắt Ngài.\nVào khoảnh khắc lưỡi kiếm đó Xuyên thấu qua Ngài, Leviathan mới hiểu ra, cảm xúc mà Ngài chưa từng trải qua đó, được gọi là Sợ hãi."
  },
  Skill_146015_Desc_0 = {
    Text = "Cần tiêu thụ <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"> mới có thể kích hoạt. Gây <Damage:[Damage:Arg1]> điểm sát thương chí mạng chắc chắn lên kẻ địch có sát thương cao nhất, hưởng [Arg2]% cộng thêm sức mạnh. Mỗi khi mục tiêu tăng 1 điểm sát thương thông qua <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\">, sát thương của \"Ngư Thần Trảm Thế\" +[Arg4]. <DerivativeCardKeywords_154:>"
  },
  Skill_146015_Desc_3 = {
    Text = "Cần tiêu thụ <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"> mới có thể kích hoạt. Gây <Damage:[Damage:Arg1]> điểm sát thương chí mạng chắc chắn lên kẻ địch có sát thương cao nhất, hưởng [Arg2]% cộng thêm sức mạnh. Mỗi khi mục tiêu tăng 1 điểm sát thương thông qua <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\">, sát thương của \"Ngư Thần Trảm Thế\" +[Arg4]. <DerivativeCardKeywords_154:>"
  },
  Skill_146015_EffectNameList = {
    Text = "Sát thương,Tăng Sức mạnh"
  },
  Skill_146015_Name = {
    Text = "Ngư Thần Trảm Thế"
  },
  Skill_146015_OverLimitUtlSkillDesc = {
    Text = "Cần tiêu thụ <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"> mới có thể kích hoạt. Nhận được [Power:Arg3] điểm <PowerIconKeywords:sức mạnh>. Gây <Damage:[Damage:Arg1]> điểm sát thương chí mạng chắc chắn lên kẻ địch có sát thương cao nhất, hưởng [Arg2]% cộng thêm sức mạnh. Mỗi khi mục tiêu tăng 1 điểm sát thương thông qua <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\">, sát thương của \"Ngư Thần Trảm Thế\" +[Arg4]. <DerivativeCardKeywords_154:>"
  },
  Skill_146015_PropertyNameList = {
    Text = "Tấn công lực *GrowValue1,$GrowValue2%"
  },
  Skill_146016_AwakerSkillBackgroundStory = {
    Text = "Thần Minh xé toạc linh hồn và thể xác của cô ấy, tưởng rằng đó là phán quyết tối thượng đối với Hỗn Mang.\nNhưng linh hồn trống rỗng chưa bao giờ ngừng tìm kiếm, sức mạnh bị tách rời cũng chưa bao giờ thực sự tan biến.\nKhi giáp xương một lần nữa phủ lên thân thể cô ấy, khi nhịp đập của Leviathan lại cảm ứng với ý chí của cô ấy — tất cả Hạn chế vỡ vụn trong khoảnh khắc đó.\nLinh hồn và thể xác hòa quyện lại nhau ở nơi sâu thẳm của biển sao. Quái thú hỗn loạn không còn khiếm khuyết nữa.\nVùng biển sao này, sẽ một lần nữa đón nhận cô ấy hoàn chỉnh."
  },
  Skill_146016_BattleDesc_0 = {
    Text = "\"Lotan: Ngư Thần\" nhận được <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Số lần gây thương của thẻ lệnh \"Lotan: Ngư Thần\" +1. Khi bắt đầu lượt nếu <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"> ở trong tay, lần đầu tiên trong lượt này <DerivativeCardKeywords_154:\"Tử Chiến\"> mỗi khi trộm cắp 1 điểm Điên loạn, làm Sát thương cuối cùng của \"Ngư Thần Trảm Thế\" lần sau +1%, tối đa cộng dồn 90%."
  },
  Skill_146016_BattleDesc_15 = {
    Text = "\"Lotan: Ngư Thần\" nhận được <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>: Số lần gây thương của thẻ lệnh \"Lotan: Ngư Thần\" +1, <DerivativeCardKeywords_154:\"Tử Chiến\"> trộm cắp Điên loạn tăng lên 50%. Khi bắt đầu lượt nếu <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"> ở trong tay, lần đầu tiên trong lượt này <DerivativeCardKeywords_154:\"Tử Chiến\"> mỗi khi trộm cắp 1 điểm Điên loạn, làm Sát thương cuối cùng của \"Ngư Thần Trảm Thế\" lần sau +1.5%, tối đa cộng dồn 135%."
  },
  Skill_146016_Desc_0 = {
    Text = "\"Lotan: Ngư Thần\" nhận được [Arg2]% Cuồng khí cơ bản. <ExaltIconKeywords:Khai mở linh trí>: Số lần gây thương của thẻ lệnh \"Lotan: Ngư Thần\" +1. Khi bắt đầu lượt nếu <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"> ở trong tay, lần đầu tiên trong lượt này <DerivativeCardKeywords_154:\"Tử Chiến\"> mỗi khi trộm cắp 1 điểm Điên loạn, làm Sát thương cuối cùng của \"Ngư Thần Trảm Thế\" lần sau +1%, tối đa cộng dồn 90%."
  },
  Skill_146016_Desc_15 = {
    Text = "\"Lotan: Ngư Thần\" nhận được [Arg2]% Cuồng khí cơ bản. <ExaltIconKeywords:Khai mở linh trí>: Số lần gây thương của thẻ lệnh \"Lotan: Ngư Thần\" +1, Điên loạn mà <DerivativeCardKeywords_154:\"Tử Chiến\"> trộm cắp tăng lên 50%. Khi bắt đầu lượt nếu <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"> ở trong tay, lần đầu tiên trong lượt này <DerivativeCardKeywords_154:\"Tử Chiến\"> mỗi khi trộm cắp 1 điểm Điên loạn, làm Sát thương cuối cùng của \"Ngư Thần Trảm Thế\" lần sau +1.5%, tối đa cộng dồn 135%."
  },
  Skill_146016_EffectNameList = {
    Text = "Điên loạn"
  },
  Skill_146016_Name = {
    Text = "Khởi Nguyên Sống Lại"
  },
  Skill_146017_AwakerSkillBackgroundStory = {
    Text = "Chiếc răng sắc nhất của Leviathan được mài thành đoản đao, cô ấy gọi nó là \"Thực\".\nNó không có bất kỳ hứng thú nào với kẻ yếu, lưỡi kiếm luôn hướng về kẻ thù mạnh nhất. Lưỡi dao sắc đâm ra với tốc độ cực nhanh, khi bóng mờ tan biến, sức mạnh bao la như biển sao cũng sẽ bị Nuốt chửng sạch.\nSự Tham lam của nó không bao giờ có điểm dừng, Ánh Mắt Đói Khát đó từ khi ra đời đã chăm chăm nhìn Rotan, mỗi lần ra tay đều Cắn xé một mảng Huyết Nhục trong cơ thể Rotan.\nRotan chưa bao giờ để tâm. Cô ấy dùng Máu Tươi nuôi dưỡng nó, dùng Sức mạnh chế ngự nó. Cô ấy dùng nó vung về phía đối thủ mạnh nhất, hương vị của Sức mạnh, cô ấy cùng nó thưởng thức."
  },
  Skill_146017_BattleDesc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương ngẫu nhiên [Arg3] lần, nhận [Power:Arg2] điểm <PowerIconKeywords:Sức mạnh>, coi như \"Đánh\". Sau khi chơi xong xáo trở lại rút bài từ bộ bài. Mỗi lần thứ 3 chơi lá bài này Có hiệu lực thêm 1 lần và khiến lần chơi \"Trường Kiếm: Diệt\" tiếp theo trong lượt này tổng hợp thành <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\">( [Arg4]/3 )<DerivativeCardKeywords_154:>"
  },
  Skill_146017_Desc = {
    Text = "Coi như \"Đánh\". Gây <Damage:[Damage:Arg1]> điểm thương cho kẻ địch ngẫu nhiên [Arg3] lần, nhận [Power:Arg2] điểm <PowerIconKeywords:Sức mạnh>, sau khi chơi xong xáo trở lại rút bài từ bộ bài. Mỗi lần thứ 3 chơi lá bài này Có hiệu lực thêm 1 lần và khiến lần chơi \"Trường Kiếm: Diệt\" tiếp theo trong lượt này tổng hợp thành <DerivativeCardKeywords_153:\"Đại Kiếm: Kình Lạc\"><DerivativeCardKeywords_154:>"
  },
