  Skill_19313_Desc_1 = {
    Text = "<PVPWeaponKeywords:vòng mệnh>: Khi kết thúc lượt, nhận được <Block:[Block:Arg1]> lá chắn và <Energy:[Energy:Arg2]> điên cuồng."
