  },
  Skill_19314_Name_1 = {Text = "Đánh"},
  Skill_19315_Desc_1 = {
    Text = "<PVPWeaponKeywords:vòng mệnh>:Vào đầu mỗi lượt, nhận được hiệu ứng tích cực <PVPWonderfulEffectKeywords:hiệu ứng kỳ diệu>, mỗi lần đối phương sử dụng 「lệnh khóa」 lần đầu tiên trong lượt của họ sẽ đặt [Arg1] lá <PVPDerivativeCardKeywords_3:「cảnh quan hoa lệ」> vào tay."
  },
  Skill_19315_Name_1 = {
