  Skill_19321_Desc_1 = {
    Text = "<PVPWeaponKeywords:Vòng Mệnh>: Sau khi chết, đầu lượt tiếp theo <PVPResurrectionKeywords:hồi sinh> bản thân và nhận <Heal:[Heal:Arg1]> sinh mệnh cùng <Block:[Block:Arg2]> khiên, sau đó phá hủy \"Vòng Mệnh\" này."
