  },
  Skill_21615_AwakerSkillBackgroundStory = {
    Text = "Ký ức của Orci bị đứt gãy vì hiện tượng ăn mòn. \n Anh nhớ tiếng cười trong buổi khiêu vũ, nhưng quên mất tên của nhân vật chính trong buổi tiệc; anh nhớ mình được huấn luyện trong đoàn kỵ sĩ, nhưng không biết tại sao công tước lại để cho cậu bé tươi trẻ ấy trở thành kỵ sĩ; anh nhớ mình đã chết dưới chân kỵ sĩ sắt, nhưng không thể nhớ nụ cười mà mình đã bảo vệ là như thế nào. \n Không ai có thể trách móc anh, anh đã thực hiện mọi trách nhiệm mà một kỵ sĩ cần có - bao gồm cả việc hy sinh mạng sống vì ý chí bảo vệ."
  },
  Skill_21615_Desc_0 = {
    Text = "Giải trừ trạng thái <FragileIconKeywords:yếu đuối> của bản thân. Nhận được <Block:[Block:Arg1]> điểm lá chắn. Nhận được [Power:Arg2] điểm lực lượng tạm thời <PowerIconKeywords:lực lượng>."
  },
  Skill_21615_Desc_2 = {
    Text = "Nếu bản thân có trạng thái <FragileIconKeywords:yếu đuối>, thì xóa bỏ và nhận <Block:[Block:Arg3]> điểm lá chắn. Nhận <Block:[Block:Arg1]> điểm lá chắn. Nhận [Power:Arg2] điểm lực lượng tạm thời<PowerIconKeywords:lực lượng>."
  },
  Skill_21615_EffectNameList_0 = {
    Text = "Lá chắn、lực lượng"
  },
  Skill_21615_EffectNameList_2 = {
    Text = "Làm tan biến để nhận lá chắn, tăng cường lá chắn và lực lượng"
  },
  Skill_21615_Name = {
    Text = "bảy nghệ thuật, truyền thừa đức hạnh"
  },
  Skill_21615_OverLimitUtlSkillDesc_0 = {
    Text = "Xua tan trạng thái <FragileIconKeywords:Mong manh> của bản thân. Nhận <Block:[Block:Arg1]> điểm lá chắn. Nhận [Power:Arg2] điểm <PowerIconKeywords:Sức mạnh> tạm thời. Lá chắn nhận được tăng 200%. Số lần gây thương của Orci +1, kéo dài 3 lượt."
  },
  Skill_21615_OverLimitUtlSkillDesc_2 = {
    Text = "Nếu bản thân có trạng thái <FragileIconKeywords:Mong manh>, thì xóa bỏ và nhận <Block:[Block:Arg3]> điểm lá chắn. Nhận được <Block:[Block:Arg1]> điểm lá chắn. Nhận [Power:Arg2] điểm <PowerIconKeywords:Sức mạnh> tạm thời. Lá chắn nhận thêm 200%. Số lần gây thương tích của Orci tăng thêm 1 lần và kéo dài trong 3 lượt."
  },
  Skill_21615_PropertyNameList_0 = {
    Text = "Khả năng phòng thủ *GrowValue1, sức tấn công *GrowValue2"
  },
  Skill_21615_PropertyNameList_2 = {
    Text = "Khả năng phòng thủ *GrowValue3, khả năng phòng thủ *GrowValue1, sức tấn công *GrowValue2"
  },
  Skill_21620_AwakerSkillBackgroundStory = {
    Text = "Lý tính quyết định góc nhìn của cô ấy, chân lý xây dựng chiều sâu tư duy của cô ấy, còn thực tế thì hạn chế thước đo đạo đức của cô ấy. \n Đối với thiên tài không giống ai này, khoa học cũng là một loại triết học."
  },
  Skill_21620_Desc_0 = {
    Text = "Giải trừ trạng thái <VulnerabilityIconKeywords:tăng sát thương> của bản thân. Khôi phục <Heal:[Heal:Arg1]> điểm sức sống, các thân thể được đánh thức khác nhận được <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_21620_Desc_3 = {
    Text = "Giải trừ trạng thái <VulnerabilityIconKeywords:dễ bị tổn thương> của bản thân. Phục hồi <Heal:[Heal:Arg1]> điểm sức sống, tất cả các thân thể được đánh thức nhận được <Energy:[Energy:Arg2]> điểm cuồng nộ."
  },
