  Skill_36800_Desc = {
    Text = "Rút [Arg1] thẻ bài có sức tính toán tiêu thụ thấp nhất từ bộ bài rút. Nếu giới vực hiện tại là\"biển sâu\", thì tăng thêm <TentacleInjurieIconKeywords:thương tổn xúc tu> [Arg2] điểm."
  },
  Skill_36800_Name = {
    Text = "Kho báu của Ô Ryta"
  },
  Skill_36807_BattleDesc = {
    Text = "Chọn 1 thân thể được đánh thức để nhận <Energy:[Arg2]> điểm điên cuồng, nhận [Arg3] điểm <PowerIconKeywords:lực lượng>, nếu giới vực hiện tại là \"thịt máu\", thêm <EmbryoFusionIconKeywords:phôi hợp tử> + [Arg4], nhưng giảm 10%([Arg1]) sức sống hiện tại."
  },
  Skill_36807_Desc = {
    Text = "Chọn 1 thân thể được đánh thức để nó nhận được <Energy:[Arg2]> điểm điên cuồng, nhận [Arg3] điểm <PowerIconKeywords:lực lượng>, nếu giới vực hiện tại là \"thịt máu\", cộng thêm [Arg4] vào <EmbryoFusionIconKeywords:phôi hợp tử>, nhưng mất 10% sức sống hiện tại."
  },
  Skill_36807_Name = {
    Text = "Máu và Cát Gầm Rú"
  },
  Skill_36808_Desc = {
    Text = "Nhận được [Arg4] điểm sức tính toán. Chọn 1 thân thể được đánh thức, đặt [Arg1] lá \"đánh\" và [Arg1] lá \"phòng thủ\" bản sao gốc vào tay, và khiến họ nhận được <DepleteIconKeywords:tiêu thụ>, <NothingnessIconKeywords:hư vô>. Nếu giới vực hiện tại là \"siêu việt\", thì nhận thêm [Arg2] điểm lực lượng tạm thời <PowerIconKeywords:lực lượng> và [Arg3] điểm giữ mình tạm thời <AlertIconKeywords:giữ mình>."
  },
  Skill_36808_Name = {
    Text = "sự vĩnh cửu ngắn ngủi"
  },
  Skill_36809_Desc = {
