  },
  Skill_36809_Name = {
    Text = "Lời thề cuối cùng"
  },
  Skill_36843_Desc = {
    Text = "Chọn [Arg1] lá bài từ bộ bài và thêm vào tay, đồng thời giảm sức tính toán tiêu thụ [Arg2]."
  },
  Skill_36843_Name = {
    Text = "Vượt qua cánh cửa hồi tưởng"
  },
  Skill_36844_Desc = {
    Text = "Gây [Arg2] điểm <IntoxicationIconKeywords:Ngộ độc> lên kẻ thù có Sinh lực cao nhất, nhận <Block:[Block:Arg1]> điểm lá chắn. Nếu trong lượt này đã kích hoạt \"Nuốt chửng\", không còn nhận lá chắn, kích hoạt 50% <IntoxicationIconKeywords:Ngộ độc> lên kẻ thù đó."
  },
  Skill_36844_Name = {
