  Skill_3973_AwakerSkillBackgroundStory = {
    Text = "Sắp bị sự tĩnh lặng nuốt chửng, cô như nhìn thấy người hầu gái đã chết đuối. \nDa của người hầu gái trắng bệch, giống như một bông sen úa nằm trên mặt hồ, vết thương trên cổ đang lan theo những mạch máu xanh nhạt đến nơi vô định. \n \"Hãy nhìn chuỗi ngọc mắt mèo của cô đi,\" xác chết nói, \"tất cả đã biến thành tro rồi. Biến thành tro rồi...\""
  },
  Skill_3973_Desc = {
    Text = "Phục hồi <Heal:[Heal:Arg1]> điểm sức sống và nhận <Block:[Block:Arg2]> điểm lá chắn. Cuối lượt, nếu ở trong tay, tăng tiêu thụ sức tính toán thêm 1, phục hồi sức sống và lá chắn gấp đôi. Tối đa [Arg3] lần."
