  Skill_3975_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [AttackTimes:Arg2] lần. Áp dụng [Arg3] lượt<FragileIconKeywords:yếu đuối>."
  },
  Skill_3977_AwakerSkillBackgroundStory = {
    Text = "\"Lại gần một chút, đừng ngượng ngùng, hãy để ông Mũ Lễ thưởng thức nụ cười và niềm vui của bạn.\"\nThầy Kassia gật gù vành mũ, rầm một tiếng biến ra một bó dải lụa và thẻ bài lớn. \n \"Chọn lá bài của bạn trong lòng. Xì! Đừng nói với ai cả. Thầy Kassia sẽ chỉ cho bạn lá nào là duy nhất của bạn.\""
  },
  Skill_3977_Desc_0 = {
    Text = "Được xem là \"đánh\". Chọn 1 lá bài bất kỳ từ <DimensionalSpaceIconKeywords:siêu việt> vào tay và giảm chi phí sức tính toán của nó đi 2. Gây ra ngẫu nhiên <Damage:[Damage:Arg1]> điểm thương [Arg2] lần, nhận [Power:Arg3] điểm <PowerIconKeywords:lực lượng> tạm thời."
  },
  Skill_3977_Desc_3 = {
    Text = "Được xem là 「đánh」. Chọn 1 lá bài bất kỳ từ <DimensionalSpaceIconKeywords:Khoảng không gian siêu việt> đưa vào tay và giảm 2 điểm tiêu thụ sức tính toán. Gây ngẫu nhiên <Damage:[Damage:Arg1]> điểm thương [Arg2] lần, nhận [Power:Arg3] điểm <PowerIconKeywords:lực lượng> tạm thời. <RippleKeywords:Dư ba>: Trộn 1 lá <DerivativeCardKeywords_4:「Linh cảm」> vào bộ bài rút."
  },
