  Skill_3978_Name = {
    Text = "Cảnh giác"
  },
  Skill_3979_AwakerSkillBackgroundStory = {
    Text = "Bệnh tâm thần phân liệt.\nTrước khi từ này được phát minh, Herbert đã tạo ra vô số bệnh nhân trong phòng thí nghiệm.\n24 chắc chắn là tác phẩm đỉnh cao trong số đó, nhân cách của cô ấy sinh sôi với tốc độ đáng kinh ngạc, và không làm phiền nhau.\nTheo một nghĩa nào đó, não bộ của cô ấy giống như một căn hộ đông đúc, chật cứng khách thuê ồn ào."
  },
  Skill_3979_Desc_0 = {
    Text = "Gây [Arg2] lần thương ngẫu nhiên, mỗi lần <Damage:[Damage:Arg1]> điểm."
