  Skill_3980_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> sát thương [AttackTimes:Arg2] lần, tạo ra <Block:[Block:Arg3]> lá chắn."
  },
  Skill_3981_AwakerSkillBackgroundStory = {
    Text = "Dòng máu được truyền từ các chủng tộc khác, bị coi là dị giáo. \nChỉ có lòng tin vào sự cao quý, tin vào sự vĩ đại của nó, mới có thể sống sót trong thế giới tàn nhẫn. \nCuốn cuộn giấy mà chú Oran để lại, cùng với thành phố cổ đại huyền ảo dưới biển sâu được vẽ trong đó, là chỗ dựa tinh thần duy nhất của anh. \n \"Khi dòng máu bùng phát, chắc chắn sẽ được ban tặng lực lượng vô song từ biển sâu.\""
  },
  Skill_3981_Desc = {
    Text = "Phục hồi <Heal:[Heal:Arg3]> điểm sức sống và xóa trạng thái <WeaknessIconKeywords:suy nhược> của bản thân, áp dụng [Arg4] lớp <VulnerabilityIconKeywords:trọng thương> lên tất cả kẻ địch. <TentacleInjurieIconKeywords:Thương tổn xúc tu> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Phản công> +[Counterattack:Arg2]. Trước khi bắt đầu lượt tiếp theo, mỗi lần bị tấn công sẽ khiến 1 râu chạm phản công kẻ tấn công."
  },
  Skill_3981_EffectNameList = {
