  Skill_4010_AwakerSkillBackgroundStory = {
    Text = "Hiro không nhớ mình đã có được sức mạnh kỳ quái này từ khi nào. \n Vào một đêm không có sao, Hiro tỉnh dậy từ bùn đất trong nhà tù, đột nhiên phát hiện ra chất lỏng đen đang quằn quại bên cạnh. Những chất lỏng đen đó như những cánh tay mới sinh, đã phá bỏ những chiếc xích chắc chắn. \n Cô nhớ đến người nông dân già bị giam giữ ở phòng bên cạnh, người mà cô đã cầu xin để thoát khỏi tù. Cô vội vàng chạy đến kiểm tra, nhưng chỉ còn lại những vết máu gần như đã cạn kiệt. \n Đó từng là cha cô. \n Những ngày đêm không ngừng nghỉ của lao động không lấy đi mạng sống của ông, những trận đòn tàn nhẫn không lấy đi mạng sống của ông—mạng sống của ông bị cướp đi bởi chính sự cầu xin của mình, bởi những lời dèm pha của kẻ vu khống, bởi sự phân biệt của kẻ cầm quyền... \n Hốc mắt đã khô cạn, những gì chảy ra—chỉ là chất lỏng đen chứa đầy sự hận thù mà thôi."
  },
  Skill_4010_BattleDesc = {
    Text = "Mất [Arg1]% Cuộc sống hiện tại ([Arg3]). Gây <Damage:[Damage:Arg2]> sát thương cho tất cả kẻ thù và gây thêm tác dụng <BleedingIconKeywords:Chảy máu>. Tạo 2 lá \"Đánh\" ngẫu nhiên của người đánh thức và thêm vào <DepleteIconKeywords:Kiệt sức>. Xem như \"Đánh\"."
  },
  Skill_4010_Desc = {
    Text = "Mất [Arg1]% cuộc sống hiện tại. Gây sát thương <Damage:[Damage:Arg2]> cho tất cả kẻ thù và gây sát thương bằng lượng tương đương <BleedingIconKeywords: chảy máu>. Tạo 2 lá bài \"Đánh\" ngẫu nhiên của người đánh thức và thêm <DepleteIconKeywords: kiệt sức>. Được coi như \"Đánh\"."
