  },
  Skill_4017_AwakerSkillBackgroundStory = {
    Text = "Trong sự cô đơn dài đằng đẵng, cô đã dần quên lãng lý do mình vung kiếm. \nNhưng cô biết rõ rằng, mình phải đưa ra nhát kiếm quyết định này."
  },
  Skill_4017_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương, <PowerIconKeywords:lực lượng> phát huy [Arg2] lần hiệu ứng trên \"Kiếm Định Mệnh\". Mỗi lần sử dụng lệnh khóa, tỷ lệ lực lượng tăng gấp đôi trong trận chiến này. <TimeBeacon:hoàn vòng>: chọn <C01EXCardKeyWord1:vòng tuần hoàn> hoặc <C01EXCardKeyWord2:bài ca tương lai>."
