  Skill_4017_PropertyNameList_0 = {
    Text = "Sức tấn công*GrowValue1,"
  },
  Skill_4018_AwakerSkillBackgroundStory = {
    Text = "Đau đớn, đau đớn. \n Cơn đau đen tối và lạnh lẽo là một trong những điều ít ỏi mà cô còn ấn tượng. \n Nếu cô giống như những con ốc anh vũ thực thụ, có một chiếc vỏ cứng rắn và xinh đẹp, liệu có còn đau như thế nữa không?"
  },
  Skill_4018_Desc_0 = {
    Text = "Nốtira nhận được <Energy:[Energy:Arg1]> điểm điên cuồng.<ExaltIconKeywords:Thức tỉnh linh tri thức>:Nốtira thi triển lá chắn và <RetaliateIconKeywords:phản công> tăng [Arg2]%."
  },
  Skill_4018_Desc_15 = {
    Text = "Notera nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Khiên và <RetaliateIconKeywords:Phản Kích> mà Notera thi triển tăng [Arg2]%, <RetaliateIconKeywords:Phản Kích> cố định mà tất cả Hoán Tỉnh Thể gây ra tăng [Arg3]%."
  },
  Skill_4018_EffectNameList = {
    Text = "điên cuồng"
  },
  Skill_4018_Name = {
    Text = "thợ sửa chữa đại tài"
  },
  Skill_4019_AwakerSkillBackgroundStory = {
    Text = "Như lý thuyết về vạn vật sinh ra từ một và vạn vật quy về một, cô ấy từng rơi vào bẫy nghịch lý."
  },
  Skill_4019_Desc_0 = {
    Text = "Nhận được <Posse:[Arg1]> điểm năng lượng chìa khóa bạc. Đặt 3 bản gốc khác nhau của thẻ lệnh không phái sinh được đánh cuối lượt trước vào tay, giảm sức tính toán tiêu thụ của chúng xuống 1 và nhận <DepleteIconKeywords:tiêu thụ> và <NothingnessIconKeywords:hư vô>. Nếu số thẻ lệnh có thể đặt vào tay không đủ, thì rút số thẻ tương đương để thay thế."
  },
  Skill_4019_Desc_3 = {
    Text = "Nhận được <Posse:[Arg1]> điểm năng lượng chìa khóa bạc. Đặt 3 bản gốc khác nhau của thẻ lệnh không phái sinh được chơi cuối lượt trước vào tay, giảm sức tính toán tiêu thụ của chúng xuống 1 và nhận <DepleteIconKeywords:tiêu thụ> và <NothingnessIconKeywords:hư vô>. Nếu số thẻ lệnh có thể đặt vào tay không đủ, thì rút số thẻ tương đương để thay thế. Chọn 1 mật lệnh nào đó đã được mở khóa để thay thế mật lệnh hiện tại, sử dụng mật lệnh hoặc phục hồi sau khi kết thúc trận chiến."
  },
  Skill_4019_EffectNameList = {
    Text = "Sạc năng lượng chìa khóa bạc"
  },
  Skill_4019_Name = {
    Text = "bế tắc thu thập"
  },
  Skill_4019_OverLimitUtlSkillDesc_0 = {
    Text = "Nhận <Posse:[Arg1]> Năng lượng chìa khóa bạc. Sao chép nguyên bản 3 thẻ lệnh không phái sinh khác nhau được chơi cuối cùng trong lượt trước đưa vào tay, làm cho Giá trị Điểm tính toán của chúng trở thành 0 và nhận <DepleteIconKeywords:Tiêu hao> và <NothingnessIconKeywords:Hư vô>. Nếu số thẻ lệnh có thể đưa vào tay không đủ, thì Rút số lượng tương đương thay thế. Nhận 3 lớp <TimeBeacon2:Negentropy> không giới hạn tối đa."
  },
  Skill_4019_OverLimitUtlSkillDesc_3 = {
    Text = "Nhận <Posse:[Arg1]> điểm năng lượng chìa khóa bạc. Đặt 3 bản gốc khác nhau của thẻ lệnh không phái sinh được đánh cuối lượt trước vào tay, làm cho sức tính toán tiêu thụ của chúng trở thành 0 và nhận <DepleteIconKeywords:tiêu thụ> và <NothingnessIconKeywords:Hư vô>. Nếu số thẻ lệnh có thể đặt vào tay không đủ, thì rút số thẻ tương đương để thay thế. Chọn 1 lệnh khóa đã mở khóa bất kỳ để thay thế lệnh khóa hiện tại, sử dụng lệnh khóa hoặc phục hồi sau khi kết thúc trận đấu. Nhận 3 lớp <TimeBeacon2:Negentropy> không bị giới hạn."
  },
