  Skill_4023_AwakerSkillBackgroundStory = {
    Text = "Liz vẫn còn nhớ cảnh tượng khi cô nhận được ngọn lửa lục ấy. \nNgọn lửa lục nhảy múa và bùng lên trong lòng bàn tay, thúc giục cô thực hiện ước muốn đã bị dồn nén lâu nay."
  },
  Skill_4023_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:sát thương xuyên>, áp dụng [Arg2]% <IntoxicationIconKeywords:trúng độc>. Cuối lượt nếu ở trong tay hoặc <DimensionalSpaceIconKeywords:siêu việt>, nâng cấp thành \"<DerivativeCardKeywords_19:phù hợp mục tiêu bị thối rữa>\". Khi không đủ sức tính toán, vẫn có thể ép buộc sử dụng, hiệu ứng thay đổi thành nhận <Energy:[Energy:Arg3]> điểm điên cuồng và tiêu thụ."
  },
