  },
  Skill_4025_Desc = {
    Text = "Gây ra [Arg1] lớp<WeaknessIconKeywords:yếu đuối>, nhận được \"Cơn giận của bầy chuột\": vòng sau, mỗi lần bị tấn công sẽ nhận được [Arg3] điểm<PowerIconKeywords:lực lượng>."
