  },
  Skill_4027_AwakerSkillBackgroundStory = {
    Text = "Phiệt không thể rời khỏi lớp vỏ mỏng, Tinkerer thường xuyên ở bên cạnh cô, hát bài ca an ủi này cho cô. \n \"Tôi sẽ hấp thụ sức sống của bạn.\" Phiệt nói. \n \"Đừng lo, sự sống của chúng ta là một.\" Tinkerer đáp lại."
  },
  Skill_4027_BattleDesc_0 = {
    Text = "Xua tan trạng thái <FragileIconKeywords:Mong Manh>, <WeaknessIconKeywords:Suy Nhược> và <VulnerabilityIconKeywords:Dễ Tổn Thương> của bản thân. Tạm thời giảm [Exhaustion:Arg1] điểm <ExhaustionIconKeywords:Sức Mạnh> của tất cả kẻ địch, mỗi 1 kẻ địch nhận [Power:Arg1] điểm <PowerIconKeywords:Sức Mạnh tạm thời>. Lượt này hiệu ứng Dịch Chuyển tiếp theo chắc chắn kích hoạt. <TransitionIconKeywords:Dịch Chuyển>: Thay vào đó tạm thời giảm [Exhaustion:Arg2] điểm <ExhaustionIconKeywords:Sức Mạnh> của tất cả kẻ địch, mỗi 1 kẻ địch nhận [Power:Arg2] điểm <PowerIconKeywords:Sức Mạnh tạm thời>."
  },
  Skill_4027_Desc_0 = {
    Text = "Giải trừ trạng thái <FragileIconKeywords:yếu đuối>, <WeaknessIconKeywords:suy nhược> và <VulnerabilityIconKeywords:trọng thương> của bản thân. <TouquKeywords:Trộm cắp> [Arg1] điểm <PowerIconKeywords:lực lượng> từ tất cả kẻ địch. Làm cho hiệu ứng bước nhảy lần tiếp theo trong lượt này chắc chắn xảy ra. <TransitionIconKeywords:Bước nhảy>: Thay đổi để <TouquKeywords:trộm cắp> [Arg2] điểm <PowerIconKeywords:lực lượng>."
  },
