  Skill_4052_Name = {Text = "Phôi thai"},
  Skill_4052_tempBattleDesc_1 = {
    Text = "Thể thức tỉnh trong cõi thịt máu khi phát động bùng nổ điên cuồng có thể tiêu thụ nó, kích hoạt 1 lần hiệu ứng <DevouredIconKeywords:tiêu thụ>. Sau khi chơi, chọn một thể thức tỉnh để nhận <Energy:[Energy:Arg1]> điểm điên cuồng, tỷ lệ chí mạng trong lượt này tăng [Arg2]%."
  },
  Skill_4052_tempBattleDesc_2 = {
    Text = "Khi Thể Thức Tỉnh của Giới Vực Huyết Nhục giải phóng Cuồng Khí Bùng Nổ có thể tiêu hao nó, kích hoạt 1 lần hiệu ứng <DevouredIconKeywords:Nuốt Chửng>. Sau khi đánh ra, chọn một Thể Thức Tỉnh nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. Mỗi lượt khi Thể Thức Tỉnh lần đầu tiêu hao \"Phôi Thai\" hoặc \"Con của sự thánh thiện\", nhận được [Arg3] tầng <BreedingKeywords1:Lễ hội phối giống>."
