  },
  Skill_4054_Desc = {
    Text = "Một loại vết thương Xé toạc đặc biệt. Khi kết thúc lượt nếu còn trong tay, nhận [Arg1] điểm <FixedDamage:Sát Thương Thuần Túy>. Khi bỏ đi sẽ <DepleteIconKeywords:tiêu hao> nó."
  },
  Skill_4054_Name = {
    Text = "Viết rách"
  },
  Skill_4055_AwakerSkillBackgroundStory = {
    Text = "Trong đại dương bao la vô tận, con tàu cô đơn lắc lư theo sóng biển. \nHọ cầu xin, van nài, khẩn cầu, hy vọng nữ thánh trắng có thể đưa họ rời khỏi biển cả, trở về quê hương. \nTại cột buồm chính, cô gái mặc váy trắng ngẩng đầu lên, nhìn thấy một con chim trắng bay lượn. \n \"Giao lái cho tôi, tôi sẽ dẫn các người về nhà.\""
  },
  Skill_4055_BattleDesc_0 = {
    Text = "Giải trừ trạng thái <HeavyInjuryKeywords:Thiệt hại nặng> của bản thân, hồi phục <Heal:[Heal:Arg1]> điểm sức sống và nhận 1 điểm tính toán. Trong trận chiến này, khi nhận phải thương gây chết sẽ phục sinh và hồi phục [Arg2]%(<Heal:[Arg3]>) sức sống, mỗi trận chiến chỉ có thể kích hoạt 1 lần."
  },
  Skill_4055_BattleDesc_3 = {
    Text = "Giải trừ trạng thái <HeavyInjuryKeywords:Thiệt hại nặng> của bản thân, hồi phục <Heal:[Heal:Arg1]> điểm sức sống và nhận 1 điểm tính toán. Trong trận chiến này, khi nhận phải thương gây chết sẽ phục sinh, hồi phục [Arg2]%(<Heal:[Arg3]>) sức sống và khiến tất cả thân thể thức tỉnh nhận được <Energy:[Energy:Arg4]> điểm điên cuồng, sau khi kích hoạt cần phải cách 6 lượt mới có thể áp dụng hiệu ứng phục sinh lần nữa."
  },
  Skill_4055_Desc_0 = {
    Text = "Giải trừ trạng thái <HeavyInjuryKeywords:Thiệt hại nặng> của bản thân, hồi phục <Heal:[Heal:Arg1]> điểm sức sống và nhận 1 điểm tính toán. Trong trận chiến này, khi nhận phải thương gây chết sẽ phục sinh và hồi phục [Arg2]% sức sống, mỗi trận chiến chỉ có thể kích hoạt 1 lần."
  },
  Skill_4055_Desc_3 = {
    Text = "Giải trừ trạng thái <HeavyInjuryKeywords:Thiệt hại nặng> của bản thân, hồi phục <Heal:[Heal:Arg1]> điểm sức sống và nhận 1 điểm tính toán. Trong trận chiến này, khi nhận phải thương gây chết sẽ phục sinh, hồi phục [Arg2]% sức sống và khiến tất cả thân thể được đánh thức nhận được <Energy:[Energy:Arg4]> điểm điên cuồng, sau khi kích hoạt cần phải chờ 6 lượt mới có thể tái áp dụng hiệu ứng phục sinh."
  },
  Skill_4055_EffectNameList = {
    Text = "Phục hồi, phục hồi phần trăm sức sống"
  },
  Skill_4055_Name = {
    Text = "Chim thiên đường bất tử"
  },
  Skill_4055_OverLimitUtlSkillDesc_0 = {
    Text = "Hồi phục <Heal:[Heal:Arg1]> điểm Sinh lực và nhận 1 Điểm tính toán, xua tan trạng thái <HeavyInjuryKeywords:Thiệt hại nặng> của bản thân. Trong trận chiến này, khi nhận sát thương gây chết sẽ được phục sinh, hồi phục [Arg2]% (<Heal:[Arg3]>) Sinh lực, mỗi trận chỉ có thể kích hoạt 1 lần. Đặt 3 thẻ \"Giấc mơ thuần khiết\" tăng hồi phục 50% vào tay và gắn thêm tiêu thụ."
  },
  Skill_4055_OverLimitUtlSkillDesc_3 = {
    Text = "Phục hồi <Heal:[Heal:Arg1]> điểm sức sống và nhận 1 sức tính toán, xóa bỏ trạng thái <HeavyInjuryKeywords:trạng thái trọng thương>. Trong trận chiến này, nếu nhận sát thương gây tử vong sẽ hồi sinh, phục hồi [Arg2]%(<Heal:[Arg3]>) điểm sức sống. Đồng thời, tất cả các thân thể được đánh thức nhận được <Energy:[Energy:Arg4]> điểm điên cuồng. Sau khi kích hoạt, cần cách 6 lượt mới có thể áp dụng lại hiệu ứng hồi sinh. Đưa 3 lá \"Giấc mơ thuần khiết\" tăng 50% lượng hồi phục vào tay, kèm theo hiệu ứng tiêu thụ."
