  },
  Skill_4065_AwakerSkillBackgroundStory = {
    Text = "Ác ý ở vị trí cao không ngừng bồn chồn, nhưng ý chí của nhân loại cũng không phải là không có sức chống cự. \n Chất lỏng đen hòa tan mọi thứ đã làm suy yếu tinh thần của Ngài, trở thành sự trợ giúp duy nhất của nhân loại. \n Người tạo ra rối tạm thời chiếm ưu thế, cô ấy mở rộng đôi tay, biến dòng điện phá hoại thành những đường cong bảo vệ."
  },
  Skill_4065_BattleDesc_0 = {
    Text = "Nhận được [Arg1] điểm tạm thời<AlertIconKeywords:giữ mình>. Nhận được <Posse:[Arg2]> điểm năng lượng chìa khóa bạc. Loại bỏ trạng thái<FragileIconKeywords:yếu đuối> của bản thân. Mỗi khi có 1 lá bài đi vào<DimensionalSpaceIconKeywords:siêu việt>, sẽ biến đổi thành<DerivativeCardKeywords_13:「trang bị cơ khí - phóng」>."
