  Skill_4074_Name = {Text = "Trốn"},
  Skill_4075_AwakerSkillBackgroundStory = {
    Text = "Ninh Phi Nga rất thích hoa, ngoài tiểu thuyết văn học, đây là điều duy nhất ở bên cạnh cô khi nằm trên giường bệnh. \n Chỉ là, kể từ khi cha mẹ qua đời, không còn ai định kỳ mang đến những bó hoa an ủi. \n Bó hoa lily cuối cùng ấy, cũng dần mất đi sự tươi sống theo thời gian. \n Vì vậy, trong tang lễ mà cô chuẩn bị cho bản thân, cô đã không do dự mang theo nó. \n Cá bơi lội theo ánh sáng và bóng đổ, san hô như cành lá mọc lên, theo những con sóng đang dâng trào hướng tới nơi cô chỉ về bằng ánh mắt."
  },
