  Skill_4102_AwakerSkillBackgroundStory = {
    Text = "Lắc bụng đói meo đi dạo trên phố. \n \"Giá mà có một con gà quay xuất hiện ngay trước mặt thì tốt biết mấy,\" Lắc nghĩ. \n Một bóng đen lướt qua, tiếp theo là tiếng hét của một người phụ nữ. \n Mắt tinh tay nhanh, Lắc lập tức túm lấy bóng đen, định trả lại túi xách cho người phụ nữ nhưng chợt nhận ra vẻ mặt cô ta có gì đó bất thường. \n Sau một hồi giằng co, cảnh sát tuần tra mới chậm rãi xuất hiện. \n Hóa ra, người phụ nữ chính là tên trộm đá quý khét tiếng. \n Chủ nhân chiếc túi đãi Lắc một bữa no nê và còn tặng thêm một viên đá quý màu vàng. \n \"Thật là một món hời ngoài ý muốn,\" Lắc vừa xoa bụng vừa nói."
  },
  Skill_4102_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương. Chọn 1 thẻ từ bộ bài và thêm vào tay, nếu là đòn chí mạng thì giảm 1 điểm tiêu thụ sức tính toán của thẻ được chọn."
