  Skill_4136_Name = {
    Text = "Trái tim biến dạng"
  },
  Skill_4137_AwakerSkillBackgroundStory = {
    Text = "Phương pháp diễn dịch là một hình thức suy luận logic, chỉ khi nắm vững tiền đề đúng, mới có thể đưa ra kết luận chính xác. \n Trước khi trở thành điều tra viên, Ramona đã luôn sử dụng phương pháp diễn dịch để nhận thức thế giới. \n Sau khi trải qua đủ nhiều cuộc phiêu lưu, có lẽ cô ấy sẽ bắt đầu xem xét việc sử dụng phương pháp quy nạp."
  },
  Skill_4137_Desc_0 = {
    Text = "Nhận được <Posse:[Arg1]> điểm năng lượng chìa khóa bạc. Chọn 1 lá bài từ bộ bài rút hoặc rác bài, thêm vào bộ bài trên tay và giảm tiêu thụ sức tính toán xuống còn 0 điểm."
  },
  Skill_4137_Desc_3 = {
    Text = "Nhận được <Posse:[Arg1]> điểm năng lượng chìa khóa bạc. Chọn 1 lá bài từ bộ rút bài hoặc rác bài và đưa vào tay, làm cho sức tính toán tiêu thụ của nó trở thành 0 điểm. Đưa 1 lá <DerivativeCardKeywords_4:「cảm hứng」> vào rút bài từ bộ bài."
  },
  Skill_4137_EffectNameList = {
    Text = "Sạc năng lượng chìa khóa bạc"
  },
  Skill_4137_Name = {
    Text = "phương pháp diễn dịch thế giới"
  },
  Skill_4137_OverLimitUtlSkillDesc_0 = {
    Text = "Nhận <Posse:[Arg1]> Năng lượng chìa khóa bạc. Chọn 1 thẻ bài từ rút bài từ bộ bài hoặc rác bài đưa vào Tay, làm cho Giá trị Điểm tính toán của nó trở thành 0. <WeaknessIconKeywords:Suy nhược> và <VulnerabilityIconKeywords:Trọng thương> tất cả kẻ địch 1 lượt, Mật lệnh tiếp theo được kích hoạt có hiệu lực 2 lần."
  },
  Skill_4137_OverLimitUtlSkillDesc_3 = {
    Text = "Nhận được <Posse:[Arg1]> điểm năng lượng chìa khóa bạc. Chọn 1 lá bài từ rút bài từ bộ bài hoặc rác bài để đưa vào tay, làm cho sức tính toán tiêu thụ của nó trở thành 0 điểm. Trộn 1 lá <DerivativeCardKeywords_4:「cảm hứng」> vào rút bài từ bộ bài. <WeaknessIconKeywords:yếu đuối> và <VulnerabilityIconKeywords:tăng sát thương> tất cả kẻ địch trong 1 lượt, lệnh khóa khi được kích hoạt tiếp theo sẽ có hiệu lực 2 lần."
  },
  Skill_4138_AwakerSkillBackgroundStory = {
    Text = "Ramona ở tuổi mười đã đề xuất mong muốn được huấn luyện chiến đấu. \nKhông phải vì muốn chơi trò hiệp sĩ, mà sau khi chứng kiến sự xa xỉ và tiêu xài phung phí của cha nuôi, cô quyết định chuẩn bị cho nguy cơ phá sản có thể đến. \n \"Lương bảo vệ nữ hoàng chắc cao hơn cảnh sát nhỉ?\""
  },
  Skill_4138_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [Arg2] lần. Sau khi sử dụng, số lần gây thương của \"kiếm của nữ hoàng\"+1, tối đa tăng đến [Arg3] lần. Nhận được [Arg7] điểm giới vực thông thạo tạm thời."
  },
  Skill_4138_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [Arg5] lần, mỗi lần gây thương nhận được [Power:Arg4] điểm <PowerIconKeywords:Sức mạnh> tạm thời. Sau khi chơi làm số lần gây thương của \"kiếm của nữ hoàng\" +1, tối đa tăng lên [Arg6] lần. Nhận được [Arg7] điểm Sự thông thạo giới vực tạm thời. <RippleKeywords:Sóng dư chấn>: Nhận được Năng lượng chìa khóa bạc tương đương 300% Sạc năng lượng chìa khóa bạc của Ramona."
  },
  Skill_4138_Desc_3 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [Arg5] lần, mỗi lần gây thương nhận được [Power:Arg4] điểm <PowerIconKeywords:Sức mạnh> tạm thời. Sau khi chơi làm số lần gây thương của \"kiếm của nữ hoàng\" +1, tối đa tăng lên [Arg6] lần. Nhận được [Arg7] điểm Sự thông thạo giới vực tạm thời. <RippleKeywords:Sóng dư chấn>: Nhận được Năng lượng chìa khóa bạc tương đương 300% Sạc năng lượng chìa khóa bạc của Ramona."
  },
