  Skill_4144_AwakerSkillBackgroundStory = {
    Text = "Nếu là mệnh lệnh của chủ nhân, Lily có thể ném cái to lớn đó đi. \n Nó không sợ đau. \n Đau chỉ là sức mạnh, đau thúc đẩy sự cuồng loạn, Lily không sợ đau, nó cũng không sợ đau. \n Vì vậy, nó nhất định có thể giúp chủ nhân tiêu diệt kẻ thù."
  },
  Skill_4144_Desc_0 = {
    Text = "Gây ra <Damage:[Damage:Arg1]> điểm sát thương, kích hoạt hiệu ứng <IntoxicationIconKeywords:ngộ độc> [Arg3]% lên mục tiêu, nếu gây ra chí mạng, tỷ lệ kích hoạt sẽ tăng lên [Arg4]%. Được coi là\"Đánh\". Mỗi lớp <PainWord:nhẫn nại> sẽ làm tăng sát thương 2, sau khi chơi sẽ loại bỏ <PainWord:nhẫn nại>."
  },
  Skill_4144_Desc_2 = {
