  Skill_4151_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương [AttackTimes:Arg2] lần, nhận được <Block:[Block:Arg3]> lá chắn."
  },
  Skill_4152_AwakerSkillBackgroundStory = {
    Text = "Máu chảy đầy đất cũng được, xác chết la liệt cũng được, chịu đựng nỗi đau xuyên tim cũng được. \n Để cho đất nước thần thánh tái lâm vào thế gian, tất cả đều là hy sinh không đáng kể. \n Cô ấy chỉ hận bản thân không phải là người được chọn, không phải là cô gái bị giam cầm trong cái lồng."
  },
  Skill_4152_Desc_0 = {
    Text = "Chọn 1 thân thể được đánh thức khác, khiến nó nhận được <Energy:[Energy:Arg2]> điểm điên cuồng. <O07CardKeyWord:nghi lễ tế>: nhận được điên cuồng tăng lên [Arg4]/[Arg5]/[Arg6] điểm."
  },
  Skill_4152_Desc_2 = {
    Text = "Chọn 1 thân thể được đánh thức khác, khiến nó nhận được <Energy:[Energy:Arg2]> điểm điên cuồng, giới vực tinh thông +[Arg3]. <O07CardKeyWord:Lễ nghi>: Nhận được điên cuồng tăng lên [Arg4]/[Arg5]/[Arg6] điểm."
  },
  Skill_4152_EffectNameList = {
