  },
  Skill_4152_Name = {
    Text = "Người được chọn"
  },
  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "Nghe đi, đó là tiếng chuông tang dành cho chính mình. \n Không phải là người tìm kiếm điên cuồng, không phải là kẻ lạc lối bối rối, cô ấy chỉ lặng lẽ lựa chọn con đường tận cùng của mình. \n Những cánh hoa tàn úa múa cho lễ tế của cô, cơn gió biển điên cuồng khóc cho bài hát tiễn đưa của cô. \n Sau tiếng chuông vang dội thấu tận tâm can, thế giới ngắn ngủi rơi vào sự tĩnh lặng chết chóc."
  },
  Skill_4154_Desc_0 = {
    Text = "Đặt [Poison:Arg1] lớp <IntoxicationIconKeywords:trúng độc> cho tất cả kẻ địch, đặt [Arg2] lượt <WeaknessIconKeywords:yếu đuối> và <VulnerabilityIconKeywords:tăng sát thương>."
  },
  Skill_4154_Desc_1 = {
