  Skill_4154_PropertyNameList_1 = {
    Text = "Sức tấn công*GrowValue1, sức phòng thủ*GrowValue2"
  },
  Skill_4155_AwakerSkillBackgroundStory = {
    Text = "Nguồn gốc từ vạn cổ, phát sinh từ sự ngu dốt, bắt nguồn từ nỗi sợ hãi. \n Chảy trong mạch máu của Thái Di Sơ là một bản năng nguyên thủy. \n Trong cuộc hiến tế khó có thể quay đầu lại, lúc đó Thái Di Sơ còn trẻ đã bị cấy ghép bản năng này. \n Ý chí, cảm xúc, thậm chí nhân cách đều bị những tồn tại không thuộc về cô thay thế——\n những gì cô để lại, chỉ có bản năng chung của sự sống, nỗi sợ hãi cái chết."
  },
  Skill_4155_BattleDesc_0 = {
    Text = "<EmbryoFusionIconKeywords:Dung hợp Phôi thai> +[Blood:Arg1], nhận <Posse:[Arg2]> điểm Năng lượng chìa khóa bạc. Lựa chọn: <B01AFKeyWord1:Máu Sợ Hãi>, <B01AFKeyWord2:Máu thối rữa>, <B01AFKeyWord3:Máu sinh sản><DerivativeCardKeywords_149:><DerivativeCardKeywords_150:><DerivativeCardKeywords_151:>"
