  Skill_4156_AwakerSkillBackgroundStory = {
    Text = "Thuở còn mới tập viết, Horla thường thích trốn trong góc thư phòng chỉ để đọc thơ. Khi ánh mắt lướt qua những dòng thơ bi thương, Horla chẳng thể làm gì khác ngoài để trái tim mình rung động."
  },
  Skill_4156_BattleDesc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> Lá Chắn. Nhận <Energy:[Energy:Arg2]> Aliemus. <TransitionIconKeywords:Nhảy Vọt>: Chuyển sang trạng thái cảm xúc \"Buồn Bã\"."
