  Skill_4167_AwakerSkillBackgroundStory = {
    Text = "Việc quản lý một salon không phải là điều đơn giản. Cân nhắc từng ly rượu, tỉ mỉ lên thực đơn, thậm chí còn phải trau chuốt ở cả khâu tuyển chọn nhân viên phục vụ, tất cả đều tự tay Sorel lo liệu.\nVà cứ thế, Sorel đã giành được quyền tự do hiếm có và đặc quyền từ những người ủng hộ cô."
  },
  Skill_4167_Desc_0 = {
