  },
  Skill_4229_BattleDesc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương. Nếu mục tiêu sức sống dưới 25%([Arg3]) hoặc bị tiêu diệt, hoàn lại tiêu thụ sức tính toán. <PowerIconKeywords:lực lượng> phát huy [Arg2] lần hiệu ứng trên \"cắt đầu trọng thương\". Mỗi râu chạm tăng thêm 1 lần hiệu quả cho lực lượng."
  },
  Skill_4229_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương, nếu máu mục tiêu dưới 25% hoặc bị hạ gục, thì trả lại lượng tiêu thụ. <PowerIconKeywords:lực lượng>tăng [Arg2] lần hiệu ứng của \"cắt đầu trọng thương\"."
