  Skill_4289_Name = {
    Text = "thử thách"
  },
  Skill_4290_AwakerSkillBackgroundStory = {
    Text = "Lễ diễu hành chiến thắng từ xưa đến nay luôn là tiệc lớn của người La Mã. \n Bồ câu trắng, lá nguyệt quế, và những mảnh vàng bay rợp trời… Tất cả đều liên quan đến chiến binh, mà cũng không liên quan. \n Anh ta cùng với những tù binh đến từ Gaul, Alexandria và Parthia, bị trói chặt trên những cây thập tự nặng nề để diễu hành trước công chúng. \n Đây là tiết mục giữ lại trong lễ diễu hành chiến thắng. Chiến binh bị chế nhạo một cách thoải mái, chỉ vì anh ta được coi là đồng phạm máu me của vị hoàng đế đã khuất. \n Nhục nhã, giận dữ, hay thù hận? Không, không có cả ba. \n Chiến binh không có cảm xúc, cũng không có suy nghĩ. \n Anh chỉ ngửi thấy máu."
  },
  Skill_4290_BattleDesc_0 = {
    Text = "Yu U Hahi nhận được <Energy:[Energy:Arg1]> điểm điên cuồng.<ExaltIconKeywords:Khai mở linh trí>: Yu U Hahi không bị ảnh hưởng bởi <CardKeyWord:Phong ấn>, tỷ lệ chí mạng và sát thương chí mạng tăng [Arg2]%, khi sinh lực dưới 25% thì hiệu ứng sẽ tăng gấp đôi."
  },
  Skill_4290_BattleDesc_15 = {
    Text = "Yuuhashi nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Yuuhashi không bị ảnh hưởng bởi <CardKeyWord:Phong Ấn>, tỷ lệ bạo kích và sát thương bạo kích tăng [Arg2]%, sát thương cuối cùng của \"Thánh Ca Máu và Cát\" tăng [Arg5]%, khi sinh mệnh dưới 25% hiệu quả nhân đôi."
