  Skill_4295_AwakerSkillBackgroundStory = {
    Text = "Đôi mắt này đã không thể nhìn thấy bình thường nữa. \n Cô đối mặt với cơn bão của thời gian và thực tại, để cho sự hỗn loạn gào thét cắt xé, nghiền nát, cuối cùng trở thành đôi mắt của cô. \n Một dấu vết khác của \"Ramona\"đang biến mất khỏi cơ thể cô, cô không thể nắm giữ bản thân đang dần trôi đi, giống như cô đã không thể nắm giữ sức sống tuột khỏi đầu ngón tay."
  },
  Skill_4295_Desc = {
    Text = "Nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>. Chọn 1 lá bài từ bộ bài rút bài và đưa vào tay, giảm sức tính toán tiêu thụ xuống 1. <TimeBeacon:Vòng lặp>: Thay đổi để chọn 1 lá bài từ bộ bài rút hoặc rác bài, đưa vào tay và làm cho sức tính toán tiêu thụ của nó trở thành 0."
