  Skill_4306_AwakerSkillBackgroundStory = {
    Text = "Cô sẽ hành động trên mặt đất nhân danh Ngài. \nCô sẽ nhận được danh tiếng xứng đáng. \nCô sẽ chịu đau đớn mà không ai có thể chịu đựng vào lúc hủy diệt. \nĐây chính là Người Thừa Hành."
  },
  Skill_4306_Desc_0 = {
    Text = "Miryam nhận được <Energy:[Energy:Arg1]> điểm điên loạn.<ExaltIconKeywords:khai mở linh trí>: số lượng xúc tu và giới hạn xúc tu +1, áp dụng 1 lớp <WeaknessIconKeywords:suy nhược> và <VulnerabilityIconKeywords:trọng thương> lên tất cả kẻ thù. Tỉ lệ chí mạng của Miryam cho kỹ năng「đánh mạnh」và「hy sinh tối thượng」tăng 100%. Đặt 1 thẻ <O07CardKeyWord4:「Những ngã rẽ của đức tin」> vào tay."
  },
  Skill_4306_Desc_15 = {
    Text = "Miriam nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Giới hạn xúc thủ và số lượng xúc thủ +1, gây 1 tầng <WeaknessIconKeywords:Hư Nhược> và <VulnerabilityIconKeywords:Dễ Thương> lên tất cả kẻ địch.「Đả Kích」và「Vô Thượng Sinh Tế」của Miriam tăng 100% tỷ lệ bạo kích. Đặt 1 lá <O07CardKeyWord4:「Kỳ Lộ Tín Ngưỡng」> vào tay. Mỗi lật 2 lá「Thánh Lễ」sẽ đặt một lá「Thần Quốc Huyễn Ảnh」vào tay."
  },
