  },
  Skill_4311_AwakerSkillBackgroundStory = {
    Text = "Cảm chạm nhẹ nhàng, liệu bạn có cảm nhận được tình yêu không? \n Hơi thở ấm áp, liệu bạn có chìm đắm vào tôi không? \n Sự vuốt ve được bao quanh bởi ngọc trai và voan mỏng, đối với bạn, có phải là quà tặng không?"
  },
  Skill_4311_Desc_0 = {
    Text = "Chọn 1 thức tỉnh giả khác, khiến bản thân và thức tỉnh giả đó đều nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. Nhận [Power:Arg2] điểm <PowerIconKeywords:lực lượng>."
