  Skill_4314_AwakerSkillBackgroundStory = {
    Text = "Máu của cô ấy vì Ngài mà sôi sục, não của cô ấy vì Ngài mà sôi sục. \n Dù những con cái dị hình này có thể thực hiện nguyện vọng của cô ấy hay không, dù Ngài có thể tồn tại trong Hư vô hay không. \n Thái Di Sơ đầy yêu thương chào đón sự ra đời của mỗi Con của sự thánh thiện."
  },
  Skill_4314_Desc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Khiến các thân thể được đánh thức khác nhận được <Energy:[Energy:Arg1]> điểm điên cuồng.] Gây <Damage:[Damage:Arg2]> điểm thương cho tất cả kẻ địch, gây [Arg3]% thương tổn<BleedingIconKeywords:Chảy máu>, và áp dụng [Arg4]% thương tổn<IntoxicationIconKeywords:Ngộ độc> và nhận [Arg5]% thương tổn<RetaliateIconKeywords:phản công>. Chọn 1 thẻ lệnh không phái sinh trong tay, đặt [Arg7] bản gốc kèm theo<DepleteIconKeywords:tiêu thụ>và<NothingnessIconKeywords:Hư vô> vào tay, giảm sức tính toán tiêu thụ của nó -[Arg6]."
  },
  Skill_4314_EffectNameList = {
    Text = "Điên cuồng, sát thương, tỷ lệ chảy máu, tỷ lệ trúng độc, tỷ lệ phản công"
  },
  Skill_4314_Name = {
    Text = "Lễ hội Phong Thịnh"
  },
  Skill_4314_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Khiến các thân thể được đánh thức khác nhận được <Energy:[Energy:Arg1]> điểm điên cuồng.] Gây <Damage:[Damage:Arg2]> điểm thương cho tất cả kẻ địch, gây [Arg3]% thương tổn <BleedingIconKeywords:Chảy máu>, và áp dụng [Arg4]% thương tổn <IntoxicationIconKeywords:Ngộ độc> và nhận [Arg5]% thương tổn <RetaliateIconKeywords:phản công>. Chọn 1 thẻ lệnh không phái sinh trong tay, nhận [Arg7] bản gốc kèm theo <DepleteIconKeywords:tiêu thụ> và <NothingnessIconKeywords:hư vô>, làm giảm Điểm tính toán tiêu thụ của nó -[Arg6]. Trong 3 lượt tiếp theo, mỗi lượt bắt đầu sẽ chuyển 1 thẻ \"Phôi thai\" thành \"Con của sự thánh thiện\", nếu không có \"Phôi thai\" thì <EmbryoFusionIconKeywords:Dung hợp Phôi thai> +[Blood:Arg8], không bị ảnh hưởng bởi hiệu ứng tăng Dung hợp Phôi thai."
  },
  Skill_4314_PropertyNameList = {
