  },
  Skill_4315_AwakerSkillBackgroundStory = {
    Text = "Bảo vệ tôi. Bảo vệ tôi. Bảo vệ tôi. \n Quái vật nhút nhát, giống như cô ấy, dường như có sinh mệnh, dường như không có ý thức. \n Chất lỏng màu đen tụ lại thành thuộc hạ của cô ấy, bị điều khiển bởi mệnh lệnh suốt ngày đêm."
  },
  Skill_4315_Desc_0 = {
    Text = "Lily nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Vào đầu lượt, nhận 10% sinh lực tối đa của <PainWord:nhẫn nại>. Khi Lily áp dụng lá chắn, gây [Poison:Arg2] lớp <IntoxicationIconKeywords:ngộ độc> lên kẻ thù có sinh lực cao nhất."
  },
  Skill_4315_Desc_15 = {
    Text = "Lily nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Đầu lượt nhận <PainWord:Nhẫn Nại> bằng 10% sinh mệnh tối đa. Khi Lily thi triển khiên, thi triển [Poison:Arg2] tầng <IntoxicationIconKeywords:Trúng Độc> lên kẻ địch có sinh mệnh cao nhất. Cuồng Khí Bùng Phát khiến mỗi lần nhận tấn công trong lượt này sẽ tăng hiệu ứng tiêu hao <PainWord:Nhẫn Nại> của \"Đòn Báo Đáp\" tiếp theo 40%, tối đa cộng dồn 5 tầng."
