  Skill_4329_BattleDesc_0 = {
    Text = "Nhận <Block:[Block:Arg3]> điểm Khiên, vứt bỏ tất cả lá bài. <TransitionIconKeywords:Bước nhảy>: Không vứt bài, nhận <Block:[Block:Arg4]> điểm Khiên và rút 1 lá bài."
