  },
  Skill_4329_Desc_0 = {
    Text = "<Block:[Block:Arg1]> điểm lá chắn, bỏ tất cả bài trong tay, cứ mỗi lá bài bỏ đi, lá chắn tăng thêm 50%.<TransitionIconKeywords:nhảy vọt>: không bỏ bài và rút 1 lá bài, lá chắn nhận được tăng 100%."
  },
  Skill_4329_Desc_2 = {
