  Skill_4361_AwakerSkillBackgroundStory = {
    Text = "Cô gái trong nôi, liệu có mơ về những bông hoa chưa từng thấy không? \n Đó sẽ là bông hoa như thế nào? Liệu có giống như cô, bị giam cầm trong không gian nhỏ bé, nở ra trong chậu nhỏ bằng lòng bàn tay không? \n Hay sẽ như trong bài ca của em gái, nở rộ giữa biển sao, được bụi vũ trụ và dòng sao mang đến những nơi không biết?"
  },
  Skill_4361_Desc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>:Đưa 1 lá 「Mầm non」có tiêu hao sức tính toán bằng 0 vào tay và thêm <DepleteIconKeywords:tiêu thụ>. <WeaknessIconKeywords:yếu đuối> tất cả kẻ địch trong 2 lượt.] Nhận [Counterattack:Arg1] lớp <RetaliateIconKeywords:phản công>. Nếu <DeathResistanceIconKeywords:kháng cự tử vong> dưới [Arg2]%, thì +[Arg3]%. Loại bỏ trạng thái <FragileIconKeywords:yếu đuối> của bản thân."
  },
  Skill_4361_Desc_3 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>:Đưa 1 lá 「Mầm non」có tiêu hao sức tính toán bằng 0 vào tay và thêm <DepleteIconKeywords:tiêu thụ>. <WeaknessIconKeywords:yếu đuối> tất cả kẻ địch trong 2 lượt.] Nhận [Counterattack:Arg1] lớp <RetaliateIconKeywords:phản công>. Nếu <DeathResistanceIconKeywords:kháng cự tử vong> dưới [Arg2]%, thì +[Arg3]%. Loại bỏ trạng thái <FragileIconKeywords:yếu đuối> của bản thân."
  },
  Skill_4361_EffectNameList_0 = {
    Text = "Phản công, giới hạn kháng cự tử vong và kháng cự tử vong"
  },
  Skill_4361_Name = {
