  Skill_4365_AwakerSkillBackgroundStory = {
    Text = "Có người cố chấp cho rằng, cơ thể và linh hồn nên là một thể vĩnh cửu; cũng có người sợ hãi rằng sau khi mất đi thể xác, tâm trí lơ lửng không định sẽ dẫn đến hủy diệt. \n Phản hồi nghi ngờ trong mắt đóa là một việc phiền phức, cô ấy chọn sử dụng sự thay đổi của từng thân thể rối để chứng minh sự thành công của cuộc phẫu thuật."
  },
  Skill_4365_Desc = {
