  Skill_4368_Name = {Text = "Đánh"},
  Skill_4371_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [AttackTimes:Arg2] lần, khôi phục lượng sức sống tương đương với thương chưa bị chặn. Đặt 1 lá <DerivativeCardKeywords_34:「Nỗi Đau Chưa Được Đáp Ứng」> vào rút bài từ bộ bài."
  },
  Skill_4371_Name = {
    Text = "Đau đớn và máu"
  },
  Skill_4372_Desc = {
    Text = "Gây [Arg1] lớp <VulnerabilityIconKeywords:tăng sát thương> cho cả hai bên. Nhận được 「Lưỡi Dao II」: nếu gây thương mà không bị chặn, thêm 2 lá <DerivativeCardKeywords_23:「vết thương」> vào đầu bộ bài rút bài. Hiệu ứng kéo dài 1 lượt."
  },
  Skill_4372_Name = {
    Text = "Cuộc đấu tranh hấp hối"
  },
  Skill_4373_AwakerSkillBackgroundStory = {
    Text = "Cánh tay trước của cô có thể chém mở đường đi, đuôi đủ sức tạo nên bến cảng. \nSau khi không còn ai để chiến đấu, con cá voi khổng lồ đã chìm vào giấc ngủ trong hỗn loạn, giao phó hành tinh cho những sinh linh mới."
  },
  Skill_4373_BattleDesc_0 = {
    Text = "Loại bỏ trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch [Arg3] lần. Trong trận chiến này, mỗi lần đánh ra 1 lá \"Đánh\" sẽ tăng thương + [Arg2]."
  },
  Skill_4373_BattleDesc_3 = {
    Text = "Giải trừ trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch [Arg3] lần. Trong cuộc chiến này, mỗi khi ra 1 lá \"đánh\" sẽ tăng thương + [Arg2]. Đặt 2 lá \"đánh\" có gắn <DepleteIconKeywords:tiêu thụ> và <NothingnessIconKeywords:hư vô> vào tay."
  },
  Skill_4373_Desc_0 = {
    Text = "Giải tán trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch. Trong cuộc chiến này, mỗi lần sử dụng 1 lá \"đánh\" sẽ tăng thương +[Arg2]."
  },
  Skill_4373_Desc_15 = {
    Text = "Giải trừ trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch [Arg3] lần. Trong cuộc chiến này, mỗi khi ra 1 lá \"đánh\" sẽ tăng thương + [Arg2]. Đặt 2 lá \"đánh\" có gắn <DepleteIconKeywords:tiêu thụ> và <NothingnessIconKeywords:hư vô> vào tay."
  },
  Skill_4373_Desc_3 = {
    Text = "Giải trừ trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch [Arg3] lần. Trong cuộc chiến này, mỗi khi ra 1 lá \"đánh\" sẽ tăng thương + [Arg2]. Đặt 2 lá \"đánh\" có gắn <DepleteIconKeywords:tiêu thụ> và <NothingnessIconKeywords:hư vô> vào tay."
