  Skill_4373_EffectNameList = {
    Text = "Thương, thương"
  },
  Skill_4373_Name = {
    Text = "quái thú hỗn loạn"
  },
  Skill_4373_OverLimitUtlSkillDesc_0 = {
    Text = "Xua tan trạng thái <WeaknessIconKeywords:Suy nhược> của bản thân. Gây <Damage:[Damage:Arg1]> điểm sát thương lên tất cả kẻ thù. Trong trận chiến này, mỗi khi chơi 1 thẻ \"Đánh\" thì sát thương +[Arg2]. Gây thêm 1 lần <FixedDamage:Sát Thương Thuần Túy> bằng 15% Sinh lực tối đa của mục tiêu lên tất cả kẻ thù. Sát thương cơ bản của \"quái thú hỗn loạn\" trong trận chiến này tăng 100%."
  },
  Skill_4373_OverLimitUtlSkillDesc_3 = {
    Text = "Xua tan trạng thái <WeaknessIconKeywords:Suy nhược> của bản thân. Gây <Damage:[Damage:Arg1]> điểm sát thương lên tất cả kẻ thù [Arg3] lần. Trong trận chiến này, mỗi khi chơi 1 thẻ \"Đánh\" thì sát thương +[Arg2]. Đặt 2 thẻ \"Đánh\" được gắn thêm <DepleteIconKeywords:tiêu hao> và <NothingnessIconKeywords:Hư vô> vào tay. Gây thêm 1 lần <FixedDamage:Sát Thương Thuần Túy> bằng 15% Sinh lực tối đa của mục tiêu lên tất cả kẻ thù. Sát thương cơ bản của \"quái thú hỗn loạn\" trong trận chiến này tăng 100%."
  },
  Skill_4373_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1, sức tấn công*GrowValue2"
