  Skill_4374_Desc = {
    Text = "Chỉ là vết thương nhỏ, không đáng kể. Nhận [Arg1] điểm <FixedDamage:Sát Thương Thuần Túy>, rút [Arg3] thẻ bài."
  },
  Skill_4374_Name = {
    Text = "vết thương"
  },
  Skill_4375_AwakerSkillBackgroundStory = {
    Text = "Từng bước, cô ấy từ từ bước vào trong làn nước biển. \n Vừa chạm vào da, làn nước đêm vẫn có chút lạnh lẽo, nhưng lúc này lại ấm áp như cái ôm của con người. \n Biển đã chấp nhận tôi, những suy nghĩ như vậy lặng lẽ bay vào đầu Ninh Phi Nga. \n Trong chốc lát, cô ấy nhìn thấy nụ cười của cha mẹ. Ở sâu trong biển, chắc chắn có sự an lạc của tình thân đúng không."
  },
  Skill_4375_Desc_0 = {
    Text = "Nymphaea nhận được <Energy:[Energy:Arg1]> điểm điên cuồng.<ExaltIconKeywords:Đánh thức>:Sau khi Nymphaea sử dụng thẻ, nhận thêm <Energy:[Energy:Arg2]> điểm điên cuồng. Vào cuối lượt đấu, tăng trạng thái gây độc của Nymphaea lên [Arg3]%."
  },
  Skill_4375_Desc_15 = {
    Text = "Nymphia nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Sau khi Nymphia đánh ra bài, nhận <Energy:[Energy:Arg2]> điểm Cuồng Khí. Khi kết thúc lượt, tăng Trúng Độc do Nymphia gây ra [Arg4]%."
  },
  Skill_4375_EffectNameList = {
