  Skill_4379_AwakerSkillBackgroundStory = {
    Text = "Tuyên bố: \n Những kẻ tầm thường không thể cảm nhận vẻ đẹp của nghệ thuật, những kẻ vui mừng trong sự đau khổ của vũ công, những kẻ tham lam với danh vọng và lợi lộc. \n Đây chính là con đường kết thúc của các ngươi. \n Dâng tặng cho các ngươi điệu Vũ điệu báo tử này, để Lửa Xanh thanh tẩy linh hồn của các ngươi, để ngọn lửa tuyệt đẹp cuốn đi trái tim bẩn thỉu của các ngươi. \n Hẹn gặp lại chúng ta ở miền đất thanh khiết vĩnh cửu."
  },
  Skill_4379_Desc_0 = {
    Text = "Được [Power:Arg1] điểm <PowerIconKeywords:lực lượng> tạm thời. Loại bỏ tất cả các lá bài Liz trên tay và kích hoạt hiệu ứng tương ứng."
