  Skill_4379_OverLimitUtlSkillDesc_0 = {
    Text = "Nâng cấp tất cả \"Lửa Xanh\" và \"Ngọn lửa xanh bị hư hỏng\" trong tay thành \"Ngọn Lửa Xanh Của Sự Diệt Vong\", sau đó trong [Arg2] lượt, mỗi khi bắt đầu lượt sẽ lặp lại hiệu ứng này 1 lần. Nhận [Arg1] điểm <PowerIconKeywords:Sức mạnh> tạm thời. Bỏ tất cả thẻ bài của Liz trong tay và kích hoạt hiệu ứng của chúng."
  },
  Skill_4379_OverLimitUtlSkillDesc_3 = {
