  Skill_4381_AwakerSkillBackgroundStory = {
    Text = "Thời khắc biến thân đã đến. \n Người kế thừa là sự tồn tại cao quý hơn người phàm. \n Từ bỏ người thân, từ bỏ bạn bè, từ bỏ đau đớn, từ bỏ tất cả quá khứ. \n Tôi sẽ nhận được sự che chở của vinh quang. \n Bề mặt cơ thể anh ta mọc đầy vảy sắc nhọn."
  },
  Skill_4381_Desc_0 = {
    Text = "Kẻ khắc sét nhận được <Energy:[Energy:Arg1]> điểm điên cuồng.<ExaltIconKeywords:Khai mở linh trí>: nhận 1 xúc tu, mỗi khi Kẻ khắc sét chơi 1 thẻ bài, hồi phục <Heal:[Heal:Arg2]> điểm sinh lực và nhận [Counterattack:Arg3] cấp <RetaliateIconKeywords:phản công>."
  },
  Skill_4381_Desc_15 = {
