  Skill_4407_AwakerSkillBackgroundStory = {
    Text = "Da của cô ấy xanh lét, những mạch máu thối rữa không ngừng vặn vẹo, xoắn chặt. \nVai của cô ấy dường như đang ấp ủ thứ gì đó — chất lỏng màu đen từ từ chảy dọc theo cánh tay cô, lan rộng trên bàn mổ. \nNhững mảnh huyết nhục non nớt bừng nở từ vết loét, tranh nhau vươn ra, nhẹ nhàng và im lặng. \nCô gái mệt mỏi khẽ mỉm cười. \n \"Cuối cùng chúng ta lại gặp nhau rồi, @2.\""
  },
  Skill_4407_Desc_0 = {
    Text = "Ngẫu nhiên gây <Damage:[Damage:Arg1]> điểm sát thương [Arg2] lần. Cho đến khi bắt đầu lượt tiếp theo, cứ mỗi 2 điểm sức sống bị mất, sẽ nhận được 1 điểm lá chắn vào đầu lượt tiếp theo."
  },
  Skill_4407_Desc_1 = {
    Text = "Gây ngẫu nhiên [Arg2] lần <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:thương xuyên thủng>. Trước khi lượt tiếp theo bắt đầu, cứ mỗi 2 điểm sức sống mất đi, bạn sẽ nhận 1 điểm lá chắn vào đầu lượt."
