  Skill_4408_AwakerSkillBackgroundStory = {
    Text = "Không có loại ánh sáng này trong quang phổ đã biết của con người. \nNó lấp lánh như cực quang, xa xôi như cực quang và cũng chớp nhoáng như cực quang."
  },
  Skill_4408_Desc_0 = {
    Text = "Nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>. Tỷ lệ chí mạng tạm thời +[Arg2]%. Trong trận chiến này, sát thương cơ bản của kỹ năng \"đánh\" của Tinkerer tăng [Arg3]%. Làm 5 lá bài ngẫu nhiên trên tay giảm 1 sức tính toán cho đến hết lượt."
  },
  Skill_4408_Desc_3 = {
    Text = "Nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>. Tỷ lệ chí mạng và thương harming chí mạng tạm thời tăng +[Arg2]%. Trong trận chiến này, sát thương cơ bản của \"đánh\" của Tinkerer tăng [Arg3]%. Giảm tiêu hao sức tính toán của 5 lá bài ngẫu nhiên trong tay đi -1 cho đến cuối lượt."
  },
