  },
  Skill_4412_AwakerSkillBackgroundStory = {
    Text = "Dây roi trở nên \"trăm lần không nản\" do cuồng khí tràn đầy, luôn luôn tươi sáng và rực rỡ, bất kể thời gian hay địa điểm, đều có thể mang lại cho bạn sự đau đớn mà bạn khao khát."
  },
  Skill_4412_Desc_0 = {
