  Skill_4413_AwakerSkillBackgroundStory = {
    Text = "Sau khi nhập ngũ, cô chiến đấu ở tiền tuyến, dù bị thương tật cũng không muốn rút lui, chỉ vì cô thực sự tin rằng \"thế giới tốt đẹp hơn\" sẽ đến. \nNhưng lời nói dối cuối cùng cũng sẽ sụp đổ. Lần này, cô cầm vũ khí không phải vì lời hứa hẹn giả tạo đó, mà là vì điều đúng đắn trong lòng cô."
  },
  Skill_4413_Desc_0 = {
    Text = "Alva nhận được <Energy:[Energy:Arg1]> điểm điên loạn. <ExaltIconKeywords:khai mở linh trí>: Nhận được [Arg2] điểm <AlertIconKeywords:báo động>. Sát thương từ thẻ lệnh của Alva tăng theo lượng khiên hiện tại, mỗi điểm khiên tăng thêm 2."
