  Skill_4421_AwakerSkillBackgroundStory = {
    Text = "Cô ấy múa dưới ánh trăng khuyết. \n Vạt váy cuốn quanh cánh tay, xoay tròn như một đám mây. \n Dưới chân cô, hồ nước rộng lớn chảy mãi không ngừng, dần hòa quyện với bầu trời. \n Nhảy đi. Nhảy đi. Giọng nói trong bóng tối nói. \n Hoán tỉnh người lớn đang say giấc, rồi thực hiện lời hứa ngàn năm ấy đi."
  },
  Skill_4421_Desc_0 = {
    Text = "Gia Lân nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>:Gia Lân đánh ra thẻ bài, hồi phục <Heal:[Heal:Arg2]> điểm sức sống, nhận được <Energy:[Energy:Arg3]> điểm điên cuồng. Đánh ra<DerivativeCardKeywords_42:「Món Ăn Kỳ Diệu」>sau, gây [Poison:Arg4] lớp<IntoxicationIconKeywords:trúng độc> cho tất cả kẻ địch."
  },
  Skill_4421_Desc_15 = {
    Text = "Garen nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Sau khi Garen đánh ra lá bài, hồi phục <Heal:[Heal:Arg2]> điểm sinh mệnh, nhận được <Energy:[Energy:Arg3]> điểm Cuồng Khí. Khi kết thúc lượt nếu giữ lại bài chỉ lệnh của Garen, kích hoạt 2 lần hiệu ứng hồi phục sinh mệnh và nhận Cuồng Khí. Sau khi đánh ra <DerivativeCardKeywords_42:「Món Ăn Kỳ Diệu」>, áp dụng [Poison:Arg4] tầng <IntoxicationIconKeywords:Trúng Độc> lên tất cả kẻ địch."
