  Skill_4442_Name = {Text = "Đánh"},
  Skill_4443_AwakerSkillBackgroundStory = {
    Text = "Cô ấy từng từ đỉnh cao rơi xuống, vinh quang ngày xưa hóa thành nhục nhã hôm nay. \n Sau khi bị trục xuất khỏi khu vườn của Bà Quan Trị, Hiro trở thành một trong vô số nô lệ Hiro bình thường, mặc cho cai ngục Sparta xâm hại. Trong hoàn cảnh tuyệt vọng như vậy, cô ấy chưa bao giờ rơi vào sự chán nản và uể oải. \n Trong lồng ngực của cô ấy đang cháy bỏng, chỉ có sự thù hận kéo dài không dứt. \n Xích khóa mũi nhọn ở cổ cô ấy bị xé nát không thương tiếc, sức mạnh bị giam giữ bên trong được giải phóng, diện mạo thật sự sắp được tiết lộ. \n Từ giờ trở đi, hãy thường xuyên rửa sạch cổ của bạn, chờ đợi sự báo thù của tôi nhé."
  },
  Skill_4443_Desc = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Rút [Arg1] lá \"Đánh\", giới hạn bài tay tạm thời +2, làm tăng sát thương cơ bản của Hiro với \"Đánh\" trong trận chiến này lên [Arg3]%.] Giải tán trạng thái <WeaknessIconKeywords:yếu đuối> và trạng thái giảm <PowerIconKeywords:lực lượng> không vĩnh viễn, trong lượt này, sát thương gây ra bởi \"Đánh\" tăng lên [Arg2]%, sát thương của Hiro tăng lên [Arg4]%."
  },
