  Skill_4481_Desc_0 = {
    Text = "Vanda nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Ngay lập tức nhận 5 lớp <DreamGuide:Dẫn mộng>. Sau khi bắt đầu lượt, nhận 1 lớp <DreamGuide:Dẫn mộng>. Mỗi khi nhận được <DreamGuide:Dẫn mộng> làm cho nó đạt 5 hoặc 10 lớp, nhận <Block:[Block:Arg2]> điểm lá chắn."
  },
  Skill_4481_Desc_15 = {
    Text = "Wanda nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Lập tức nhận 5 tầng <DreamGuide:Mộng Dẫn>. Sau khi bắt đầu lượt nhận 1 tầng <DreamGuide:Mộng Dẫn>. Mỗi khi nhận <DreamGuide:Mộng Dẫn> đạt 5 hoặc 10 tầng, nhận <Block:[Block:Arg2]> điểm khiên. Sau khi Wanda giải phóng Cuồng Khí Bùng Phát, 2 lá chỉ lệnh tiếp theo của bản thân kích hoạt thêm 1 lần."
