  Skill_4506_AwakerSkillBackgroundStory = {
    Text = "Đó là biển nguyên chất vô tận, truyền thuyết kể rằng mọi sinh vật hữu cơ trên hành tinh đều sinh ra từ đó. \nTrong đại dương xám, nhiều mặt nổi lơ lửng, chứa đựng nụ cười hay lòng từ bi."
  },
  Skill_4506_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương cho tất cả kẻ địch, sát thương này được hưởng hệ số tăng sức mạnh [Arg4] lần. Tạo 1 thẻ \"Hình Ảnh Ngàn Mặt\" tùy chỉnh đặt vào Tay, nếu hiện tại không phải Vòng Siêu Chiều và <DimensionalSpaceIconKeywords:Khoảng không gian siêu việt> không có \"Hình Ảnh Ngàn Mặt\", sao chép đặt vào <DimensionalSpaceIconKeywords:Khoảng không gian siêu việt> và coi như đã kích hoạt 1 lần <SingularityKeywords3:Xuyên Không Chiều Không Gian>, nếu không thì đặt 1 thẻ <DerivativeCardKeywords_4:\"Cảm hứng\"> vào tay."
  },
