  Skill_4529_Desc_0 = {
    Text = "Chọn: <B02AFKeyWord2:hiến dâng>, <B02AFKeyWord3:Siêu độ> hoặc <B02AFKeyWord4:Cứu chuộc>. Nhận <Energy:[Energy:Arg5]> điểm điên cuồng. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch, trong trận này mỗi khi tích lũy 1 điểm hồi phục từ lò nung đỏ thẫm, sẽ làm tăng sát thương lên [Float:Arg2] điểm."
  },
  Skill_4529_Desc_2 = {
    Text = "Lựa chọn: <B02AFKeyWord2:hiến dâng>, <B02AFKeyWord3:Siêu độ> hoặc <B02AFKeyWord4:Cứu chuộc>. Nhận <Energy:[Energy:Arg5]> điểm điên cuồng. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch, trong trận này mỗi khi tích lũy 1 điểm hồi phục từ Lò nung đỏ thẫm, sát thương sẽ tăng lên [Float:Arg2] điểm. Tỉ lệ chí mạng của sát thương này tăng lên [Arg4]%."
