  Skill_4546_AwakerSkillBackgroundStory = {
    Text = "Jenkin cũng không phải ngay từ đầu đã hiểu brun. \n Không được, cô nghĩ, như vậy brun sẽ không thể thu hút sự chú ý của những ông chủ tự cho là sang trọng trên phố, để cô có thể lấy bữa tối hôm nay từ túi của họ. \n Vì vậy, cô bắt đầu huấn luyện dưới ánh đèn dầu, và sau nhiều ngày thử thách, cuối cùng — \n \"brun, xuất phát!\"\n \"Xịt!\""
  },
  Skill_4546_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương. Trong trận chiến này, sát thương gây ra bởi \"Brâu ra trận!\" tăng [Arg2] điểm. Nhảy vọt: thay đổi để gây thương cho tất cả kẻ địch, nhưng sau khi sử dụng sẽ <DepleteIconKeywords:tiêu thụ>."
  },
  Skill_4546_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương. Trong trận chiến này, sát thương từ \"Brâu ra trận!\" tăng [Arg2] điểm và sát thương từ \"đám chuột xông tới\" tăng [Arg3] điểm. Nhảy vọt: gây sát thương lên tất cả kẻ địch, nhưng sau khi sử dụng sẽ <DepleteIconKeywords:tiêu thụ>."
