  },
  Skill_4579_AwakerSkillBackgroundStory = {
    Text = "Phù thủy nói: \"Họ là những kẻ ngoại đạo đông đúc.\nChúng ta ở Levant dường như yếu thế.\nYu U Hahi, hãy thổi sừng của ngươi,\nvà chiến đấu như một kẻ điên cuồng.\"\nChiến binh đáp: \"Ở đây không có kẻ ngoại đạo.\nTất cả các ngươi đều sẽ bị ta giết chết, người chết không phân biệt tộc quần hay tín ngưỡng.\nKhi đó, xác chết sẽ phủ kín thung lũng và đỉnh núi,\nđó chính là khúc ca dâng tặng máu và cát mà ta viết nên.\""
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Trong trận chiến này, sát thương của \"Bài ca Máu và Cát\" khi được tung ra sau sẽ tăng [Arg4] điểm, tỷ lệ lực lượng tăng [Arg3] lần.] Gây <Damage:[Damage:Arg1]> điểm thương lên tất cả kẻ địch. <PowerIconKeywords:lực lượng> Phát huy hiệu ứng [Arg2] lần trên \"Bài ca Máu và Cát\". Yu U Hahi nhận được <Energy:[Energy:Arg5]> điểm điên cuồng."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Sát thương của \"Bài ca ngợi máu và cát\"được phát động sau trong trận đấu tăng [Arg4] điểm, hệ số lực lượng tăng [Arg3] lần.] Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch. <PowerIconKeywords:lực lượng> phát huy hiệu ứng [Arg2] lần trên \"Bài ca ngợi máu và cát\". Nhận lượng điên cuồng tương đương với nạp năng lượng điên cuồng của Yu U Hahi."
  },
  Skill_4579_EffectNameList = {
    Text = "Thương, tăng sát thương"
