  Skill_4579_Name = {
    Text = "Bài ca ngợi máu và cát"
  },
  Skill_4579_OverLimitUtlSkillDesc = {
    Text = "【<DevouredIconKeywords:Nuốt chửng>: Sát thương của \"Lời ca của máu và cát\" phát hành sau trận chiến này được tăng thêm [Arg4] điểm, tỷ lệ sức mạnh tăng thêm [Arg3] lần.】Gây <Damage:[Damage:Arg1]> điểm sát thương cho tất cả kẻ địch. <PowerIconKeywords:Sức mạnh> có hiệu lực [Arg2] lần trên \"Lời ca của máu và cát\". Uvhash nhận được <Energy:[Energy:Arg5]> điểm Aliemus. \"Hãy thét lên, máu!\" bị ảnh hưởng ảo giác và kiệt sức sẽ được điền đầy tay. Số lần Uvhash gây sát thương trong lượt này tăng 1"
  },
  Skill_4579_PropertyNameList = {
