  Skill_4580_Desc = {
    Text = "Gọi một \"Đèn lồng\" phía sau bản thân."
  },
  Skill_4580_Name = {
    Text = "Lễ thánh"
  },
  Skill_4581_AwakerSkillBackgroundStory = {
    Text = "Dưới thánh đường có một không gian ẩn giấu. \n\nGiáo sĩ quỳ trước bảng đá, ngâm nga Mật ngữ còn sót lại từ thuở sáng thế. \n\nNhững phù văn bị thời gian lãng quên phát ra ánh sáng phản hồi, hiện ra hình bóng khổng lồ theo ý chí của giáo sĩ, ban xuống phúc lành của Đấng Tạo Hóa cho những người đang được bao bọc trong ánh sáng của Ngài."
  },
  Skill_4581_Desc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng> tạm thời, tỷ lệ chí mạng tạm thời +[Arg4]%.] Nhận <Block:[Block:Arg2]> điểm lá chắn. <VulnerabilityIconKeywords:Trọng thương> tất cả kẻ địch 1 lượt. Cho đến khi bắt đầu lượt sau, khi bị tấn công sẽ chuyển đổi [Arg3]% thương thành lượng hồi phục từ lò nung đỏ thẫm."
  },
  Skill_4581_Desc_3 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Nhận được [Power:Arg1] điểm tạm thời <PowerIconKeywords:lực lượng>, tỷ lệ chí mạng tạm thời +[Arg4]%.] Nhận được <Block:[Block:Arg2]> điểm lá chắn. <VulnerabilityIconKeywords:Trọng thương> tất cả kẻ địch 1 lượt. Đến khi bắt đầu lượt tiếp theo, khi bị tấn công sẽ chuyển đổi [Arg3]% sát thương thành lượng hồi phục từ lò nung đỏ thẫm. Salvador nhận được [Arg5]% sát thương bạo kích tạm thời."
  },
  Skill_4581_EffectNameList = {
