  },
  Skill_4581_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Nuốt chửng>: Nhận [Power:Arg1] điểm <PowerIconKeywords:Sức mạnh> tạm thời, Tỷ lệ chí mạng tạm thời +[Arg4]%.] Nhận <Block:[Block:Arg2]> điểm lá chắn. Gây <VulnerabilityIconKeywords:Trọng thương> cho tất cả kẻ địch 1 lượt. Cho đến khi bắt đầu lượt tiếp theo, khi nhận tấn công sẽ chuyển hóa [Arg6]% sát thương thành lượng hồi phục Lò nung đỏ thẫm. Khiến \"Đánh cơ bản\" và \"đau khổ phải tiêu trừ\" của Salvador được hưởng thêm 100% cộng thêm Sức mạnh. Trong lần khám phá này, giới hạn trên của Lò nung đỏ thẫm tăng thêm 2% Sinh lực tối đa, tối đa tăng 10%."
