  },
  Skill_4604_Desc_15 = {
    Text = "Ogier nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Nhận [Power:Arg3] điểm <PowerIconKeywords:Sức Mạnh>, sau khi Ogier đánh ra lá bài, nhận [Power:Arg2] điểm <PowerIconKeywords:Sức Mạnh>. Sau khi kích hoạt kháng tử vong trong trận chiến này, <PowerIconKeywords:Sức Mạnh> tạm thời nhận được từ Cuồng Khí Bộc Phát của Ogier tăng lên gấp 3 lần."
