  Skill_4615_AwakerSkillBackgroundStory = {
    Text = "Phiệt là khiếm khuyết. \nPhiệt là nguy hiểm. \nPhiệt là bị nguyền rủa. \nPhiệt, là sắc màu kỳ bí và rực rỡ nhất từ các vì sao."
  },
  Skill_4615_BattleDesc_15 = {
    Text = "Phiệt nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Lập tức vĩnh viễn Đánh cắp [Arg4] điểm <PowerIconKeywords:sức mạnh> của tất cả kẻ thù. Nhận [Counterattack:Arg3] lớp <RetaliateIconKeywords:phản công>. Tỷ lệ suy giảm khi kích hoạt kháng cự tử vong trong trận chiến này giảm từ 50% xuống 45%. Khi Phiệt chơi thẻ bài, <TouquKeywords:Đánh cắp> [Arg2] điểm <PowerIconKeywords:sức mạnh> của tất cả kẻ thù. Khi kết thúc lượt, kích hoạt 50% <RetaliateIconKeywords:phản công> lên kẻ thù hàng trước."
  },
  Skill_4615_Desc_0 = {
    Text = "Phiệt nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Nhận [Counterattack:Arg3] lớp <RetaliateIconKeywords:phản công>. Tỷ lệ suy giảm khi kích hoạt kháng cự tử vong trong trận chiến này giảm từ 50% xuống 45%. Khi Phiệt chơi thẻ bài, <TouquKeywords:Đánh cắp> [Arg2] điểm <PowerIconKeywords:sức mạnh> của tất cả kẻ thù. Khi kết thúc lượt, kích hoạt 50% <RetaliateIconKeywords:phản công> lên kẻ thù hàng trước."
  },
  Skill_4615_Desc_15 = {
    Text = "Phiệt nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Lập tức vĩnh viễn Đánh cắp [Arg4] điểm <PowerIconKeywords:sức mạnh> của tất cả kẻ thù. Nhận [Counterattack:Arg3] lớp <RetaliateIconKeywords:phản công>. Tỷ lệ suy giảm khi kích hoạt kháng cự tử vong trong trận chiến này giảm từ 50% xuống 45%. Khi Phiệt chơi thẻ bài, <TouquKeywords:Đánh cắp> [Arg2] điểm <PowerIconKeywords:sức mạnh> của tất cả kẻ thù. Khi kết thúc lượt, kích hoạt 50% <RetaliateIconKeywords:phản công> lên kẻ thù hàng trước."
