  Skill_4616_Desc = {
    Text = "Nhận [Arg1] điểm lá chắn, khi gây thương không bị chặn sẽ hồi 3 lần lượng thương đó thành sức sống, kéo dài [Arg2] lượt, tiến lên."
  },
  Skill_4616_Name = {
    Text = "Sẵn sàng phẫu thuật"
  },
  Skill_4617_AwakerSkillBackgroundStory = {
    Text = "Trong tiếng khóc tuyệt vọng của người thủy thủ, cô ấy yên lặng nhìn, chờ đợi. \n Mặt biển bình lặng nổi lên bong bóng, những râu chạm khổng lồ từ đó vươn lên, nhanh chóng quấn quanh cột buồm và trong gió biển mở ra thành những cánh buồm mới. \n \"Khởi hành, khởi hành!\" các thủy thủ hát, \"Chúng ta khởi hành trong hình bóng!\""
  },
  Skill_4617_Desc = {
    Text = "Phục hồi <Heal:[Heal:Arg1]> điểm sinh lực. Tạm thời <TentacleInjurieIconKeywords:thương tổn xúc tu> +[TentaclePower:Arg2]. Gây 1 lượt <WeaknessIconKeywords:Suy nhược> cho tất cả kẻ địch. Kích hoạt 1 râu chạm tấn công kẻ địch, gây [Arg3]% thương tổn râu chạm."
