  Skill_4618_AwakerSkillBackgroundStory = {
    Text = "Bạn đã từng cảm thấy mình là tâm điểm của ánh đèn, là trung tâm của vũ trụ, là đứa con cưng của Chúa chưa? \n Đối với Lắc, đó chính là khoảnh khắc nhẹ nhàng liếc nhìn lá bài, rồi bình thản lật mở nó ra."
  },
  Skill_4618_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương 1~[Arg4] lần, nhận <Energy:[Energy:Arg2]> điểm điên cuồng. Nếu gây 6 lần hoặc nhiều hơn thương, nhận 1 lá \"thu hoạch bất ngờ\" có sức tính toán tiêu thụ là 0 và chi phí phụ thêm."
  },
  Skill_4618_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương 1~[Arg4] lần, nhận <Energy:[Energy:Arg2]> điểm điên cuồng, mỗi lần chí mạng, nhận thêm <Energy:[Arg3]> điểm điên cuồng. Nếu gây 6 lần hoặc nhiều hơn thương, nhận 1 lá có sức tính toán tiêu thụ là 0 và chi phí phụ thêm <DepleteIconKeywords:tiêu thụ>\"thu hoạch bất ngờ\"."
