  Skill_4635_AwakerSkillBackgroundStory = {
    Text = "Có một loại lực lượng cổ xưa đang tái sinh trong cơ thể Muphí. \n Hạt giống được gieo trồng, ngày qua ngày thành những nụ hoa hư ảo. \n \"Vì đã được ban cho lực lượng này, để ta cho các ngươi thấy khả năng của ta!\""
  },
  Skill_4635_Desc = {
    Text = "Tất cả kẻ địch giảm thương tổn [Arg1]%, nhưng khi bị tấn công sẽ nhận một nửa thương tổn dưới dạng <SacrificeKeyWord:hiến tế>, kéo dài 1 lượt. Nhận <Block:[Block:Arg2]> điểm lá chắn, cho phép tất cả xúc tu tấn công 1 lần."
