  Skill_4638_AwakerSkillBackgroundStory = {
    Text = "Lưỡi dao sắc được chế tạo từ một khối sắt nguyên chất nặng không thể tưởng tượng, khi vung lên tạo ra dòng khí mạnh đến mức có thể làm vỡ đá. \n Người bạn trung thành của tôi, thanh đại đao đáng tin cậy của tôi, chúng ta đều đã có được sinh mới và sức mạnh vô hạn trong bóng tối. Tối nay, chúng ta sẽ say sưa trong máu của kẻ thù; tối nay, chúng ta sẽ thoải mái giết chóc."
  },
  Skill_4638_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch. <PowerIconKeywords:lực lượng> có hiệu ứng [Arg2] lần trên \"Sức mạnh của Lưỡi đao khổng lồ\". Thẻ này được coi là một \"Đòn đánh\"."
