  Skill_46433_Name_1 = {Text = "Hư vô"},
  Skill_4643_AwakerSkillBackgroundStory = {
    Text = "\"Không, không. Đây không phải là logic của sự sáng tạo.\"\nNhà điêu khắc trầm giọng nói, nhưng không dám nhìn thẳng vào mắt người đệ tử trẻ.\nĐó là một đôi mắt như thế nào —\nYên lặng như đại dương ở tận cùng thế giới, thu hết sự giãy dụa của những con chim di cư sắp chết.\nNàng biết tất cả, nhưng vẫn im lặng không nói."
