  Skill_4643_PropertyNameList_2 = {
    Text = "Khả năng phòng thủ*GrowValue1,khả năng phòng thủ*GrowValue2"
  },
  Skill_4644_AwakerSkillBackgroundStory = {
    Text = "Con tàu rời bến lạc lối trong gió, những con thú tách biệt tạo nên những cơn sóng lớn. \n Sự cuồng nhiệt của cô ấy đã ảnh hưởng đến sự tồn tại của nền văn minh nhân loại nhiều lần, nhưng cô ấy không hề quan tâm. \n Đối với những con thú, không có gì quan trọng hơn việc tìm lại nơi cư trú."
  },
  Skill_4644_Desc_0 = {
    Text = "Gây ra <Damage:[Damage:Arg1]> điểm thương và lượng <IntoxicationIconKeywords:ngộ độc> tương ứng, hưởng [Arg4]% <TentacleInjurieIconKeywords:thương tổn xúc tu> tăng cường. Tạo ra [Arg2] râu chạm tạm thời. <TentacleInjurieIconKeywords:Thương tổn xúc tu> +[TentaclePower:Arg3]."
