  Skill_4653_Name = {
    Text = "Cắt phẫu thuật"
  },
  Skill_4654_Desc = {
    Text = "Nhận được [Arg1] điểm lá chắn. Lá chắn nhầy do Lily gọi chỉ có thể chống lại một lần xé rách của chó địa ngục. Thật sự… không đau sao?"
  },
  Skill_4654_Name = {
    Text = "bông hoa bất diệt trên bùn lầy"
  },
  Skill_4655_AwakerSkillBackgroundStory = {
    Text = "Biển cả sâu thẳm và yên bình, nó mang trong mình khao khát sống và nỗi sợ chết. \nNhưng lại có người muốn dùng tiếng cười và sự tinh nghịch để lấp đầy đại dương — khi Ô Ryta đưa ra lời mời như vậy, cảm giác \"chơi đùa cùng cô ấy một chút cũng không tệ\" luôn dâng lên trong lòng, để niềm vui thuần khiết lan tỏa khắp tâm hồn."
  },
  Skill_4655_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương. Tiêu thụ tối đa 10 lá \"Tuyến Phân Chia\" từ rút bài từ bộ bài và rác bài, mỗi lá gây thêm 1 lần thương. Đặt 2 lá \"Tuyến Phân Chia\" vào tay. Tăng thương mà \"Ô Ryta\" gây ra trong phần còn lại của chiến đấu lên [Arg2] điểm."
  },
  Skill_4655_Desc_2 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm<PunctureDamagewords:thương xuyên thủng>. Tiêu thụ tối đa 10 lá \"Phân chia tuyến\" từ rút bài từ bộ bài và rác bài, mỗi lá tăng thêm 1 điểm thương. Đặt 2 lá \"Phân chia tuyến\" vào tay. Tăng [Arg2] điểm thương mà \"Ô Ryta\" gây ra trong phần còn lại của trận chiến."
  },
  Skill_4655_EffectNameList = {
    Text = "Thương, tăng sát thương theo thời gian"
  },
  Skill_4655_Name = {
    Text = "Biển ồn ào"
  },
  Skill_4655_OverLimitUtlSkillDesc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương. Tiêu thụ tối đa 10 thẻ \"Phân chia tuyến\" trong rút bài từ bộ bài và rác bài, mỗi thẻ gây thêm 1 lần thương. Đặt 2 thẻ \"Phân chia tuyến\" vào tay. Tăng sát thương mà \"Ô Ryta\" gây ra trong phần còn lại của trận chiến này thêm [Arg2] điểm. Nhận [Power:Arg2] điểm <PowerIconKeywords:Sức mạnh> và [TentaclePower:Arg2] điểm <TentacleInjurieIconKeywords:thương tổn xúc tu>, sau đó 5 lần chơi \"Phân chia tuyến\" tiếp theo, mỗi lần sẽ Rút 1 thẻ bài."
  },
  Skill_4655_OverLimitUtlSkillDesc_2 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:sát thương đâm> và tiêu hao tối đa 10 thẻ \"phân tách tuyến\" từ chồng bốc thăm và chồng bài bỏ, mỗi thẻ gây thêm 1 lần sát thương. Thêm 2 thẻ \"phân tách tuyến\" vào tay. Tăng sát thương do \"Aurita\" gây ra trong trận chiến thêm [Arg2] điểm. Nhận [Power:Arg2] điểm <PowerIconKeywords:sức mạnh> và [TentaclePower:Arg2] điểm <TentacleInjurieIconKeywords:thiệt hại xúc tu>, trong 5 lần tiếp theo, mỗi khi chơi \"phân tách tuyến\", đều sẽ bốc 1 thẻ."
