  Skill_4658_AwakerSkillBackgroundStory = {
    Text = "Tay của Kassia trống trải;\nMũ của Kassia trống trải;\nNgực của Kassia trống trải.\nKassia mang trong mình niềm vui trống trải, hòa vào một cuộc vui lặng lẽ với màn trình diễn cô đơn."
  },
  Skill_4658_Desc_0 = {
    Text = "Kasia nhận được <Energy:[Energy:Arg1]> điểm điên cuồng, <ExaltIconKeywords:Thức tỉnh linh tri thức>: Kasia mỗi lần đánh ra 1 thẻ bài, nhận được [Power:Arg2] điểm tạm thời <PowerIconKeywords:lực lượng>."
