  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Một hai, một hai...\nCô ấy cầm đĩa, di chuyển nhanh nhẹn theo nhịp điệu giữa đám đông.\nKhách mời liên tục uống rượu, hát hò, còn cô thì không ngừng phục vụ món ăn, mỉm cười.\nMọi thứ ở đây đều là màu vàng. Đại sảnh màu vàng, rượu vang màu vàng, và cả gấu váy màu vàng.\nGia Lân thích màu vàng. Cô ấy nở nụ cười quen thuộc đã được luyện tập hàng nghìn lần.\n \"Quý khách xin mời dùng ——!!\""
  },
  Skill_4660_Desc_0 = {
    Text = "Loại bỏ trạng thái <SlowIconKeywords:chậm chạp> của tất cả các lá bài trong tay. Khôi phục <Heal:[Heal:Arg1]> điểm sức sống. Đặt 1 lá <DerivativeCardKeywords_42:「món ăn kỳ diệu」> vào tay. Gây [Poison:Arg2] lớp <IntoxicationIconKeywords:trúng độc> cho tất cả kẻ địch."
  },
  Skill_4660_Desc_3 = {
    Text = "Loại bỏ trạng thái <SlowIconKeywords:chậm chạp> của tất cả các lá bài trong tay. Khôi phục <Heal:[Heal:Arg1]> điểm sức sống. Đưa 1 lá <DerivativeCardKeywords_43:「Đặc sản kỳ diệu」> vào tay. Áp dụng [Poison:Arg2] lớp <IntoxicationIconKeywords:trúng độc> lên tất cả kẻ địch."
