  Skill_4660_Name = {
    Text = "Khách quan, xin hãy từ từ dùng!"
  },
  Skill_4660_OverLimitUtlSkillDesc_0 = {
    Text = "Xóa Trạng thái <SlowIconKeywords:Trì trệ> khỏi tất cả Tay. Trả lời <Heal:[Heal:Arg1]> điểm Sinh lực. Đặt 1 lá <DerivativeCardKeywords_43:\"Món ăn kỳ diệu\"> vào tay. Gây [Poison:Arg2] lớp <IntoxicationIconKeywords:Ngộ độc> lên tất cả kẻ thù. Xáo trộn 1 lá <DerivativeCardKeywords_42:\"Món ăn kỳ diệu\"> vào rút bài từ bộ bài và rác bài mỗi loại."
  },
  Skill_4660_OverLimitUtlSkillDesc_3 = {
    Text = "Loại bỏ trạng thái <SlowIconKeywords:chậm chạp> của tất cả các lá bài trong tay. Khôi phục <Heal:[Heal:Arg1]> điểm sức sống. Đặt 1 lá <DerivativeCardKeywords_43:「món ăn kỳ diệu」> vào tay. Gây [Poison:Arg2] lớp <IntoxicationIconKeywords:trúng độc> cho tất cả kẻ địch. Xáo trộn 1 lá <DerivativeCardKeywords_43:「món ăn kỳ diệu」> vào cả bộ bài rút và rác bài mỗi bên 1 lá."
