  Skill_4661_Name = {
    Text = "ảo ảnh bi thảm màu mật ong"
  },
  Skill_4662_AwakerSkillBackgroundStory = {
    Text = "Người ta ca ngợi vẻ đẹp của nàng, ghen tị với thần thái quyến rũ thơm hương hồng của Sorel. Nhưng chẳng một ai để tâm đến nàng khi chỉ còn là một chiếc nụ e ấp.\nSố phận của nàng lúc ấy tựa như một nhành hoa mỏng manh lung lay trước cơn gió dại. Nàng chẳng thể quyết định được số phận của mình, để rồi trở thành một quân cờ bị cắt bỏ bởi người làm vườn.\nMãi đến khi bông hoa ấy bừng nở trước vương triều, người ta mới bàng hoàng nhận ra bản thân đã vướng vào vườn hồng gai góc và đẫm máu."
  },
  Skill_4662_BattleDesc_0 = {
    Text = "Ngẫu nhiên gây <Damage:[Damage:Arg1]> điểm thương [Arg3] lần. Cuối lượt, hồi phục <Heal:[Heal:Arg2]> điểm sức sống."
  },
  Skill_4662_BattleDesc_2 = {
    Text = "Ngẫu nhiên gây <Damage:[Damage:Arg1]> điểm thương [Arg3] lần, mỗi lần gây thương, tỷ lệ chí mạng tạm thời +5%. Cuối lượt, hồi <Heal:[Heal:Arg2]> điểm sức sống."
  },
  Skill_4662_Desc_0 = {
    Text = "Ngẫu nhiên gây <Damage:[Damage:Arg1]> điểm thương [Arg3] lần. Cuối lượt, hồi phục <Heal:[Heal:Arg2]> điểm sức sống."
