  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "Cỗ máy lạnh lẽo thay thế trái tim, dầu trong ống thủy lực thay thế máu. Cô ấy phải lạnh lẽo, lý trí, hành động theo lệnh. \n Nhưng, một ý chí ngoại lai âm thầm chuyển động trong thân xác của cô. Ngài không cần máu, không cần nhiệt độ, chỉ với bản thân mình đã có thể đốt cháy sự ác độc phi nhân. Ngài nói: Hãy quy phục, sinh vật hèn mọn và yếu đuối, rồi hủy diệt trong quả cầu điện nóng bỏng của ta."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Được [Power:Arg1] điểm tạm thời <PowerIconKeywords:lực lượng>. Được <Posse:[Arg2]> điểm năng lượng chìa khóa bạc. Xua tan trạng thái <WeaknessIconKeywords:yếu đuối> của mình. Mỗi khi có 1 lá bài đi vào <DimensionalSpaceIconKeywords:không gian siêu việt>, biến hình thành <DerivativeCardKeywords_14:「trang bị cơ giới - liễm」>."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng> tạm thời. Nhận <Posse:[Arg2]> điểm năng lượng bạc. Xóa bỏ <WeaknessIconKeywords:trạng thái yếu đuối> của bản thân. Đặt 1 lá 「Đánh」 Erika với thuộc tính <DepleteIconKeywords:tiêu thụ> vào bộ bài tay. Mỗi khi có 1 lá bài vào <DimensionalSpaceIconKeywords:không gian siêu việt>, chuyển hóa thành <DerivativeCardKeywords_14:「Vũ trang cơ giới - Liễm」>."
  },
  Skill_4663_Desc_0 = {
    Text = "Được [Power:Arg1] điểm <PowerIconKeywords:lực lượng> tạm thời. Nhận năng lượng chìa khóa bạc tương đương với sạc chìa khóa bạc của Erika. Tán xạ trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Mỗi khi có 1 lá bài vào <DimensionalSpaceIconKeywords:siêu việt không gian>, biến hình thành <DerivativeCardKeywords_14:「trang bị cơ giới - liễm」>."
  },
  Skill_4663_Desc_1 = {
    Text = "Được [Power:Arg1] điểm <PowerIconKeywords:lực lượng> tạm thời. Nhận năng lượng chìa khóa bạc tương đương với mức sạc của Erika. Loại bỏ trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Đặt 1 lá 「đánh」 có <DepleteIconKeywords:tiêu thụ> từ Erika vào tay. Mỗi khi có 1 lá bài vào <DimensionalSpaceIconKeywords:siêu việt>, biến hình thành <DerivativeCardKeywords_14:「Vũ trang cơ giới - Liễm」>."
  },
