  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "Bệnh dịch vô hình lặng lẽ, mang đến nỗi đau và điên cuồng vô tận. \n\n Giám mục không thể ngủ được, đau lòng vì không thể mang đi khổ nạn của mọi người. \n\n \"Đấng tạo hóa nhân từ ơi, xin cứu giúp họ, con nguyện thay họ gánh chịu mọi đau đớn và sầu buồn.\"\n\n Vì vậy, Cha Trời ban \"phước lành\" cho ông, để ông khắc lời thần trên bảng đá, thực hiện việc xóa bỏ khổ đau và tai nạn."
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>: Đặt 1 lá <B02AFKeyWord:bảo vệ bằng tình yêu thương> vào tay. Cuối lượt, nhận được [Power:Arg2] điểm <PowerIconKeywords:lực lượng>."
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Đặt 1 lá <B02AFKeyWord:Hộ Dĩ Nhân Ái> vào tay. Sau khi kết thúc lượt, nhận được [Power:Arg2] điểm <PowerIconKeywords:Sức Mạnh>.\"Sự Che Chở Của Tạo Chủ\" và\"Huyết Cốt Thụ Phúc\" tích lũy Lò Đỏ Thẫm tăng 25%,\"Khổ Nạn Cần Tiêu\" khi chọn \"Siêu Độ\" mỗi 1% sinh mệnh tối đa Lò Đỏ Thẫm tiêu hao sẽ tăng hiệu quả sát thương cuối cùng từ 2% lên 5%."
