  },
  Skill_4667_AwakerSkillBackgroundStory = {
    Text = "Đó là mê cung vĩ đại vượt qua mọi chiều không gian.\nNgười lữ hành lạc vào mê cung buộc phải đối mặt với một giao dịch bất lịch sự.\nNếu trả lời \"không\", người lữ hành sẽ mãi mãi bị kẹt trong mê cung.\nNếu trả lời \"đồng ý\", người lữ hành sẽ bị cấy ghép con cháu báng bổ và bị xóa sạch mọi ký ức.\nBạn hỏi giao dịch là gì?\nChẳng ai biết chi tiết của giao dịch, kể cả chủ nhân nhợt nhạt của mê cung.\nĐơn giản, giao dịch chỉ là giao dịch."
  },
  Skill_4667_Desc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Nhận được [Power:Arg1] điểm <PowerIconKeywords:lực lượng> và [Arg4] điểm <AlertIconKeywords:Báo động>.] Nhận được <Block:[Block:Arg2]> điểm lá chắn. Gây [Poison:Arg3] lớp <IntoxicationIconKeywords:trúng độc> cho tất cả kẻ địch."
  },
