  Skill_4680_AwakerSkillBackgroundStory = {
    Text = "Gió núi thì thầm trong những bộ xương của mê cung, tiếng than khóc vang vọng. \n Cô ấy lắng nghe tiếng kêu than của những lữ khách lạc đường từ xa, lại ngáp lần thứ tám nghìn không trăm một. \n Cô ấy nuốt nỗi đau, rồi phân loại, trưng bày chúng từng thứ một. \n Chỉ có một câu hỏi - không ai biết đến kiệt tác của cô, cô là khán giả duy nhất ở đây. \n Ôi——! \n Cô ấy ngồi ở nơi sâu nhất của mê cung, lại ngáp thêm một lần nữa."
  },
  Skill_4680_Desc_0 = {
    Text = "Agrippa nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>: Hiệu ứng <IntoxicationIconKeywords:trúng độc> từ Agrippa tăng 50%, sau khi kết thúc lượt, nhận được <Block:[Block:Arg2]> điểm lá chắn."
  },
  Skill_4680_Desc_15 = {
    Text = "Agrippa nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: <IntoxicationIconKeywords:Trúng Độc> do Agrippa gây ra tăng 100%, sau khi kết thúc lượt, nhận được <Block:[Block:Arg2]> điểm Khiên, mỗi lượt mỗi lần Agrippa gây ra hoặc kích hoạt 1 lần trúng độc, khiên đó tăng 50%, tối đa 5 tầng."
