  Skill_4694_AwakerSkillBackgroundStory = {
    Text = "Trong nhà tù Cửa Mới tối tăm, dầu sáp có ở khắp nơi cũng là một vật quý giá. \n Đã quý giá thì phải dùng ở những nơi quan trọng, chẳng hạn như vào lúc kỷ luật, dùng trên làn da của những đứa trẻ không ngoan. \n Không phải là dầu sáp đặc chế, khi nhỏ xuống kèm theo tiếng than khóc thảm thiết, nhưng trong tai của cô gái, lại giống như những vần thơ thanh tao."
  },
  Skill_4694_BattleDesc_0 = {
    Text = "Nhận được [Counterattack:Arg2] tầng <RetaliateIconKeywords:Phản công>. Tạm thời giảm [Exhaustion:Arg1] điểm <ExhaustionIconKeywords:Sức mạnh> của tất cả kẻ địch, mỗi kẻ địch nhận được [Power:Arg1] điểm <PowerIconKeywords:Sức mạnh tạm thời>. Xóa trạng thái <RetaliateIconKeywords:Phản công> của tất cả kẻ địch."
  },
  Skill_4694_BattleDesc_2 = {
    Text = "Nhận được [Counterattack:Arg2] tầng <RetaliateIconKeywords:Phản công>. Tạm thời giảm [Exhaustion:Arg1] điểm <ExhaustionIconKeywords:Sức mạnh> của tất cả kẻ địch, mỗi kẻ địch nhận được [Power:Arg1] điểm <PowerIconKeywords:Sức mạnh tạm thời>. Xóa trạng thái <RetaliateIconKeywords:Phản công> của tất cả kẻ địch. Nhận <Energy:[Energy:Arg3]> điểm aliemus."
  },
  Skill_4694_Desc_0 = {
    Text = "Nhận [Counterattack:Arg2] lớp <RetaliateIconKeywords:phản công>. <TouquKeywords:Trộm cắp> [Arg1] điểm <PowerIconKeywords:lực lượng> từ tất cả kẻ địch và loại bỏ trạng thái <RetaliateIconKeywords:phản công> của chúng."
