  },
  Skill_4698_Name = {
    Text = "cầu nguyện"
  },
  Skill_4701_AwakerSkillBackgroundStory = {
    Text = "Đó là phôi thai bị biến dạng, là hạt giống tội ác. \n là nhịp tim kích động, là mạch đập cuồn cuộn, là sự thù hận giữa xương máu, số phận quấn chặt. \n Sáng tạo không có quyền lựa chọn, cô ấy chỉ có thể để cho sự mang thai sai lệch phát triển."
  },
  Skill_4701_Desc_0 = {
    Text = "Muphí nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: nhận 1 xúc tu, sau khi Muphí chơi thẻ bài, nhận 1 xúc tu tạm thời không bị giới hạn số lượng xúc tu, và được sạc năng lượng chìa khóa bạc tương đương với 1 điểm tính toán, mỗi lượt tối đa kích hoạt 3 lần."
  },
  Skill_4701_Desc_15 = {
    Text = "Murphy nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Nhận 1 xúc thủ, sau khi Murphy đánh ra lá bài, nhận 1 xúc thủ tạm thời bỏ qua giới hạn xúc thủ, và nạp Ngân Thược bằng 1 lượng tiêu hao Toán Lực, mỗi lượt tối đa kích hoạt 3 lần. Lần đầu tiên mỗi lượt Murphy đánh ra \"Loa Yên Nghịch Lưu\" số lần sát thương và\"Thánh Nữ Tác Thành\" nhận toán lực nhân đôi."
  },
