  },
  Skill_4729_AwakerSkillBackgroundStory = {
    Text = "\"Đúng vậy, ta đã từng hứa hẹn như vậy với nàng.\"\nKhi đề cập đến ngày đất nước cũ sụp đổ, vẻ mặt của vị vua trẻ càng thêm mệt mỏi. \n \"Ta chỉ mong những lời đó có thể an ủi nỗi sợ hãi của nàng trước khi chết, không ngờ nàng lại xem như kim chỉ nam...\""
  },
  Skill_4729_Desc_0 = {
    Text = "Giải tán trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Nhận được [TentaclePower:Arg1] điểm tạm thời <TentacleInjurieIconKeywords:thương tổn xúc tu> và [Power:Arg1] điểm tạm thời <PowerIconKeywords:lực lượng>. Nếu tư thế hiện tại là\"Biển Lặng\", sẽ làm giảm thêm [Exhaustion:Arg3] điểm <ExhaustionIconKeywords:lực lượng> của tất cả kẻ địch trong lượt này. <RippleKeywords:Dư ba>: Điều khiển 1 xúc tu tấn công kẻ thù."
  },
  Skill_4729_Desc_3 = {
    Text = "Giải tán trạng thái <WeaknessIconKeywords:yếu đuối> của bản thân. Nhận được [TentaclePower:Arg1] điểm tạm thời <TentacleInjurieIconKeywords:thương tổn xúc tu> và [Power:Arg1] điểm tạm thời <PowerIconKeywords:lực lượng>. Nhận được [Arg2]% tỷ lệ chí mạng tạm thời. Nếu tư thế hiện tại là\"Biển Lặng\", tất cả kẻ địch trong lượt này sẽ giảm [Exhaustion:Arg3] điểm <ExhaustionIconKeywords:lực lượng>. <RippleKeywords:Dư ba>: Điều khiển 1 xúc tu tấn công kẻ thù."
  },
