  Skill_47455_Desc_1 = {
    Text = "Khiến một mục tiêu nhận được <StrengthenKeywords:bao cát>."
  },
  Skill_47455_Name_1 = {Text = "bao cát"},
  Skill_4745_AwakerSkillBackgroundStory = {
    Text = "Hai ý chí không ngừng đối kháng và giằng co trong thân thể máy móc: một mong muốn hủy diệt, một không chịu khuất phục. Nhưng con người nhỏ bé không thể giành chiến thắng lâu dài, cô ấy cuối cùng sẽ bị đối phương nhấn chìm, trở thành một chiếc bình điên cuồng chỉ tồn tại để phá hủy. \n Thế là cô ấy giải phóng toàn bộ dòng điện. Những cung điện lớn bao trùm lấy cơ thể cô, tiếng nổ điện vang lên từ thân thể bị đoản mạch của cô ấy, cô ném ra năng lượng đã tích lũy, rồi ngay lập tức mất khả năng hành động. \n \"Không thể động đậy, thì không thể hủy diệt.\""
  },
  Skill_4745_Desc_0 = {
    Text = "Erika nhận được [Arg4]% tỷ lệ chí mạng tạm thời và sát thương chí mạng. Nhận được <Block:[Block:Arg2]> điểm lá chắn. Gây <Damage:[Damage:Arg1]> sát thương cho tất cả kẻ địch và áp dụng [Arg3] lớp <WeaknessIconKeywords:suy nhược> và <VulnerabilityIconKeywords:dễ bị thương>."
  },
  Skill_4745_Desc_2 = {
    Text = "Erika nhận được [Arg4]% tỷ lệ chí mạng tạm thời và sát thương chí mạng. Nhận <Block:[Block:Arg2]> điểm lá chắn. Gây <Damage:[Damage:Arg1]> thương cho tất cả kẻ địch và áp dụng [Arg3] lớp <WeaknessIconKeywords:Suy nhược> và <VulnerabilityIconKeywords:Trọng thương>. Kỹ năng này được hưởng thêm [Arg7] lần <PowerIconKeywords:lực lượng> và <AlertIconKeywords:Báo động> tăng cường."
  },
