  },
  Skill_4745_OverLimitUtlSkillDesc_0 = {
    Text = "Erika nhận [Arg4]% Tỷ lệ chí mạng tạm thời và Sát thương chí mạng. Nhận <Block:[Block:Arg6]> điểm lá chắn. Gây <Damage:[Damage:Arg5]> thương cho tất cả kẻ địch và gây [Arg3] lớp <WeaknessIconKeywords:Suy nhược> và <VulnerabilityIconKeywords:Trọng thương>. \"Đánh cơ bản\" của Erika gây thêm 1 lần thương, \"Phòng thủ cơ bản\" nhận thêm 1 lần lá chắn, kéo dài 3 lượt."
  },
  Skill_4745_OverLimitUtlSkillDesc_2 = {
    Text = "Erika nhận được [Arg4]% tỷ lệ chí mạng tạm thời và sát thương chí mạng. Nhận <Block:[Block:Arg6]> điểm lá chắn. Gây <Damage:[Damage:Arg5]> thương cho tất cả kẻ địch và áp dụng [Arg3] lớp <WeaknessIconKeywords:suy yếu> và <VulnerabilityIconKeywords:dễ tổn thương>. Kỹ năng này được hưởng thêm [Arg7] lần <PowerIconKeywords:lực lượng> và <AlertIconKeywords:báo động>. Đòn đánh cơ bản của Erika gây thêm 1 lần thương, phòng thủ cơ bản nhận thêm 1 lớp lá chắn, kéo dài 3 lượt."
  },
