  },
  Skill_4745_tempOverLimitUtlSkillDesc_3 = {
    Text = "Erica nhận được [Arg4]% tỷ lệ bạo kích và sát thương bạo kích tạm thời. Nhận được <Block:[Block:Arg6]> điểm hộ thuẫn. Gây <Damage:[Damage:Arg5]> sát thương lên tất cả kẻ địch và áp dụng [Arg3] tầng <WeaknessIconKeywords:Hư Nhược> và <VulnerabilityIconKeywords:Dễ Thương>. Kỹ năng này được hưởng thêm [Arg7] lần gia thành <PowerIconKeywords:Lực Lượng> và <AlertIconKeywords:Giới Bị>, các lần thi triển sau đó được hưởng thêm 1 lần gia thành Lực Lượng và Giới Bị.\"Đả Kích Cơ Bản\" của Erica gây thêm 1 lần sát thương,\"Phòng Thủ Cơ Bản\" nhận thêm 1 lần hộ thuẫn, kéo dài 3 lượt."
  },
  Skill_4746_Desc = {
    Text = "Giảm [Arg2] điểm lực lượng tạm thời của tất cả kẻ địch, đặt một thẻ <DerivativeCardKeywords_28:triệu chứng:「suy sụp」> vào bộ bài tay. \"Đau lắm à? Thật đáng thương… Hãy khóc đi!\""
  },
  Skill_4746_Name = {
    Text = "khóc và la hét!!"
  },
  Skill_4747_Desc = {
    Text = "Cuộc chiến dài hạn của bạn đã thu hút sự chú ý của thâm cảnh... gây ra <Damage:[Damage:Arg1]> điểm thương [AttackTimes:Arg2] lần. Nhận trạng thái \"phẫn nộ\", lực lượng của địch sẽ tiếp tục tăng lên!"
  },
  Skill_4747_Name = {
    Text = "Xâm phạm"
  },
  Skill_47484_Desc = {
    Text = "Thu về 2 điểm sức tính toán, rút 2 lá bài."
  },
  Skill_47484_Name = {
    Text = "Cảm hứng nâng cao"
  },
  Skill_4748_AwakerSkillBackgroundStory = {
    Text = "Trẻ em sẽ từ từ nhìn thấu bản chất của những câu chuyện cổ tích, hiểu được những ẩn dụ đằng sau huyền thoại. Trong ngôn ngữ của con người, quá trình này được gọi là \"trưởng thành\". \nNhưng cũng có những đứa trẻ càng tin vào những câu chuyện trước khi đi ngủ, chúng kiên trì cho rằng trên trời thật sự có cầu vồng, thật sự có những nền văn minh chìm sâu dưới biển sâu. \nÔ Ryta thích những câu chuyện này, cô ấy muốn chia sẻ niềm vui này với nhiều người bạn hơn."
  },
  Skill_4748_Desc_0 = {
    Text = "<TentacleInjurieIconKeywords:Thiệt hại xúc tu> +[TentaclePower:Arg1]. Bỏ hết bài trên tay, rút số lượng bài tương đương. Trộn 1 lá bài \"Tuyến thể phân bào\" vào chồng bài bỏ."
  },
  Skill_4748_Desc_1 = {
    Text = "<TentacleInjurieIconKeywords:Thiệt hại xúc tu> +[TentaclePower:Arg1]. Bỏ hết bài trên tay, rút số lượng bài tương đương +1. Trộn 1 lá bài \"Tuyến thể phân bào\" vào chồng bài bỏ."
  },
  Skill_4748_EffectNameList = {
    Text = "Thương tổn xúc tu, \"chia tách tuyến\" cấp độ"
  },
  Skill_4748_Name = {
    Text = "Lực của đồng đội"
  },
  Skill_4748_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1,$GrowValue2"
  },
  Skill_4749_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương [AttackTimes:Arg2] lần."
  },
  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "Mang thai đi, ra đời đi, sinh sản đi. \n Trong thực tại đang dần hòa tan, trong thế giới u ám, trong hư không sắp sửa sinh mới. \n Sự tồn tại của các ngươi, là quả của sự hy sinh của mẹ, là nguyên nhân cho sự tồn tại của mẹ. \n Con của sự thánh thiện ơi, hãy tái sinh trong thế giới mới —— hãy tái sinh trong thế giới vô nhiễm, đã xóa bỏ mọi nỗi sợ hãi."
  },
  Skill_4750_Desc_0 = {
    Text = "Thái Di Sơ nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Ngay lập tức nhận 1 lá <DerivativeCardKeywords_10:Con của sự thánh thiện>. Mỗi khi phát động mật lệnh, sẽ chuyển đổi một phôi thai trong tay thành <DerivativeCardKeywords_10:Con của sự thánh thiện>."
  },
  Skill_4750_Desc_15 = {
