  Skill_4769_AwakerSkillBackgroundStory = {
    Text = "Thành phố của cô ấy là một phế tích không ngừng lan rộng. \n ước mơ đã hoàn toàn biến mất tại đây, nhưng phế tích không hề hay biết. Nó chỉ đơn giản là tiếp tục mở rộng mà thôi. \n thế giới đã lâu quên mất nó."
  },
  Skill_4769_Desc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm lá chắn và [Counterattack:Arg2] lớp <RetaliateIconKeywords:phản công>, hiệu ứng nhảy vọt tiếp theo trong lượt này sẽ chắc chắn được kích hoạt. Có thể lựa chọn tiêu thụ số lớp <DreamGuide:Dẫn mộng> để kích hoạt <JingjinvwangKeywords1:Phản công trong giấc ngủ sâu> hoặc <JingjinvwangKeywords2:Tiếng thì thầm vang lại>, nếu số lớp <DreamGuide:Dẫn mộng> không đủ 5 lớp, thì nhận 1 lớp <DreamGuide:Dẫn mộng>."
