  Skill_4769_tempOverLimitUtlSkillDesc_2 = {
    Text = "Nhận được <Block:[Block:Arg1]> điểm lá chắn và [Counterattack:Arg2] tầng <RetaliateIconKeywords:phản công>, trong lượt này lần nhảy vọt tiếp theo chắc chắn sẽ kích hoạt hiệu ứng. Không cần tiêu thụ mộng dẫn, đồng thời kích hoạt \"<JingjinvwangKeywords3:thúc miên mạch>\", \"<JingjinvwangKeywords1:sâu miên phản kích>\" và \"<JingjinvwangKeywords2:nói mơ hồi âm>\"."
  },
  Skill_4769_tempOverLimitUtlSkillDesc_3 = {
    Text = "Nhận được <Block:[Block:Arg1]> điểm khiên và [Counterattack:Arg2] tầng <RetaliateIconKeywords:Phản Kích>, hiệu ứng Dịch Chuyển tiếp theo trong lượt này chắc chắn phát động. Không cần tiêu hao Mộng Dẫn, đồng thời kích hoạt \"<JingjinvwangKeywords3:Thôi Miên Mạch Lạc>\",\"<JingjinvwangKeywords1:Thâm Miên Phản Kích>\" và\"<JingjinvwangKeywords2:Ảo Ngữ Hồi Âm>\". 2 lá bài chỉ lệnh tiếp theo mà Wanda đánh ra sẽ phát huy hiệu quả thêm 1 lần."
  },
  Skill_4770_AwakerSkillBackgroundStory = {
    Text = "Tại buổi tụ họp của Sorel, một vũ điệu xoay vòng trước khi tan tiệc là điều không thể thiếu.\nDưới sự mời gọi của rượu và hormone, dù là hoàng tử láng giềng, trọng thần triều đình hay nữ hầu cận, tất cả rồi sẽ cùng nắm tay bước vào vòng nhảy và tận hưởng cuồng nhiệt.\nCho đến khi tiếng đàn dần nhỏ lại, bóng người dần rời đi khỏi bàn tiệc, không một thứ gì có thể đứng ở bên Sorel, trừ quyền lực tuyệt đối và ánh bình minh le lói qua khung cửa sổ dát vàng."
  },
  Skill_4770_Desc_0 = {
