  Skill_4784_OverLimitUtlSkillDesc_0 = {
    Text = "Xua tan trạng thái <FragileIconKeywords:Mong manh> của bản thân và nhận <Block:[Block:Arg1]> điểm lá chắn. Nhận [Counterattack:Arg3] lớp <RetaliateIconKeywords:phản công>. Chọn 1 Thể thức tỉnh khác để nhận <Energy:[Energy:Arg2]> điểm Điên loạn. Khiến Thể thức tỉnh được chọn nhận <Energy:[Energy:Arg4]> điểm Điên loạn khi bắt đầu lượt, kéo dài 3 lượt."
  },
  Skill_4784_OverLimitUtlSkillDesc_3 = {
    Text = "Giải trừ trạng thái <FragileIconKeywords:yếu đuối> của bản thân và nhận được <Block:[Block:Arg1]> điểm lá chắn. Nhận [Counterattack:Arg3] lớp <RetaliateIconKeywords:phản công>. Chọn 1 thân thể thức tỉnh khác nhận <Energy:[Energy:Arg2]> điểm điên cuồng và khiến thân thể đó phải bùng nổ 2 lần cơn thịnh nộ trong lượt này mới vào thời gian hồi chiêu. Khi bắt đầu lượt, thân thể được chọn nhận <Energy:[Energy:Arg4]> điểm điên cuồng, duy trì 3 lượt."
