  Skill_4788_Name = {
    Text = "Cuộc đấu tranh hấp hối"
  },
  Skill_4789_AwakerSkillBackgroundStory = {
    Text = "Không ai có thể giải thích tại sao con gấu bông được gắn bạc tâm hình giọt nước mắt lại trở thành hình dạng này sau khi Ai Jī Sī được Hoán tỉnh. Điều này có thể liên quan đến lực lượng của bậc trên mà Ai Jī Sī sở hữu, hoặc đơn giản chỉ là biến dạng do bị ảnh hưởng bởi sức mạnh tinh thần mạnh mẽ. \n\n Dù sao đi nữa, nó dường như có một phần ý thức riêng, thỉnh thoảng sẽ tách ra một phần khi Ai Jī Sī không chú ý, biến thành một bông hoa pháo bằng sợi chỉ."
