  Skill_4800_AwakerSkillBackgroundStory = {
    Text = "Lắc tin rằng chiến thắng của mình đến từ sự ưu ái của nữ thần may mắn.\nGiống như những kẻ đánh bạc cuối cùng đều trắng tay, anh ta cũng tin rằng nữ thần may mắn sẽ không ngoảnh mặt đi."
  },
  Skill_4800_Desc_0 = {
    Text = "Lắc nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>: Nhận [Power:Arg2] điểm <PowerIconKeywords:lực lượng>. Trong trận chiến này, nhận một <C05_zaowu:「hỗn loạn di sản」> sáng tạo đã chọn, hoặc nâng cấp một <C05_zaowu:「hỗn loạn di sản」> đã sở hữu."
  },
  Skill_4800_Desc_15 = {
    Text = "Lake nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Nhận được [Power:Arg2] điểm <PowerIconKeywords:Sức Mạnh>. Trong trận chiến này, nhận được một tạo vật <C05_zaowu:「Di Tặng Hỗn Độn」> đã chọn, hoặc nâng cấp một <C05_zaowu:「Di Tặng Hỗn Độn」> đang sở hữu, hiệu ứng này thực hiện liên tiếp 2 lần. Tất cả xúc xắc sáu mặt của Lake được nâng cấp thành xúc xắc tám mặt."
  },
