  Skill_4804_AwakerSkillBackgroundStory = {
    Text = "Ngọn lửa lây lan, biến bầu trời của nhà hát thành màu xanh ngọc bích, như mặt hồ trong trẻo yên tĩnh vào buổi sáng. \n Bao nhiêu người từng đến đây để theo đuổi hình bóng màu xanh ngọc này, lại có bao nhiêu người bỏ qua những động tác múa trôi chảy và đầy sức mạnh, chỉ nhìn thấy cánh tay màu ngọc bích mờ ảo và khung cảnh dưới chiếc váy tưởng tượng. \n Còn vũ công chỉ đứng đó như đang đông cứng, với dáng vẻ sắp chết bị Lửa Xanh nuốt chửng."
  },
  Skill_4804_Desc_0 = {
    Text = "Liz nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>:Mỗi khi Liz gây ra [Arg2] lần thương, cô sẽ đưa 1 lá bài có <DepleteIconKeywords:tiêu thụ> là <DerivativeCardKeywords_18:「Lửa Xanh」> vào bộ bài trong tay, tối đa 3 lần mỗi lượt."
  },
  Skill_4804_Desc_15 = {
    Text = "Liz nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Mỗi khi Liz gây [Arg2] lần sát thương, đặt 1 lá <DerivativeCardKeywords_18:「Lục Viêm」> có <DepleteIconKeywords:Tiêu Hao> vào bài trên tay, mỗi lượt tối đa kích hoạt 3 lần. Mỗi khi Liz gây 3 lần sát thương còn tăng sát thương mà Liz gây ra trong trận chiến này thêm [Arg3] điểm."
  },
