  Skill_4820_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [AttackTimes:Arg2] lần!!"
  },
  Skill_4821_AwakerSkillBackgroundStory = {
    Text = "Mê cung của cô ấy dẫn đến mọi ngóc ngách của thế giới. \n Trong rừng rậm, dưới lòng thư viện, và sâu dưới đáy biển đều có lối vào. \n Nhờ vào những kẻ xui xẻo lạc vào mê cung, cô ấy mới miễn cưỡng phác họa ra hình dáng của thế giới. \n Những người lữ hành lạc lối trong những lối đi xoắn ốc không ngừng, còn cô ấy lạc lối trong những câu chuyện biến đổi không ngừng. \n Cô ấy biết mọi thứ, nhưng không thể rời khỏi mê cung nửa bước."
  },
  Skill_4821_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương và lượng <IntoxicationIconKeywords:trúng độc> tương đương. Mỗi khi kích hoạt tiêu thụ, sẽ đặt \"Bàn Xoay Nhợt Nhạt\" từ rác bài vào tay."
  },
  Skill_4821_Desc_3 = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương và lượng <IntoxicationIconKeywords:trúng độc> tương đương. <EmbryoFusionIconKeywords:Phôi hợp tử> +[Blood:Arg2]. Mỗi khi kích hoạt tiêu thụ, sẽ đặt \"Vòng Xoáy Nhạt\" từ rác bài vào tay."
  },
  Skill_4821_EffectNameList_0 = {Text = "thương"},
