  Skill_4821_Name = {
    Text = "Luồng xoáy nhợt nhạt"
  },
  Skill_4821_PropertyNameList_0 = {
    Text = "Sức tấn công*GrowValue1,"
  },
  Skill_4821_PropertyNameList_3 = {
    Text = "Sức tấn công*GrowValue1"
  },
  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "Trong cuộc lang thang vô tận, tinkerer đã quên tên quê hương của mình. \nQua thời gian dài đằng đẵng, vũ trụ đã quên tên của hành tinh chết đó. \nNó giống như hàng triệu hành tinh khác bị rỗng rỗng và bị bỏ rơi, được gọi chung là \"hoang tinh\". \nGiọng hát của cô có thể là tiếng vọng cuối cùng của hành tinh ngoài giới hạn đó."
  },
  Skill_4822_Desc_0 = {
    Text = "Tinkerer nhận được <Energy:[Energy:Arg1]> điểm điên cuồng, <ExaltIconKeywords:Thức tỉnh linh tri>: tăng sát thương cơ bản của đòn \"đánh\" của Tinkerer lên [Arg2]%. Tất cả các lá bài của Tinkerer nhận được 1 hiệu ứng ngẫu nhiên. Hiệu ứng này sẽ bị loại bỏ khi trận chiến kết thúc."
  },
  Skill_4822_Desc_15 = {
    Text = "Tinkter nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí, <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Tăng sát thương cơ bản của \"Đánh\" của Tinkter thêm [Arg2]%, tất cả lá bài của Tinkter nhận 1 hiệu ứng ngẫu nhiên, hiệu ứng này sẽ bị xóa khi kết thúc trận đấu. Mỗi lượt khi Tinkter đánh ra \"Kỹ năng\" lần đầu sẽ tạo 1 lá\"Đánh\" tạm thời có tiêu hao Toán Lực bằng 0, hiệu ứng ngẫu nhiên của lá\"Đánh\"đó tăng gấp 2 lần."
