  Skill_4824_AwakerSkillBackgroundStory = {
    Text = "Liz vẫn còn nhớ cảnh tượng khi cô nhận được ngọn lửa lục ấy. \nNgọn lửa lục nhảy múa và bùng lên trong lòng bàn tay, thúc giục cô thực hiện ước muốn đã bị dồn nén lâu nay."
  },
  Skill_4824_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg2]> điểm<PunctureDamagewords:Sát thương xuyên thấu> cho kẻ thù ngẫu nhiên [Arg1] lần, gây [Arg3]% thương<IntoxicationIconKeywords:Ngộ độc>. Khi điểm tính toán không đủ có thể chơi mạnh, hiệu ứng sẽ chuyển thành nhận <Energy:[Energy:Arg4]> điểm điên cuồng và tiêu thụ."
  },
  Skill_4824_Desc_1 = {
    Text = "Gây <Damage:[Damage:Arg2]> điểm <PunctureDamagewords:thương tổn xuyên> [Arg1] lần, áp dụng [Arg3]% thương của <IntoxicationIconKeywords:trúng độc>. Khi kết thúc lượt, nếu ở trong bài hoặc <DimensionalSpaceIconKeywords:không gian siêu việt>, nâng cấp thành \"<DerivativeCardKeywords_20:Lửa Xanh Tử Diệt>\". Khi sức tính toán không đủ, có thể đánh cược mạnh mẽ, hiệu ứng thay đổi thành nhận <Energy:[Energy:Arg4]> điểm điên cuồng và tiêu thụ."
  },
