  Skill_4825_AwakerSkillBackgroundStory = {
    Text = "Dòng nước màu xám, dính đặc, không cần phải di chuyển nhưng lại giống như có sức sống. \n Chỉ cần bị dính vào, chắc chắn sẽ bị xâm nhiễm đến tận tủy xương... \n Người nhìn thấy vật này, ai cũng sẽ có cảm giác như vậy."
  },
  Skill_4825_Desc_0 = {
    Text = "Nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng> và <VulnerabilityIconKeywords:Trọng thương> tất cả kẻ địch. <TransitionIconKeywords:Bước nhảy>: Thay đổi thành: Nhận [Power:Arg2] điểm tạm thời <PowerIconKeywords:lực lượng> và <VulnerabilityIconKeywords:Trọng thương> tất cả kẻ địch."
