  Skill_4842_AwakerSkillBackgroundStory = {
    Text = "Người phụ nữ phép thuật vượt qua chiều không gian, am hiểu quy luật phản xạ trong chiều. \n Cô ấy rõ ràng từng con đường trong chiều, từng điểm kết nối. \n Đường dẫn vô tận, đều ở trong tâm trí của cô. \n Một khi như vậy, vật chất từ các chiều khác được phản xạ, đối với cô ấy tự nhiên là vật trong túi."
  },
  Skill_4842_Desc_0 = {
    Text = "Đào Đen Đá nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>:Mỗi khi có 1 lá bài của Đào Đen Đá vào <DimensionalSpaceIconKeywords:siêu việt không gian>,sẽ đặt 1 lá <DerivativeCardKeywords_4:「cảm hứng」> vào tay, mỗi lượt tối đa kích hoạt 2 lần."
  },
  Skill_4842_Desc_15 = {
    Text = "Daphodel nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Mỗi khi 1 lá bài của Daphodel đi vào <DimensionalSpaceIconKeywords:Siêu Chiều Không Gian>, đặt 1 lá <DerivativeCardKeywords_4:「Linh Cảm」> vào tay, mỗi lượt tối đa kích hoạt 2 lần. Tạo 1 lá「Đoạn Cảnh Nhất Kích」tạm thời có tiêu hao Toán Lực bằng 0 và đặt vào Siêu Chiều Không Gian."
  },
