  Skill_4843_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> thương [AttackTimes:Arg2] lần, thêm 1 lá <DerivativeCardKeywords_31:「dung dịch ăn mòn」> vào rút bài từ bộ bài."
  },
  Skill_4844_AwakerSkillBackgroundStory = {
    Text = "Đợi tôi được triệu chọn, đợi tôi lặn sâu vào Hải Vực, đợi tôi trở về với tộc. \n Tôi sẽ hưởng thụ an lạc vĩnh cửu, các ngươi những kẻ bình thường ngu dốt, đừng mong có thể bắt nạt tôi nữa. \n Với những ước mơ như vậy, trai trẻ nhỏ bé chìm vào giấc mơ tưởng tượng."
  },
  Skill_4844_Desc_0 = {
    Text = "Nhận được <Block:[Block:Arg1]> điểm lá chắn. Cho đến đầu vòng tiếp theo, <RetaliateIconKeywords:phản công> và râu chạm phản công sẽ kích hoạt thêm [Arg2] lần, gây ra 50% thương. Nhận được [Power:Arg3] điểm <PowerIconKeywords:lực lượng>."
