  Skill_4848_AwakerSkillBackgroundStory = {
    Text = "Hãy để những người Sparta trả giá cho những gì họ đã làm. \n Những gì bạn ban tặng không phải là lòng thương hại, những gì bạn tước đoạt không phải là ân huệ. \n Đó là cuộc đời của một cô gái mang trong mình những ước mơ, đó là những giọt máu nóng hổi chảy ra từ vô số người Hiro. \n Kẻ báo thù chỉ mất đi xiềng xích."
  },
  Skill_4848_Desc_0 = {
    Text = "Hiro nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>:Các thẻ bài của Hiro nhận được <RetainIconKeywords:bảo lưu>, cuối lượt, tăng 10% sát thương của \"Đòn phá chuỗi\" và\"Oán hận dai dẳng\"."
