    Text = "Khi anh ta giơ cao cây kiếm lớn, chắc chắn sẽ là máu và cái chết."
  },
  Skill_57338_Desc_0 = {
    Text = "Đặt 3 lá <DerivativeCardKeywords_17:\"Sức mạnh của Lưỡi đao khổng lồ\"> có Sát thương cơ bản tăng 400%, Giá trị Điểm tính toán bằng 0 vào Tay, nhận <PowerIconKeywords:Sức mạnh> tạm thời tương đương [Arg1]% thương tổn xúc tu."
