  },
  Skill_57339_Desc_0 = {
    Text = "Đặt 2 lá \"cắt đầu trọng thương\" vào Tay, và khiến chúng nhận <DepleteIconKeywords:Tiêu hao>, <PrepareKeypvewords:Chuẩn bị 1> và <RetainIconKeywords:Giữ lại>. Tăng Sát thương cơ bản của \"Sức mạnh của Lưỡi đao khổng lồ\" và \"cắt đầu trọng thương\" lên 25% trong trận chiến này."
  },
  Skill_57339_Desc_3 = {
    Text = "Đặt 2 lá \"cắt đầu trọng thương\" vào bộ bài và khiến chúng có được <DepleteIconKeywords:tiêu thụ>, <PrepareKeypvewords:chuẩn bị 1> và <RetainIconKeywords:giữ lại>. Khiến \"Sức mạnh của Lưỡi đao khổng lồ\" và \"cắt đầu trọng thương\" có thương cơ bản tăng 25% trong trận chiến này. Goliath nhận được <Energy:[Energy:Arg2]> điểm điên cuồng."
  },
  Skill_57339_Name = {Text = "ẩn náu"},
