    Text = "Trước khi nghe bản nhạc này, bạn chưa bao giờ thực sự có tai. Sau khi nghe bản nhạc này, bạn không thể tìm thấy âm thanh như vậy nữa. Vì vậy, hãy tập trung toàn bộ tinh thần, nín thở và ca ngợi bản nhạc hiếm có trong cuộc đời này nhé!"
  },
  Skill_59476_Desc_0 = {
    Text = "Hamlin nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Vào đầu lượt, đặt một lá\"<DerivativeCardKeywords_64:Giao hưởng của sự hòa hợp>\" vào tay.<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_Desc_15 = {
    Text = "Hamlin nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Khi bắt đầu lượt, đặt một lá\"<DerivativeCardKeywords_64:Hiệp Nhạc Giao Hưởng>\" vào tay. Khi bắt đầu lượt, mỗi lá chỉ lệnh sở hữu \"Nhạc Âm\", Hamlin nhận được <Energy:[Energy:Arg2]> điểm Cuồng Khí. Khi thi triển \"Nhạc Âm Nguyên Sơ\", cứ mỗi 2 lá chỉ lệnh sở hữu Nhạc Âm, số lần sát thương +1.<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_EffectNameList = {
    Text = "điên cuồng"
  },
  Skill_59476_Name = {
    Text = "Bản nhạc này xứng đáng được ca ngợi"
  },
  Skill_59477_AwakerSkillBackgroundStory = {
    Text = "Âm nhạc ra đời từ đâu? Từ lễ tế làm vui lòng các vị thần, từ tiếng gọi của người nông dân, từ tiếng gào thét của người nguyên thủy, từ tiếng chim hót vào mùa xuân, từ gió thông và sóng biển, từ sự rung chuyển của đất đai và sự sụp đổ của những đỉnh núi… Hay là từ trong hỗn mang của trời đất, tiếng thì thầm trong giấc mơ của các vị thần."
  },
  Skill_59477_BattleDesc_0 = {
    Text = "Gây ngẫu nhiên [Arg3] lần <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:Sát thương xuyên thấu>, mỗi lần gây thương tạm thời giảm [Exhaustion:Arg2] điểm <ExhaustionIconKeywords:lực lượng> của mục tiêu và nhận [Power:Arg2] điểm <PowerIconKeywords:lực lượng tạm thời>. Chọn 1 thẻ lệnh không tiêu hao và không phái sinh trong tay mà không có\"Nhạc âm\"để thêm \"<HuihuanaKeywords:âm nhạc vòng quay>\". Nếu mỗi lần không có tay nào có thể được thêm, thay vào đó gây thêm 3 lần sát thương"
  },
  Skill_59477_BattleDesc_2 = {
    Text = "Gây ngẫu nhiên [Arg3] lần <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:Sát thương xuyên thấu>, mỗi lần gây thương tổn tạm thời giảm [Exhaustion:Arg2] điểm <ExhaustionIconKeywords:lực lượng> của mục tiêu và nhận [Power:Arg2] điểm <PowerIconKeywords:lực lượng tạm thời>. Chọn 1 thẻ lệnh không tiêu hao và không phái sinh trong tay mà không có \"Nhạc âm\"để thêm \"<HuihuanbKeywords:âm nhạc vòng quay>\". Nếu mỗi lần không có tay nào có thể được thêm vào, thay vào đó gây thêm 3 lần thương tổn"
  },
  Skill_59477_Desc_0 = {
    Text = "Gây ngẫu nhiên 3 lần <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:sát thương xuyên thấu>, mỗi lần gây thương sẽ <TouquKeywords:trộm cắp> [Arg2] điểm <PowerIconKeywords:lực lượng> từ mục tiêu. Chọn 1 thẻ lệnh trong tay không tiêu hao, không phái sinh và không có \"Nhạc âm\"để thêm hiệu ứng \"<HuihuanaKeywords:âm nhạc vòng quay>\". Mỗi lần nếu không có tay bài nào có thể thêm, sẽ thay thế bằng việc gây thêm 3 lần thương"
  },
  Skill_59477_Desc_2 = {
    Text = "Gây ngẫu nhiên 3 lần <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:sát thương xuyên thấu>, mỗi lần gây thương <TouquKeywords:trộm cắp> [Arg2] điểm <PowerIconKeywords:lực lượng> tạm thời từ mục tiêu. Chọn 1 thẻ lệnh trong tay không có \"Nhạc âm\", không tiêu hao và không phái sinh để thêm hiệu ứng \"<HuihuanbKeywords:âm nhạc vòng quay>\". Nếu mỗi lần không có tay có thể thêm, thay vào đó gây thêm 3 lần thương"
  },
  Skill_59477_EffectNameList = {
    Text = "Thương, hút lấy sức mạnh"
  },
  Skill_59477_Name = {
    Text = "Nốt nhạc nguyên thủy"
  },
  Skill_59477_OverLimitUtlSkillDesc = {
    Text = "Gây ngẫu nhiên <Damage:[Damage:Arg1]> điểm<PunctureDamagewords:sát thương xuyên thấu> [Arg3] lần, mỗi lần gây 1 lần thương sẽ tạm thời giảm [Exhaustion:Arg2] điểm<ExhaustionIconKeywords:lực lượng> của mục tiêu, nhận được [Power:Arg2] điểm<PowerIconKeywords:lực lượng tạm thời>, và áp dụng ngẫu nhiên 1 loại<MysterydebuffKeywords:hiệu ứng tiêu cực kỳ diệu> lên mục tiêu. Chọn 2 thẻ lệnh không tiêu hao, không phái sinh và không có \"Nhạc âm\" trong tay để thêm \"<HuihuanbKeywords:Âm nhạc vòng quay>\". Nếu mỗi lần không có thẻ nào trong tay có thể thêm, sẽ thay thế bằng việc gây thêm 3 lần thương."
  },
  Skill_59477_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1, sức tấn công*GrowValue2"
  },
  Skill_59478_AwakerSkillBackgroundStory = {
    Text = "Nếu linh hồn có thể tách ra, liệu những gì cấu thành nó sẽ là những nốt nhạc. Cao và thấp, nhanh và chậm, tiếng khóc của sự sinh ra và tiếng rên rỉ của cái chết hòa cùng vang lên. Hãy lắng nghe, hãy cùng nhau hát thật to, đây là khúc dạo đầu vẽ nên hình dáng linh hồn bạn."
  },
  Skill_59478_BattleDesc = {
    Text = "Gây ngẫu nhiên [Arg2] lần <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:sát thương xuyên thấu>, mỗi lần gây thương có 50% xác suất áp dụng 1 loại <MysterydebuffKeywords:hiệu ứng tiêu cực kỳ diệu>. Nếu khi chơi mà giá trị điểm tính toán tiêu thụ bằng 0, gây thêm 2 lần thương."
  },
  Skill_59478_Desc = {
    Text = "Gây ngẫu nhiên 3 lần <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:sát thương xuyên thấu>, mỗi lần gây thương có 50% xác suất áp dụng 1 loại <MysterydebuffKeywords:hiệu ứng tiêu cực kỳ diệu> cho mục tiêu. Nếu khi chơi mà giá trị điểm tính toán tiêu thụ bằng 0, gây thêm 2 lần thương."
  },
  Skill_59478_EffectNameList = {Text = "thương"},
