  },
  Skill_59479_AwakerSkillBackgroundStory = {
    Text = "Bạn đã nghe thấy âm thanh như vậy chưa? Nó thật quen thuộc, thân thuộc, khiến bạn nhớ lại những dư âm của cả một đời. Rốt cuộc bạn đã nghe thấy ở đâu? Trong giấc mơ của bạn, trong ký ức của bạn, hay trong tiếng gọi từ thiên đường trước khi chết, được cất lên bởi thiên thần thổi sáo."
  },
  Skill_59479_Desc = {
    Text = "Được [Power:Arg1] điểm <PowerIconKeywords:lực lượng>. Đặt 2 lá <DerivativeCardKeywords_4:「cảm hứng」> vào tay. Khi sức tính toán không đủ, vẫn có thể đánh ra, hiệu ứng sẽ thay đổi thành đưa 2 lá 「cảm hứng」vào rút bài từ bộ bài."
