  Skill_60256_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm<PunctureDamagewords:đâm xuyên> thương, thương càng cao khi mục tiêu có sức sống cao. Áp dụng [Arg3] lớp<FragileIconKeywords:yếu đuối>."
