  Skill_60256_Name = {
    Text = "Dạ kiếm \"<PunctureDamagewords:xuyên thủng>\""
  },
  Skill_60272_Desc = {
    Text = "Đặt 3 lá <AberrationKeywords:quái dị> ngẫu nhiên và 1 lá \"triệu chứng\" vào bộ bài rút từ bộ bài."
  },
  Skill_60272_Name = {
    Text = "Để cho thế giới này"
  },
  Skill_60273_Desc = {
    Text = "Hãy nói cho ta biết, người giữ bí mật… điều gì khiến ngươi vẫn tiếp tục chiến đấu?\nNếu chơi thẻ bài khác trong khi thẻ này vẫn còn trong tay, \"Tà Vy\" sẽ giận dữ, gây [Arg1] điểm <FixedDamage:Sát Thương Thuần Túy> cho ta."
  },
  Skill_60273_Name = {
    Text = "Đáp lại Tà Vy"
  },
  Skill_60274_Desc = {
    Text = "\"Tà Vy\" nhận được 3 lớp <ExclamationPointColour:chuỗi căm hận>."
  },
  Skill_60274_Name = {
    Text = "Để dành cho người bạn quan tâm"
  },
  Skill_60275_Desc = {
    Text = "Sẽ đính kèm <ErosionColorInkKeywords:nhận thức hỗn loạn> lên 7 thẻ lệnh ngẫu nhiên."
  },
  Skill_60275_Name = {
    Text = "Chỉ để cho bản thân mà thôi"
  },
  Skill_60285_Desc = {
    Text = "Chọn một thân thể được đánh thức để nhận 30 điểm điên cuồng, các thân thể được đánh thức khác mất 10 điểm điên cuồng. Nếu lá bài này vẫn ở trong tay vào cuối lượt, gây [Arg1] thương cho đội của tôi."
  },
  Skill_60285_Name = {
    Text = "Chân · Luân Hồi Bác Luận"
  },
  Skill_60286_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [AttackTimes:Arg2] lần, thêm 2 lá \"Chân · Luân Hồi Bế Tắc\" vào bài trên tay."
  },
  Skill_60286_Name = {
    Text = "Cánh đôi lần đầu tiên mở rộng"
  },
  Skill_60287_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương [AttackTimes:Arg2], thêm 6 lá \"Chân · Luân Hồi Bác Luận\" vào bộ bài trên tay."
  },
  Skill_60287_Name = {
