  },
  Skill_61121_AwakerSkillBackgroundStory = {
    Text = "Atropos đã cắt đứt sợi dây đen, số phận của người Tirlo bị đoạn tuyệt. \nKẻ sát thủ dùng xiềng xích làm vũ khí, từng rất dũng mãnh, \ncuối cùng gục ngã trước vô số giáo."
  },
  Skill_61121_BattleDesc = {
    Text = "Mất 10%([Arg2]) sức sống hiện tại, gây <Damage:[Damage:Arg1]> thương ngẫu nhiên 2 lần và thêm 50% thương dưới dạng <BleedingIconKeywords:chảy máu>. Sau khi sử dụng 3 lần, biến thành \"<DerivativeCardKeywords_66:chuỗi máu>\"([Arg3]/3)."
  },
  Skill_61121_Desc = {
    Text = "Mất 10% sức sống hiện tại, gây <Damage:[Damage:Arg1]> điểm thương ngẫu nhiên 2 lần và thêm 50% thương dưới dạng <BleedingIconKeywords:chảy máu>. Sau khi đánh 3 lần, biến thành \"<DerivativeCardKeywords_66:chuỗi máu thèm khát>\"."
