  },
  Skill_61122_AwakerSkillBackgroundStory = {
    Text = "Atropos đã cắt đứt sợi dây đen, số phận của người Tirlo bị đoạn tuyệt. \nKẻ sát thủ dùng xiềng xích làm vũ khí, từng rất dũng mãnh, \ncuối cùng gục ngã trước vô số giáo."
  },
  Skill_61122_BattleDesc = {
    Text = "Được xem là\"đánh\". Gây <Damage:[Damage:Arg1]> điểm thương, thương này được tăng cường 5 lần lực lượng và kích hoạt 30% <BleedingIconKeywords:chảy máu> của mục tiêu, hồi phục [Arg3]% sức sống đã mất(<Heal:[Arg2]>). Sau khi sử dụng, biến thành \"<DerivativeCardKeywords_65:chuỗi máu>\"."
  },
  Skill_61122_Desc = {
    Text = "Được xem là \"đánh\". gây <Damage:[Damage:Arg1]> thương, thương này được tăng cường 5 lần lực lượng và kích hoạt 30% <BleedingIconKeywords:chảy máu> của mục tiêu, hồi phục 15% máu đã mất. Sau khi sử dụng sẽ trở thành \"<DerivativeCardKeywords_65:chuỗi máu>\"."
  },
  Skill_61122_EffectNameList = {Text = "thương"},
  Skill_61122_Name = {
    Text = "Bóng xích thèm máu"
  },
  Skill_61122_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1"
  },
  Skill_61123_AwakerSkillBackgroundStory = {
    Text = "Hãy hát lên, nữ thần! Hãy hát về số phận của cô gái Delos: \n tràn đầy máu và nước mắt, giận dữ và tuyệt vọng. \n Sự thù hận của cô ấy như ngọn lửa, thiêu rụi mọi thứ xung quanh, và cuối cùng, \n mang đến cái chết của chính cô."
  },
  Skill_61123_Desc_0 = {
    Text = "Máu Liên · Hiro nhận được <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Thức tỉnh linh tri thức>: Đưa một thẻ \"<DerivativeCardKeywords_65:chuỗi máu>\" vào tay, các thẻ lệnh của Máu Liên · Hiro nhận được \"<RetainIconKeywords:giữ lại>\". Khi bắt đầu lượt, thương cơ bản của Máu Liên · Hiro tăng [Arg2]% trong suốt trận chiến này."
  },
  Skill_61123_Desc_15 = {
    Text = "Huyết Liên·Shilo nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Đưa một lá\"<DerivativeCardKeywords_65:Xiềng Xích Máu>\" vào tay, thẻ chỉ lệnh của Huyết Liên·Shilo nhận được \"<RetainIconKeywords:Giữ lại>\". Khi bắt đầu lượt, sát thương cơ bản của Huyết Liên·Shilo tăng [Arg2]% trong trận chiến này. Sau khi giải phóng bùng nổ Cuồng Khí\"Xiềng Xích Trói Thân\", ban cho mỗi thẻ chỉ lệnh \"Huyết Liên·Shilo\" khác nhau trong tay 50 tầng <TempPowerKeywords:Cường Hóa Tạm Thời>."
  },
  Skill_61123_EffectNameList = {
    Text = "Điên cuồng, tăng sát thương"
  },
  Skill_61123_Name = {
    Text = "Tuyên bố của Người Thu Thập Hồn"
  },
  Skill_61124_AwakerSkillBackgroundStory = {
    Text = "Clotho, Clotho, nữ thần cầm cuộn sợi, \nngươi lấy sợi từ đâu? \nDù có phá vỡ xiềng xích, những người dân đảo Delos đáng thương, \ncũng không thể thoát khỏi số phận đã định."
  },
  Skill_61124_Desc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ>: Rút 1 thẻ lệnh của Dây máu · Hiro, giảm tiêu thụ sức tính toán của thẻ lệnh Dây máu · Hiro trong tay đi 1 điểm.] Trong lượt này, khi Dây máu · Hiro gây sát thương chủ động, thêm [Arg2]% <BleedingIconKeywords:chảy máu>. Gây ra <Damage:[Damage:Arg1]> điểm thương."
