  },
  Skill_66302_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương trong [AttackTimes:Arg2] lần. Tất cả các thân thể được đánh thức giảm 100% điên cuồng. Người giữ bí mật có sức tính toán tối đa giảm 5 và giới hạn thẻ trên tay giảm 10."
  },
