  Skill_66349_AwakerSkillBackgroundStory = {
    Text = "Cô ấy biết quá khứ, hiện tại và tương lai.\nCô ấy biết mọi thứ bắt đầu như thế nào và sẽ kết thúc ra sao.\nGiữa tai cô vang vọng hơi thở của \"Ngài\"."
  },
  Skill_66349_Desc_0 = {
    Text = "Khi ở trong tay, nếu lá bài trên đầu rút bài từ bộ bài là thẻ lệnh, biến thành bản sao của nó. Sau khi đánh, khôi phục và nhận <Energy:[Energy:Arg1]> điểm điên cuồng."
  },
  Skill_66349_Desc_1 = {
    Text = "Khi ở trong bộ bài trên tay, nếu lá bài trên cùng của rút bài từ bộ bài là thẻ lệnh, biến thành bản sao có sức tính toán tiêu thụ -1. Sau khi đánh ra, khôi phục lại, nhận được <Energy:[Energy:Arg1]> điểm điên cuồng."
  },
  Skill_66349_EffectNameList = {
    Text = "điên cuồng"
  },
  Skill_66349_Name = {
    Text = "Thông hiểu lý vạn vật"
  },
  Skill_66350_AwakerSkillBackgroundStory = {
    Text = "Đi qua cánh cửa chìa khóa bạc, nhân loại quỳ trước ngai vàng của Ngài, tìm kiếm câu trả lời tối thượng. \n Còn cô ấy là người canh gác, cô ấy có trách nhiệm ngăn cản, nhắc nhở, cảnh báo. \n Không tiết lộ mới là lòng từ bi của cô ấy."
  },
  Skill_66350_BattleDesc_0 = {
    Text = "Tà Vy nhận được <Energy:[Energy:Arg1]> điểm Điên loạn. Đặt 1 thẻ \"<DerivativeCardKeywords_67:Ánh Sáng Bạc Khóa>\" vào tay. Mỗi khi Tà Vy tiêu hao 1 điểm Điểm tính toán, nhận được Năng lượng chìa khóa bạc tương đương 50% Sạc năng lượng chìa khóa bạc."
  },
  Skill_66350_BattleDesc_15 = {
    Text = "Tà Vy nhận được <Energy:[Energy:Arg1]> điểm Điên loạn. Đặt 1 thẻ \"<DerivativeCardKeywords_67:Ánh Sáng Bạc Khóa>\" vào tay. Mỗi khi Tà Vy tiêu hao 1 điểm Điểm tính toán, nhận được Năng lượng chìa khóa bạc tương đương 50% Sạc năng lượng chìa khóa bạc. Sau khi Tà Vy kích hoạt Bùng nổ, Sát thương cuối cùng của thẻ lệnh tất cả Thể thức tỉnh trong lượt này tăng lên [Arg2]% và làm cho thẻ lệnh của Thể thức tỉnh khác tiếp theo được chơi ra cũng Có hiệu lực thêm 1 lần."
  },
  Skill_66350_Desc_0 = {
