  Skill_67180_Name = {Text = "Phân li"},
  Skill_67181_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> thương [Arg2] lần, số lần gây thương của \"kiếm của nữ hoàng\" phát động sau đó tăng thêm 1."
  },
  Skill_67181_Name = {
    Text = "kiếm của nữ hoàng"
  },
  Skill_67182_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm <PunctureDamagewords:sát thương xuyên thấu> [Arg2] lần và áp dụng <BleedingIconKeywords:chảy máu> tương đương, áp dụng 1 lượt <VulnerabilityIconKeywords:trọng thương>. Nếu lá chắn bị phá vỡ, chuyển thành \"Ngọn Giáo Nổi Giận\": không còn gây sát thương xuyên thấu và chảy máu, nhưng số lần sát thương tăng thêm 1."
  },
  Skill_67182_Name = {
    Text = "\"đâm xuyên\" ngọn thương"
  },
  Skill_67183_Desc = {
    Text = "Gây ra <Damage:[Damage:Arg1]> sát thương [Arg2] lần."
  },
  Skill_67183_Name = {Text = "Đánh"},
  Skill_67184_Desc = {
    Text = "Sau giai đoạn rút bài, ngẫu nhiên hiển thị 3 thẻ lệnh từ tay, chọn một thẻ để trao cho khắcăng \"Hồi Âm\", bỏ đi các thẻ bài còn lại."
