  },
  Skill_67185_Name = {
    Text = "phẫu thuật ngoại vực"
  },
  Skill_67186_Desc = {
    Text = "Áp dụng [Poison:Arg1] trạng thái<IntoxicationIconKeywords:trúng độc>. Sau khi kết thúc lượt, kẻ địch khác nhận [Power:Arg2] điểm<PowerIconKeywords:lực lượng>."
  },
  Skill_67186_Name = {
    Text = "số phận sụp đổ"
  },
  Skill_67187_Desc = {
    Text = "<TouquKeywords:Vĩnh viễn đánh cắp> [Arg1] điểm <PowerIconKeywords:lực lượng> và loại bỏ 50% <RetaliateIconKeywords:phản công>, đính kèm \"suy diễn\" cho 5 thẻ bài không có \"suy diễn\"."
