  },
  Skill_67856_AwakerSkillBackgroundStory = {
    Text = "Trong sự cô đơn dài đằng đẵng, cô đã dần quên lãng lý do mình vung kiếm. \nNhưng cô biết rõ rằng, mình phải đưa ra nhát kiếm quyết định này."
  },
  Skill_67856_Desc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương, <PowerIconKeywords:lực lượng> trên \"Mệnh Định Chi Kiếm\" phát huy [Arg2] lần hiệu ứng. Mỗi lần sử dụng lệnh khóa, tỷ lệ lực lượng tăng gấp đôi trong trận chiến này."
