  Skill_70299_AwakerSkillBackgroundStory = {
    Text = "Cô ấy cả đời theo đuổi điểm đến, giờ đây đã hiện ra ngay trước mắt. \n Cánh cửa tối tăm tỏa ra sức hút chết người. \n Trước khi đẩy cửa, cô đã hình dung ra 372 khả năng của sự thật. \n Sau khi đẩy cửa, chỉ còn lại điều thứ 373 mà cô không muốn thừa nhận. \n Không có sự lựa chọn, cô chỉ có thể rơi xuống. \n Thật sự không may, bản thân và cả thế giới."
  },
  Skill_70299_BattleDesc = {
    Text = "Các Thể thức tỉnh khác nhận <Energy:[Energy:Arg1]> điểm điên cuồng, áp [Poison:Arg2] lớp <IntoxicationIconKeywords:Ngộ độc> lên tất cả kẻ địch, Khuếch đại sát thương tạm thời +[Arg3]%."
  },
  Skill_70299_Desc = {
    Text = "Các Thể thức tỉnh khác nhận <Energy:[Energy:Arg1]> điểm điên cuồng, áp [Poison:Arg2] lớp <IntoxicationIconKeywords:Ngộ độc> lên tất cả kẻ địch, Khuếch đại sát thương tạm thời +[Arg3]%. \"Cuối cùng hình thái\": Rút thêm 3 thẻ bài, nhận 3 điểm Điểm tính toán, kích hoạt 50% <IntoxicationIconKeywords:Ngộ độc> của tất cả kẻ địch, Cuồng khí cơ bản của \"Tan chảy · Đóa\" tăng lên 50 điểm, tối đa tăng 3 lần."
