  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Các Thể thức tỉnh khác nhận <Energy:[Energy:Arg4]> điểm điên cuồng, áp [Poison:Arg2] lớp <IntoxicationIconKeywords:Ngộ độc> lên tất cả kẻ địch, Khuếch đại sát thương tạm thời +[Arg3]%, Sát thương cơ bản của <IntoxicationIconKeywords:Ngộ độc>, <RetaliateIconKeywords:phản công> do tất cả Thể thức tỉnh gây ra tăng lên 10%. Nếu hiện tại là Trận chiến Lãnh đạo, nhận thêm 1 lớp \"Cuối cùng\"."
  },
  Skill_70299_PropertyNameList = {
