  },
  Skill_70300_AwakerSkillBackgroundStory = {
    Text = "Khi bào tử đỏ tươi phình to dưới lớp vỏ máy móc, bộ cộng hưởng bằng đồng dệt nên ma trận phòng thủ hình tổ ong. \n Mạng lưới nấm mạch xé rách không gian, sương axit khắc họa những văn tự cảnh báo, trong khi tia sáng tách biệt ký ức đang được làm nóng - bất kỳ thứ gì chạm vào ranh giới của thịt máu, cuối cùng sẽ trở thành bản mẫu co giật trong đĩa nuôi cấy."
  },
  Skill_70300_BattleDesc = {
    Text = "Nhận được <Block:[Block:Arg1]> điểm lá chắn. Nhận được <Energy:[Energy:Arg2]> điểm khí điên cuồng."
