    Text = "Cô ấy đã hiến tế bản thân để đổi lấy tư cách chạm vào sự thật. \nKhi cô ấy rút tay về, linh hồn của cô đã tan chảy như sáp."
  },
  Skill_70302_BattleDesc_0 = {
    Text = "\"Dung Hủy·Doãn Nhĩ\" nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Khi kết thúc lượt, hồi phục <Heal:[Heal:Arg2]> điểm sinh mệnh và nhận <Energy:[Energy:Arg4]> điểm Cuồng Khí.\"Hình Thái Chung Mạt\": Không còn hồi phục sinh mệnh, thay vào đó kích hoạt [Arg3]% <IntoxicationIconKeywords:Trúng Độc> của tất cả kẻ địch."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "\"Dung Hủy·Doãn Nhĩ\" nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Mỗi 1 tầng \"Chung Mạt\" sở hữu, sát thương cường hiệu +8%. \"Hư Vô Chung Kết\" giúp tất cả Thức Tỉnh Thể nhận 30% Cuồng Khí cơ bản. Khi kết thúc lượt, hồi phục <Heal:[Heal:Arg2]> điểm sinh mệnh và nhận <Energy:[Energy:Arg4]> điểm Cuồng Khí.\"Hình Thái Chung Mạt\": Không còn hồi phục sinh mệnh, thay vào đó kích hoạt [Arg3]% <IntoxicationIconKeywords:Trúng Độc> của tất cả kẻ địch."
  },
  Skill_70302_Desc_0 = {
    Text = "\"Phá hủy·Búp bê\" nhận được <Energy:[Energy:Arg1]> điểm Aliemus.<ExaltIconKeywords:Đánh thức>:Cuối mỗi vòng, hồi phục <Heal:[Heal:Arg2]> điểm cuộc sống và nhận được Aliemus tương đương với khả năng hồi Aliemus của bản thân.\"Hình thức kết thúc\":Không hồi phục cuộc sống nữa, thay vào đó kích hoạt <IntoxicationIconKeywords:Độc dược> [Arg3]% trên tất cả kẻ địch."
  },
  Skill_70302_Desc_15 = {
    Text = "\"Dung Hủy·Doãn Nhĩ\" nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Mỗi 1 tầng \"Chung Mạt\" sở hữu, sát thương cường hiệu +8%. \"Hư Vô Chung Kết\" giúp tất cả Thức Tỉnh Thể nhận 30% Cuồng Khí cơ bản. Khi kết thúc lượt, hồi phục <Heal:[Heal:Arg2]> điểm sinh mệnh và nhận Cuồng Khí tương đương với lượng hồi Cuồng Khí của bản thân.\"Hình Thái Chung Mạt\": Không còn hồi phục sinh mệnh, thay vào đó kích hoạt [Arg3]% <IntoxicationIconKeywords:Trúng Độc> của tất cả kẻ địch."
