  },
  Skill_78782_AwakerSkillBackgroundStory = {
    Text = "Trong chiếc quả lắc đang rung động, thế giới bắt đầu bị xóa nhòa.\nTrong đôi mắt bạn, trong trái tim bạn, trong đầu bạn, chỉ còn lại một hình bóng.\nĐó là sự cứu chuộc, cũng là con đường tuyệt vọng."
  },
  Skill_78782_BattleDesc = {
    Text = "Hồi phục <Heal:[Heal:Arg1]> điểm sinh lực [Arg2] lần, tạm thời loại bỏ tất cả trạng thái <MadnessIconKeywords:điên rồ> của kẻ địch và làm giảm tạm thời [Exhaustion:Arg3] điểm <ExhaustionIconKeywords:lực lượng>. <WormholeKeywords:Chuẩn tinh>: Nhận [Power:Arg4] điểm <PowerIconKeywords:lực lượng>."
  },
  Skill_78782_Desc = {
    Text = "Hồi phục <Heal:[Heal:Arg1]> điểm sinh lực, tạm thời loại bỏ tất cả trạng thái <MadnessIconKeywords:điên rồ> của kẻ địch và làm giảm tạm thời [Exhaustion:Arg3] điểm <ExhaustionIconKeywords:lực lượng>. <WormholeKeywords:Chuẩn tinh>: Nhận [Power:Arg4] điểm <PowerIconKeywords:lực lượng>."
  },
  Skill_78782_EffectNameList = {
    Text = "Hồi phục, giảm sức mạnh, sức mạnh"
  },
  Skill_78782_Name = {
    Text = "Sự an ủi tinh thần"
  },
  Skill_78782_PropertyNameList = {
    Text = "Thể chất *GrowValue1, khả năng phòng thủ *GrowValue2, khả năng tấn công *GrowValue3"
  },
  Skill_78783_AwakerSkillBackgroundStory = {
    Text = "Giọng nói của cô ấy nhẹ nhàng và ân cần, trong bóng tối mà bạn không nhìn thấy của tâm hồn, đang quấn quýt lan tỏa.\nMột người không thể bị đánh bại bởi sự tồn tại bên ngoài bản thân mình, và chính bạn là vũ khí của cô ấy."
  },
  Skill_78783_BattleDesc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm sát thương [Arg2] lần, nhận <Energy:[Energy:Arg5]> điểm Aliemus. <WormholeKeywords:Kích thước siêu lớn>: Nhận [Power:Arg4] điểm <PowerIconKeywords:Sức mạnh>."
  },
  Skill_78783_Desc = {
    Text = "Gây ra <Damage:[Damage:Arg1]> sát thương, Clementine nhận <Energy:[Energy:Arg3]> điểm Aliemus. <WormholeKeywords:Ultra distance>：Nhận [Power:Arg4] điểm <PowerIconKeywords:Sức mạnh>."
  },
  Skill_78783_EffectNameList = {
    Text = "Sát thương, Aliemus, Sức mạnh"
  },
  Skill_78783_Name = {Text = "Đánh"},
  Skill_78783_PropertyNameList = {
    Text = "Sức tấn công*GrowValue1,$GrowValue2,sức tấn công*GrowValue3"
  },
  Skill_78784_Desc = {
    Text = "Mỗi khi loại bỏ 1 tầng \"Cảm thông\" của bản thân, sẽ áp dụng 1 tầng \"Sợ hãi cố định\" cho tất cả kẻ thù, mỗi tầng \"Sợ hãi cố định\" sẽ giảm 3% sát thương mà mục tiêu gây ra."
  },
  Skill_78784_Name = {
    Text = "Chuyển đổi · Cố định Sợ hãi"
  },
  Skill_78785_AwakerSkillBackgroundStory = {
    Text = "\"Xin hãy cho tôi biết, thực sự bạn là ai?\"\nCô ấy hỏi như vậy và bật cười.\nNgười bệnh đáng thương dĩ nhiên không thể trả lời, vì ký ức của anh ta đã bị sửa đổi, càng tìm kiếm càng gần gũi với sự tồn tại kinh hoàng được cài cắm vào ký ức - cho đến khi nhận thức hoàn toàn sụp đổ, biến thành quái vật."
  },
  Skill_78785_BattleDesc_0 = {
    Text = "Loại bỏ tất cả <AnalysisKeywords0:Cảm thông> của bản thân, chọn chuyển hóa thành <D13AFKeyWord2:Thương tổn tinh thần> hoặc <D13AFKeyWord1:Sự cố định sợ hãi> cho tất cả kẻ địch. Gây ra <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch [Arg6] lần, nhận <Posse:[Arg3]> điểm năng lượng chìa khóa bạc."
  },
  Skill_78785_BattleDesc_2 = {
    Text = "Loại bỏ tất cả <AnalysisKeywords0:Cảm thông> của bản thân, chọn chuyển hóa thành <D13AFKeyWord2:Thương tổn tinh thần> hoặc <D13AFKeyWord1:Sự cố định sợ hãi> cho tất cả kẻ thù, mỗi khi loại bỏ 1 lớp sẽ làm tăng 3% sát thương cơ bản mà Clementine gây ra. Gây <Damage:[Damage:Arg1]> điểm thương cho tất cả kẻ địch [Arg6] lần, nhận <Posse:[Arg3]> điểm năng lượng chìa khóa bạc."
  },
  Skill_78785_BattleDesc_3 = {
