  Skill_81343_Desc = {
    Text = "Loại bỏ 1 tầng \"Năng lượng vũ trụ u tối\", <WeaknessIconKeywords:yếu đuối> và <HeavyInjuryKeywords:tổn thương nghiêm trọng> [Arg1] lượt, áp dụng \"Nhận thức hỗn loạn\" trên [Arg2] thẻ lệnh trong cụm bốc thăm."
  },
  Skill_81343_Name = {
    Text = "Sự can thiệp của tổ sâu"
  },
  Skill_81433_Desc = {
    Text = "Giải trừ tất cả các trạng thái <CardKeyWord:Phong ấn> và giảm tỷ lệ chí mạng của Thức Tỉnh, loại bỏ trạng thái \"Gia Cố\" của kẻ thù. Đưa 5 thẻ lệnh gốc không phải là biến thể được sử dụng cuối cùng trong lượt trước vào tay, tiêu hao số học của chúng thành 0 và nhận <DepleteIconKeywords:Kiệt sức> và <NothingnessIconKeywords:Ảo giác>."
  },
  Skill_81433_Name = {
    Text = "Cứu hộ theo dõi ngược"
  },
  Skill_83574_BattleDesc = {
    Text = "Xóa tất cả \"Bật buồm\" ([Arg1]). Mỗi lớp bị xóa, Sát thương cuối cùng tăng [Arg2]%, tất cả Thể thức tỉnh nhận [Arg3] điểm điên cuồng.\nNếu xóa 5 lớp hoặc hơn \"Bật buồm\" cùng một lúc, <VulnerabilityIconKeywords:Trọng thương> tất cả kẻ địch 1 lượt, gây <FixedDamage:Sát Thương Thuần Túy> bằng [Arg4]% Điểm mạng đã mất cho chúng."
  },
  Skill_83574_Desc = {
    Text = "Xóa tất cả \"Bật buồm\". Mỗi lớp bị xóa, Sát thương cuối cùng tăng 10%, tất cả Thể thức tỉnh nhận 5 điểm điên cuồng.\nNếu xóa 5 lớp hoặc hơn \"Bật buồm\" cùng một lúc, gây Trọng thương cho tất cả kẻ địch 1 lượt, gây <FixedDamage:Sát Thương Thuần Túy> bằng 35% Điểm mạng đã mất cho chúng."
  },
  Skill_83574_Name = {
    Text = "Phá sóng khởi hành"
  },
  Skill_83575_BattleDesc = {
    Text = "Xóa tất cả \"Neo Bến\" ([Arg1])。Mỗi lần xóa 1 tầng, kháng cự cái chết + [Arg2]% ，nhận [Arg3] số học, bốc thăm [Arg4] thẻ。\nNếu xóa một lúc 5 tầng hoặc nhiều hơn \"Neo Bến\", nhận [Arg5] tầng <ParcloseIconKeywords: hàng rào> tạm thời。"
  },
  Skill_83575_Desc = {
    Text = "Xóa bỏ tất cả các \"Thả neo\". Mỗi lớp xóa bỏ, \"Kháng cự tử vong\" + 15%, nhận 1 số học, rút 1 lá bài.\nNếu xóa bỏ một lần 5 lớp hoặc hơn \"Thả neo\", nhận 1 lớp \"Hàng rào\"."
  },
  Skill_83575_Name = {
    Text = "Nghỉ tạm bờ sông"
  },
  Skill_83576_BattleDesc = {
    Text = "Chọn:\"Đột phá sóng\"([Arg1]) hoặc \"Nghỉ ngơi bên bờ\"([Arg2]). Khi bị bỏ đi sẽ <DepleteIconKeywords:tiêu hao>."
  },
  Skill_83576_Desc = {
    Text = "Lựa chọn: \"Khởi hành sóng\" hoặc \"Xuống bến nghỉ ngơi\". Khi loại bỏ thì sẽ <DepleteIconKeywords:Kiệt sức>."
  },
  Skill_83576_Name = {
    Text = "Quyết định của người dẫn đường"
  },
  Skill_83779_AwakerSkillBackgroundStory = {
    Text = "Biển nước mặn vô tận nuốt chửng cô, đồng thời cũng che chở cô.\n Trong cảm giác chìm đắm ngột ngạt ấy, cô cảm nhận được đại dương sâu thẳm, hòa mình vào đại dương sâu thẳm.\n Rồi một ngày, đại dương sẽ hoàn toàn yên tĩnh, mỗi con tàu di chuyển trên mặt biển sẽ được ban phước an bình.\n Cô chờ đợi ngày đó, ngày mà \"Vùng đất thần thánh hạ xuống\"."
  },
  Skill_83779_Desc_0 = {
    Text = "Copperchant nhận được <Energy:[Energy:Arg1]> điểm aliemus. <ExaltIconKeywords:Đánh thức tri thức>: nhận được 1 xúc tu, đưa vào tay 2 lá bài \"<DerivativeCardKeywords_106:Người dẫn đường>\". Sau khi chuyển sang tư thế\"Biển tĩnh\" nhận được <Block:[Block:Arg2]> điểm khiên, 3 lượt hạ nhiệt."
  },
  Skill_83779_Desc_15 = {
    Text = "Corpusant nhận được <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Nhận được 1 xúc tu, đặt 2 lá\"<DerivativeCardKeywords_106:Lĩnh Hàng>\" vào tay, lá\"Trừng Giới Lôi Đình\" và\"Hỗn Độn Kỳ Ngữ\"đầu tiên mỗi lượt sẽ đặt thêm 1 lá\"<DerivativeCardKeywords_106:Lĩnh Hàng>\" vào tay, hiệu ứng \"<DerivativeCardKeywords_106:Lĩnh Hàng>\" tăng 50%. Sau khi chuyển sang tư thế\"Tĩnh Hải\" nhận được <Block:[Block:Arg2]> điểm hộ thuẫn, hồi chiêu 3 lượt."
  },
  Skill_83779_EffectNameList = {
    Text = "Điên cuồng, lá chắn"
