  },
  Skill_83780_AwakerSkillBackgroundStory = {
    Text = "Đám mây sẽ báo hiệu sự thay đổi của thời tiết, sóng sẽ kể về sự biến chuyển của dòng hải lưu, nhưng khi bão tố thực sự đến, thì ngay cả những con tàu khổng lồ nhất cũng chỉ có thể vô vọng trôi theo dòng. \n Lúc này, sự tính toán và chỉ dẫn của người điều hướng là con đường cuối cùng cho tất cả những người sống sót. \n Vì vậy hãy thực hiện trách nhiệm của mình, dù cho sấm chớp có giáng xuống, cũng phải trong nỗi đau, nở ra một chút ánh sáng, chỉ ra hướng về bờ. \n Đó là sứ mệnh mà bạn phải hoàn thành."
  },
  Skill_83780_BattleDesc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên và [Arg2] xúc tu tạm thời. Bỏ tất cả thẻ bài trên tay và rút số lượng thẻ tương đương."
  },
  Skill_83780_BattleDesc_3 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên và [Arg2] xúc tu tạm thời. <VulnerabilityIconKeywords:Dễ tổn thương> tất cả kẻ thù 1 lượt, sát thương chí mạng tạm thời + [Arg5] %. Bỏ tất cả thẻ bài trên tay và rút số lượng thẻ tương đương."
  },
  Skill_83780_Desc_0 = {
