  Skill_89776_AwakerSkillBackgroundStory = {
    Text = "\"Anh trai, em hỏi rằng bay mãi, bay mãi nhờ đôi cánh, rốt cuộc có thể bay cao đến mức nào? Có thể bay lên trên mây, chạm vào mặt trăng và các vì sao không?\"\n\"Có lẽ... có thể chứ? Nhưng chúng ta phải có một đôi cánh thật lớn và mạnh mẽ.\"\nNhững dải ngân hà và chòm sao huyền ảo trên cuốn sách tay in bóng vào giấc mộng say sưa của hai đứa trẻ, biến thành hạt giống của một ước mơ, chôn vùi trong trái tim chúng."
  },
  Skill_89776_Desc_0 = {
    Text = "Cas-tơ-lơ nhận <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>:Thương của Cas-tơ-lơ chắc chắn là đòn đánh chí mạng,\"<DerivativeCardKeywords_107:Lông đen>\" sau khi chơi sẽ áp dụng [Corrosion:Arg2] tầng <Corrosion:Xói mòn> lên mục tiêu, lá chắn giữ lại tăng 50%."
  },
  Skill_89776_Desc_15 = {
    Text = "Cas-tơ-lơ nhận <Energy:[Energy:Arg1]> điểm Điên loạn. <ExaltIconKeywords:Khai mở linh trí>:Thương của Cas-tơ-lơ chắc chắn là đòn đánh chí mạng,\"<DerivativeCardKeywords_107:Lông đen>\" sau khi chơi sẽ áp dụng [Corrosion:Arg2] tầng <Corrosion:Xói mòn> lên mục tiêu, lá chắn giữ lại tăng 50%. Mỗi lượt lần đầu chơi Lông đen sẽ gây Xói mòn tương đương Tài năng \"Lông Thánh Tẩy Tội\" lên kẻ địch hàng trước, Sinh lực mất khi Xói mòn bị loại bỏ tăng từ 300% lên 500%."
