  Skill_89779_Name = {Text = "Lông đen"},
  Skill_89780_AwakerSkillBackgroundStory = {
    Text = "Để chống lại sự bóc lột tàn nhẫn, chống lại những mất mát liên tiếp, anh sẽ che chở đôi cánh này mãi mãi trước em trai. Cho đến khi từng chiếc lông vũ biến thành bụi than, cho đến khi anh bước vào cánh cửa của cái chết trước tiên."
  },
  Skill_89780_BattleDesc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên. Nhận <Energy:[Energy:Arg2]> điểm điên cuồng. <WormholeKeywords:Siêu khoảng cách>: Xáo trộn 1 lá bài \"<DerivativeCardKeywords_107:Cánh đen>\" vào bộ bài bốc thăm, nhận <Block:[Block:Arg3]> điểm khiên."
  },
  Skill_89780_Desc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên. Castor nhận <Energy:[Energy:Arg2]> điểm Aliemus. <WormholeKeywords:Ultra>: Sử dụng 1 lá \"<DerivativeCardKeywords_107:Lông đen>\" vào bốc thăm, nhận <Block:[Block:Arg3]> điểm khiên."
