  },
  Skill_89781_AwakerSkillBackgroundStory = {
    Text = "Cánh của hắn mở ra, như một chiếc khiên rộng lớn, mỗi chiếc lông đều kết nối với xương cứng cáp, lắc lư trên đầu bạn. \n Bóng tối màu đen đó bao phủ bạn, che giấu mọi ánh sáng mặt trời, gió mưa và thương tổn, tạo ra một bầu trời an toàn. \n \"Đừng chạm vào nó, hãy để những lời nguyền tối tăm này, trả lại tất cả cho ngực của kẻ gây hại.\""
  },
  Skill_89781_Desc_0 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên, <WeaknessIconKeywords:Điểm yếu> tất cả kẻ địch trong 1 lượt. <WormholeKeywords:Ultra>: Sử dụng 1 lá \"<DerivativeCardKeywords_107:Lông đen>\" vào bốc thăm, nhận <Block:[Block:Arg3]> điểm khiên."
  },
  Skill_89781_Desc_2 = {
    Text = "Nhận <Block:[Block:Arg1]> điểm khiên, <WeaknessIconKeywords:Điểm yếu> tất cả kẻ địch trong 1 lượt, có mỗi 1 lá \"<DerivativeCardKeywords_107:Lông đen>\" trong tay sẽ nhận <Energy:[Energy:Arg2]> điểm Aliemus. <WormholeKeywords:Ultra>: Sử dụng 1 lá \"<DerivativeCardKeywords_107:Lông đen>\" vào bốc thăm, nhận <Block:[Block:Arg3]> điểm khiên."
