  },
  Skill_89782_AwakerSkillBackgroundStory = {
    Text = "Anh ấy không phải là người dễ chịu đựng, đôi cánh đó cũng có thể thổi lên cơn cuồng nộ. \n Tất cả thịt máu sẽ bị những chiếc răng sắc của gió xé nát, cuốn vào bụng của cái chết. \n Nhưng không cần phải sợ, anh ấy sẽ đặt tên của bạn vào con mắt của cơn bão, nơi yên tĩnh nhất ở giữa."
  },
  Skill_89782_Desc_0 = {
    Text = "Gây <Damage:[Damage:Arg1]> sát thương mỗi [Arg2] lần, sát thương chí mạng tạm thời của các đồng minh khác tăng [Arg3]%. <WormholeKeywords:Ultra>: Sử dụng 1 lá \"<DerivativeCardKeywords_107:Lông đen>\" vào bốc thăm, nhận <Block:[Block:Arg4]> điểm khiên."
  },
  Skill_89782_Desc_2 = {
    Text = "Gây ra <Damage:[Damage:Arg1]> điểm sát thương [Arg2] lần, sát thương chí mạng tạm thời của các đồng minh khác tăng lên [Arg3]%. Trong lượt này, mỗi lần chơi 1 lá\"<DerivativeCardKeywords_107:Lông đen>\" giá trị Điểm tính toán giảm 1. <WormholeKeywords:Chuẩn tinh>: Xáo trộn 1 lá\"<DerivativeCardKeywords_107:Lông đen>\" vào rút bài từ bộ bài, nhận <Block:[Block:Arg4]> điểm lá chắn."
