  },
  Skill_95811_AwakerSkillBackgroundStory = {
    Text = "Giấy của thiệp mời được làm từ làn da mềm mại. Trang trí của thiệp mời được làm từ hộp sọ mịn màng. Chữ viết trên thiệp mời được làm từ máu tươi. Chữ ký trên thiệp mời đến từ vị chủ nhân nhiệt tình của dinh thự. \n Doresain gửi đến bạn lời mời chân thành, mời bạn đến tham dự bữa tiệc lớn dành cho các bạn."
  },
  Skill_95811_Desc_0 = {
    Text = "Doresain nhận <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Nhận [Power:Arg2] điểm <PowerIconKeywords:sức mạnh>, sát thương do Doresain gây ra được hưởng thêm [Arg3]% tăng sức mạnh. Sau lần Giết đầu tiên mỗi lượt của Doresain, gây <FixedDamage:Sát Thương Thuần Túy> bằng 50% sát thương tràn lên các kẻ địch khác."
  },
  Skill_95811_Desc_15 = {
    Text = "Doresain nhận <Energy:[Energy:Arg1]> điểm điên cuồng. <ExaltIconKeywords:Khai mở linh trí>: Nhận [Power:Arg2] điểm <PowerIconKeywords:sức mạnh>, sát thương do Doresain gây ra được hưởng thêm [Arg3]% tăng sức mạnh. Gây <FixedDamage:Sát Thương Thuần Túy> bằng [Arg4]% sinh lực hiện tại lên tất cả kẻ địch. Sau lần Giết đầu tiên mỗi lượt của Doresain, gây <FixedDamage:Sát Thương Thuần Túy> bằng 100% sát thương tràn lên các kẻ địch khác."
  },
