  Skill_95820_AwakerSkillBackgroundStory = {
    Text = "Cắn xé đi, bỏ đi lớp mặt nạ của bạn. Bỏ xuống định kiến của bạn. Bước vào sàn nhảy, ôm ấp người bạn nhảy đã ngủ say nhiều năm. \n Nó đã bao lâu chưa thấy ánh trăng đẹp? Nó đã bao lâu chưa nghe những lời tình cảm dịu dàng? \n Nghe này, nó đang khao khát bạn, như bạn đang khao khát nó. \n Cắn xé đi, tiêu thụ đi. Trong bữa tiệc thịnh soạn vô song này, sinh linh và người chết hoàn thành sự thăng hoa chung của họ."
  },
  Skill_95820_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ> :<DerivativeCardKeywords_110:>Tỷ lệ chí mạng của lần bùng nổ điên cuồng này tăng thêm +[Arg2]%, nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>.] Gây <Damage:[Damage:Arg3]> điểm thương lên kẻ thù có sinh lực thấp nhất, nhận [Arg4]% tăng cường lực lượng, mỗi khi mục tiêu mất 1% sinh lực, sát thương cuối cùng của lần bùng nổ điên cuồng này tăng thêm 3%. Nếu hiện tại có 3 <CarcassKeywords:tàn dư>, sẽ tiêu thụ chúng, hồi phục <Heal:[Heal:Arg5]> điểm sinh lực và làm cho sát thương chí mạng nhận được trong lần bùng nổ điên cuồng này gấp đôi(hiện tại có [Arg6]/3 <CarcassKeywords:tàn dư>)."
  },
  Skill_95820_BattleDesc_3 = {
    Text = "[<DevouredIconKeywords:tiêu thụ> :<DerivativeCardKeywords_114:>Tỷ lệ chí mạng của bùng nổ điên cuồng này +[Arg2]%, nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>.] Gây <Damage:[Damage:Arg3]> điểm thương cho kẻ địch có sinh lực thấp nhất, nhận [Arg4]% tăng cường lực lượng, mỗi khi mục tiêu mất 1% sinh lực, sát thương cuối cùng của bùng nổ điên cuồng này sẽ tăng 3%. Nếu hiện tại có 3 <CarcassKeywords:tàn dư>, sẽ tiêu thụ chúng, hồi phục <Heal:[Heal:Arg5]> điểm sinh lực và làm cho sát thương chí mạng nhận được trong bùng nổ điên cuồng này gấp đôi(hiện tại có [Arg6]/3 <CarcassKeywords:tàn dư>)."
  },
  Skill_95820_Desc_0 = {
    Text = "[<DevouredIconKeywords:tiêu thụ> :<DerivativeCardKeywords_110:>Tỉ lệ chí mạng của cơn điên cuồng này +[Arg2]%, nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>.] Gây <Damage:[Damage:Arg3]> điểm thương lên kẻ địch có sinh lực thấp nhất, nhận [Arg4]% tăng sát thương, mỗi khi mục tiêu mất 1% sinh lực, sát thương cuối cùng của cơn điên cuồng này sẽ tăng thêm 3%. Nếu hiện tại có 3 <CarcassKeywords:tàn dư>, thì sẽ tiêu thụ chúng, hồi phục <Heal:[Heal:Arg5]> điểm sinh lực và tăng gấp đôi sát thương chí mạng nhận được từ cơn điên cuồng này."
  },
  Skill_95820_Desc_3 = {
    Text = "[<DevouredIconKeywords:tiêu thụ> :<DerivativeCardKeywords_114:>Tỉ lệ chí mạng của đợt điên cuồng này +[Arg2]%, nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>.] Gây <Damage:[Damage:Arg3]> điểm thương cho kẻ thù có sinh lực thấp nhất, nhận [Arg4]% tăng cường lực lượng, mục tiêu mỗi khi mất 1% sinh lực thì sát thương cuối cùng của đợt điên cuồng này sẽ tăng thêm 3%. Nếu hiện tại có 3 <CarcassKeywords:tàn dư> thì sẽ tiêu thụ chúng, hồi phục <Heal:[Heal:Arg5]> điểm sinh lực và làm cho sát thương chí mạng nhận được trong đợt điên cuồng này được tăng gấp đôi."
  },
  Skill_95820_EffectNameList = {
    Text = "Sức mạnh, sát thương, chữa lành"
