  Skill_95820_Name = {
    Text = "Bữa tiệc thịnh soạn của sinh linh"
  },
  Skill_95820_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Tiêu thụ> :<DerivativeCardKeywords_114:>Tỷ lệ chí mạng của cơn điên cuồng bùng phát này +[Arg2]%, nhận [Power:Arg1] điểm<PowerIconKeywords:lực lượng>.] Tỷ lệ chí mạng của cơn điên cuồng bùng phát này + 25%, sát thương cơ bản tăng 50%. Gây <Damage:[Damage:Arg7]> điểm thương cho kẻ địch có sinh lực thấp nhất, nhận [Arg4]% lực lượng tăng cường, sát thương cuối cùng gây ra bởi cơn điên cuồng bùng phát này tăng 100%, mỗi khi mục tiêu mất 1% sinh lực sẽ tăng thêm 3%. Nếu hiện tại có 3 [Phế tích], sẽ tiêu thụ chúng, hồi phục <Heal:[Heal:Arg5]> điểm sinh lực và làm cho sát thương chí mạng nhận được trong cơn điên cuồng bùng phát này tăng gấp đôi(hiện có [Arg6]/3 Phế tích)."
  },
