  Skill_98984_AwakerSkillBackgroundStory = {
    Text = "Đừng sợ ánh nhìn của tôi, hãy đến với tôi, lại gần tôi... \nTrong thế giới huyền ảo được tạo ra bởi cây cọ, hãy để tôi trao cho bạn vẻ đẹp tối thượng."
  },
  Skill_98984_Desc_0 = {
    Text = "[<DevouredIconKeywords:Nuốt chửng>: Lệnh thẻ tiếp theo trong lượt này tiêu thụ số học -2.]Nhận [Power:Arg1] điểm <PowerIconKeywords:sức mạnh>. Trong lượt này, sát thương cuối cùng, khiên, hồi phục cuộc sống của những người đánh thức khác từ sự bộc phát Aliemus sẽ tăng [Arg2]%. <FaxianKeywords:Khám phá> 3 kỹ năng từ người đánh thức ra trận có <Chuanggoukeyin:Dấu ấn sáng tạo>, chọn 1 thẻ đưa vào tay và trao cho nó các tính năng <DepleteIconKeywords:tiêu hao> và <RetainIconKeywords:bảo lưu>."
  },
  Skill_98984_Desc_2 = {
    Text = "[<DevouredIconKeywords:nuốt chửng> :Thẻ lệnh tiếp theo được đánh ra trong lượt này sẽ giảm tiêu thụ sức tính toán -2.]Nhận [Power:Arg1] điểm <PowerIconKeywords:lực lượng>. Tăng [Arg2]% cho sát thương cuối cùng, lá chắn và hồi phục sinh lực gây ra bởi sự bùng nổ điên cuồng của các thân thể được đánh thức khác trong lượt này. <FaxianKeywords:Phát hiện> 3 thẻ lệnh của các thân thể chiến đấu có <Chuanggoukeyin:Khắc ấn sáng tạo>, chọn 1 thẻ để đưa vào tay và gán cho nó <DepleteIconKeywords:tiêu thụ> và <RetainIconKeywords:giữ lại>."
  },
