  },
  Skill_98989_Desc_15 = {
    Text = "Pickman nhận <Energy:[Energy:Arg1]> điểm Cuồng Khí. <ExaltIconKeywords:Linh Tri Giác Tỉnh>: Nhận 1 tầng <Kuangxiang:Cuồng Tưởng>. Mỗi khi Pickman nhận 1 tầng <Chuangyi:Sáng Tạo>, <EmbryoFusionIconKeywords:Phôi Thai Dung Hợp>+ [Arg2].\"Hội Ảnh Mô Hình\" tạo vật Hoàng Kim tăng số lượt duy trì từ 1 lượt lên 2 lượt."
