  Skill_98990_AwakerSkillBackgroundStory = {
    Text = "Bạn đã từng thấy màu sắc thật sự chưa?\nKhông phải là màu sắc hiền hòa, mà là sự điên cuồng xâm lấn, thẩm thấu vào tủy xương.\nMỗi một nét màu đều mang lại sự run rẩy ăn mòn và sự cuồng si, đó mới là vẻ đẹp mà họa sĩ tìm kiếm."
  },
  Skill_98990_BattleDesc = {
    Text = "Gây <Damage:[Damage:Arg1]> điểm thương tất định chí mạng cho tất cả kẻ địch [Arg3] lần, mỗi lần gây thương tạm thời giảm [Exhaustion:Arg2] điểm <ExhaustionIconKeywords:Sức mạnh> của mục tiêu và nhận [Power:Arg2] điểm <PowerIconKeywords:Sức mạnh tạm thởi>. Mỗi lần hiệu ứng <FaxianKeywords:Phát hiện> được kích hoạt trong lượt này, Giá trị Điểm tính toán cơ bản của thẻ bài này giảm 1, nếu đã kích hoạt \"Bùng nổ cảm hứng!\" sẽ gây thêm 2 lần thương."
  },
  Skill_98990_Desc = {
